/**
 * پنل آموزشی جامع
 * طراح: نادر اکشیک
 *
 * یک Cloudflare Worker کامل شامل:
 *  - پنل معلم (ورود/خروج، تغییر رمز عبور، تم روشن/تاریک)
 *  - مدیریت دانش‌آموزان با لینک اختصاصی
 *  - آزمون‌سازی با انواع سوال (تشریحی، چهارگزینه‌ای، صحیح/غلط، کوتاه‌پاسخ)
 *  - سربرگ کامل آزمون (نام مدرسه، نام آموزگار، نام آزمون، مدت زمان آزمون به دقیقه)
 *  - انتخاب مقطع تحصیلی (ابتدایی توصیفی / متوسطه اول و دوم نمره‌ای)
 *  - تایمر معکوس برای دانش‌آموز (Countdown Timer)
 *  - ویرایشگر غنی سوال (علائم ریاضی، کسر، تقسیم چکشی، اشکال هندسی SVG، عکس)
 *  - صفحه آزمون دانش‌آموز با سوال امنیتی و نمایش تایمر
 *  - تصحیح و بازخورد:
 *    * ابتدایی: توصیفی (خیلی خوب، خوب، قابل‌قبول، نیاز به تلاش)
 *    * متوسطه اول و دوم: نمره‌ای (عددی با اعشار) - نمره کل از 20
 *  - پاسخنامه‌ها با وضعیت‌های مختلف
 *  - برنامه هفتگی با خروجی Word/PDF/چاپ و ذخیره در KV
 *  - جدول‌ساز حرفه‌ای با خروجی اکسل RTL و میانگین‌گیری
 *  - اسکنر حرفه‌ای (مشابه CamScanner) با فیلترهای متنوع
 *  - کاهش حجم عکس با کیفیت و فرمت‌های مختلف
 *  - برش عکس با نسبت‌های مختلف (پشتیبانی از لمس برای گوشی)
 *  - تبدیل PDF به عکس با انتخاب صفحات و DPI
 *  - چت AI با Groq (حالت‌های مختلف)
 *  - ترجمه متن با MyMemory
 *  - ذخیره‌سازی در Cloudflare KV (binding: EXAM_KV)
 */

const APP_TITLE = "پنل آموزشی جامع";
const APP_DESIGNER = "طراح: نادر اکشیک";

const DEFAULT_META = {
  school: "",
  teacher: "",
  examName: "",
  examDuration: "30",
  gradeLevel: "elementary",
};

const QUESTION_TYPES = {
  descriptive: "تشریحی",
  multiple: "چهارگزینه‌ای",
  truefalse: "صحیح / غلط",
  short: "کوتاه‌پاسخ",
};

/* اسکریپت مشترک حالت تمام‌صفحه برای کلاس آنلاین و وبینار (هم پنل معلم، هم صفحه دانش‌آموز/شرکت‌کننده) —
   یک کانتینر مشخص را هم با Fullscreen API واقعی (در صورت پشتیبانی مرورگر) و هم با یک کلاس CSS پوششی
   (برای مرورگرهایی مثل Safari موبایل که از Fullscreen API روی عنصر دلخواه پشتیبانی نمی‌کنند) تمام‌صفحه می‌کند،
   و یک دکمه‌ی بازگشت برای خروج از آن فراهم می‌کند. */
const CLS_FULLSCREEN_JS = `
function clsSetupFullscreen(containerId, toggleBtnId, backBtnId){
  var el=document.getElementById(containerId);
  var toggleBtn=document.getElementById(toggleBtnId);
  var backBtn=backBtnId?document.getElementById(backBtnId):null;
  if(!el||!toggleBtn)return;
  function isActive(){return el.classList.contains('cls-fullscreen-active');}
  function updateUi(){
    toggleBtn.textContent=isActive()?'✖️ خروج از تمام‌صفحه':'🖥️ تمام‌صفحه';
    if(backBtn)backBtn.classList.toggle('hidden',!isActive());
  }
  function bumpResize(){setTimeout(function(){try{window.dispatchEvent(new Event('resize'));}catch(e){}},60);}
  function enter(){
    el.classList.add('cls-fullscreen-active');
    var req=el.requestFullscreen||el.webkitRequestFullscreen||el.msRequestFullscreen;
    if(req){try{req.call(el).catch(function(){});}catch(e){}}
    updateUi();bumpResize();
  }
  function exit(){
    el.classList.remove('cls-fullscreen-active');
    if(document.fullscreenElement||document.webkitFullscreenElement){
      var ex=document.exitFullscreen||document.webkitExitFullscreen||document.msExitFullscreen;
      if(ex){try{ex.call(document).catch(function(){});}catch(e){}}
    }
    updateUi();bumpResize();
  }
  toggleBtn.onclick=function(){isActive()?exit():enter();};
  if(backBtn)backBtn.onclick=function(){exit();};
  ['fullscreenchange','webkitfullscreenchange'].forEach(function(ev){
    document.addEventListener(ev,function(){
      if(!document.fullscreenElement && !document.webkitFullscreenElement && isActive()){
        el.classList.remove('cls-fullscreen-active');
        updateUi();bumpResize();
      }
    });
  });
  updateUi();
}
`;

/* ------------------------- ابزارهای کمکی ------------------------- */

function json(data, status = 200, headers = {}) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", ...headers },
  });
}

/* فراخوانی یک سرویس هوش مصنوعی سازگار با فرمت OpenAI (chat/completions) با تلاش مجدد خودکار برای خطاهای موقت (503/429) */
async function callOpenAiCompatible(apiUrl, apiKey, model, messages, maxTokens) {
  const RETRYABLE_STATUSES = [503, 429];
  const MAX_ATTEMPTS = 3;
  let lastErr = null, lastStatus = 500;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      const aiRes = await fetch(apiUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json", "Authorization": "Bearer " + apiKey },
        body: JSON.stringify({ model, messages, max_tokens: maxTokens }),
      });
      if (!aiRes.ok) {
        const errText = await aiRes.text();
        lastErr = errText;
        lastStatus = aiRes.status;
        if (RETRYABLE_STATUSES.includes(aiRes.status) && attempt < MAX_ATTEMPTS) {
          await new Promise((r) => setTimeout(r, attempt * 1200));
          continue;
        }
        return { ok: false, error: lastErr, status: lastStatus };
      }
      const aiData = await aiRes.json();
      const content = aiData.choices?.[0]?.message?.content || "";
      return { ok: true, content };
    } catch (e) {
      lastErr = "Error: " + e.message;
      lastStatus = 500;
      if (attempt < MAX_ATTEMPTS) { await new Promise((r) => setTimeout(r, attempt * 1200)); continue; }
      return { ok: false, error: lastErr, status: lastStatus };
    }
  }
  return { ok: false, error: lastErr || "خطای نامشخص در ارتباط با هوش مصنوعی", status: lastStatus };
}

function html(body, status = 200, headers = {}) {
  return new Response(body, {
    status,
    headers: { "content-type": "text/html; charset=utf-8", ...headers },
  });
}

function esc(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

const FA_DIGITS_SRV = ["۰", "۱", "۲", "۳", "۴", "۵", "۶", "۷", "۸", "۹"];
function toFaDigitsSrv(s) {
  return String(s == null ? "" : s).replace(/[0-9]/g, (d) => FA_DIGITS_SRV[+d]);
}

function sanitizeHtml(s) {
  return String(s == null ? "" : s)
    .replace(/<\s*\/?\s*(script|iframe|object|embed|link|meta|style)\b[^>]*>/gi, "")
    .replace(/\son[a-z]+\s*=\s*"[^"]*"/gi, "")
    .replace(/\son[a-z]+\s*=\s*'[^']*'/gi, "")
    .replace(/javascript:/gi, "");
}

function uuid() {
  return crypto.randomUUID();
}

function parseCookies(req) {
  const out = {};
  const c = req.headers.get("cookie") || "";
  c.split(";").forEach((part) => {
    const i = part.indexOf("=");
    if (i > -1) out[part.slice(0, i).trim()] = decodeURIComponent(part.slice(i + 1).trim());
  });
  return out;
}

async function sha256(text) {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(String(text)));
  return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
}

async function getTeacherHash(env) {
  return await env.EXAM_KV.get("teacher_pass");
}

async function isTeacher(req, env) {
  const stored = await getTeacherHash(env);
  if (!stored) return false;
  const cookies = parseCookies(req);
  return Boolean(cookies.t_auth && cookies.t_auth === stored);
}

/* شمارنده‌ی تعداد ثبت‌نام هر لیست حضور و غیاب، به‌صورت یک شیء واحد در کلید «attendance-counts» نگه‌داری می‌شود
   تا شمارش لیست‌ها (GET /api/teacher/attendance-links) دیگر نیازی به خواندن تک‌تک تمام رکوردهای «attendance:»
   نداشته باشد (که با زیاد شدن تعداد ثبت‌نام‌ها به‌مرور کند می‌شد). اگر این کلید هنوز ساخته نشده باشد (یعنی هنوز
   اولین محاسبه‌ی کامل روی داده‌های قدیمی انجام نشده)، این تابع کاری انجام نمی‌دهد؛ همان اولین GET بعدی، با یک
   اسکن کامل یک‌بارِ همیشگی، مقدار درست را می‌سازد و از آن به بعد دیگر لازم نیست. */
async function bumpAttendanceCount(env, linkId, delta) {
  const raw = await env.EXAM_KV.get("attendance-counts");
  if (raw === null) return;
  let counts;
  try { counts = JSON.parse(raw); } catch (e) { counts = {}; }
  const lid = linkId || "default";
  counts[lid] = Math.max(0, (counts[lid] || 0) + delta);
  await env.EXAM_KV.put("attendance-counts", JSON.stringify(counts));
}

async function getMeta(env, grade) {
  const g = clampGrade(grade);
  const raw = await env.EXAM_KV.get("meta:" + g);
  if (raw) return { ...DEFAULT_META, ...JSON.parse(raw) };
  if (g === 0) {
    // سازگاری با نسخه‌ی قدیمی که فقط یک سربرگ/آزمون سراسری داشت (بدون تفکیک پایه)
    const legacy = await env.EXAM_KV.get("meta");
    if (legacy) return { ...DEFAULT_META, ...JSON.parse(legacy) };
  }
  return { ...DEFAULT_META };
}

function clampGrade(grade) {
  const g = parseInt(grade, 10);
  return Number.isInteger(g) && g >= 0 && g <= 11 ? g : 0;
}

function gradeLevelOf(grade) {
  if (grade >= 9) return "high";
  if (grade >= 6) return "middle";
  return "elementary";
}

async function getQuestions(env, grade) {
  const g = clampGrade(grade);
  const raw = await env.EXAM_KV.get("questions:" + g);
  if (raw) return JSON.parse(raw);
  if (g === 0) {
    // سازگاری با نسخه‌ی قدیمی
    const legacy = await env.EXAM_KV.get("questions");
    if (legacy) return JSON.parse(legacy);
  }
  return [];
}

async function listStudents(env) {
  const out = [];
  let cursor;
  do {
    const res = await env.EXAM_KV.list({ prefix: "student:", cursor });
    const values = await Promise.all(res.keys.map((k) => env.EXAM_KV.get(k.name)));
    for (const v of values) {
      if (v) out.push(JSON.parse(v));
    }
    cursor = res.list_complete ? null : res.cursor;
  } while (cursor);
  out.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
  return out;
}

function getScheduleHtml(data) {
  const school = data.school || 'مدرسه';
  const year = data.year || '';
  const topic = data.topic || '';
  const principal = data.principal || '';
  const cls = data.cls || '';
  const teacher = data.teacher || '';
  const days = ['شنبه', 'یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه'];
  const zang = ['زنگ اول', 'زنگ دوم', 'زنگ سوم', 'زنگ چهارم', 'زنگ پنجم'];
  const dayColors = [
    'linear-gradient(135deg,#ff9a9e,#fecfef)',
    'linear-gradient(135deg,#fddb92,#d1fdff)',
    'linear-gradient(135deg,#a1ffce,#faffbd)',
    'linear-gradient(135deg,#e0c3fc,#8ec5fc)',
    'linear-gradient(135deg,#a8edea,#fed6e3)'
  ];
  const accentColors = ['#ef4444','#f59e0b','#10b981','#8b5cf6','#06b6d4'];
  const cellColors = ['#fef2f2','#fffbeb','#f0fdf4','#f5f3ff','#ecfeff'];
  
  let style = `<style>
    @font-face{font-family:"BNazanin";src:url(https://cdn.jsdelivr.net/gh/naderuser/bnazanin@main/BNazanin.ttf)}
    body{direction:rtl;font-family:"BNazanin",tahoma,Arial;padding:30px;background:#f8fafc}
    .header{text-align:center;padding:20px;background:#fff;color:#1e293b;border-radius:20px;margin-bottom:20px;border:1.5px solid #e2e8f0}
    .header h1{font-size:24px;margin:0 0 10px;font-weight:800;letter-spacing:.3px}.header p{margin:5px 0;font-size:14px}
    table{width:100%;border-collapse:separate;border-spacing:0;border-radius:18px;overflow:hidden;box-shadow:0 8px 24px rgba(15,23,42,.10);border:1px solid #e2e8f0}
    th{padding:14px 8px;font-size:14px;font-weight:800;text-align:center;border-bottom:2px solid #e2e8f0;border-left:1px solid #e2e8f0}
    td{padding:14px 10px;text-align:center;font-size:13px;min-height:50px;font-weight:600;color:#1e293b;border-bottom:1px solid #eef2f6;border-left:1px solid #eef2f6}
    tr:last-child td{border-bottom:none}
    .daylabel{border-right:5px solid;font-weight:800}
    .footer{text-align:center;margin-top:30px;padding:20px;border-top:2px dashed #ddd}
  </style>`;
  
  let header = `<div class="header"><h1>برنامه هفتگی</h1><p>🏫 ${esc(school)} | سال تحصیلی: ${esc(year)}</p><p>کلاس: ${esc(cls)} | آموزگار: ${esc(teacher)}</p></div>`;
  
  let table = '<table><tr><th style="background:#fff;color:#1e293b;border-bottom:none">روز / زنگ</th>';
  for (let z = 0; z < 5; z++) {
    table += `<th style="background:#f8fafc;color:#334155">🔔 ${zang[z]}</th>`;
  }
  table += '</tr>';
  
  for (let d = 0; d < 5; d++) {
    table += `<tr><td class="daylabel" style="background:${cellColors[d]};border-right-color:${accentColors[d]}">${days[d]}</td>`;
    for (let i = 1; i <= 5; i++) {
      const key = `c${d}${i}`;
      const val = (data.cells && data.cells[key]) || '&nbsp;';
      table += `<td style="background:${cellColors[d]}"><div style="min-height:40px">${val}</div></td>`;
    }
    table += '</tr>';
  }
  table += '</table>';
  
  const footer = ``;
  return `<html><head><meta charset="utf-8">${style}</head><body>${header}${table}${footer}</body></html>`;
}

function safeQuestion(q) {
  return { 
    id: q.id, 
    type: q.type, 
    rich: Boolean(q.rich), 
    text: q.text, 
    options: q.options || [], 
    image: q.image || "",
    imageWidth: q.imageWidth || 320,
    imageAlign: q.imageAlign === "center" || q.imageAlign === "left" ? q.imageAlign : "right",
    imagePos: q.imagePos === "above" ? "above" : "below",
    weight: q.weight || 1
  };
}

/* ------------------------- روتر اصلی ------------------------- */

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    const path = url.pathname;

    try {
      if (path === "/api/classroom/ws") return await handleClassroomSocket(req, env, url);
      if (path === "/api/webinar/ws") return await handleWebinarSocket(req, env, url);
      if (path === "/api/interactive/ws") return await handleInteractiveSocket(req, env, url);
      if (path === "/api/board/ws") return await handleBoardSocket(req, env, url);

      if (path === "/sw.js") return new Response(teacherServiceWorkerScript(), { headers: { "content-type": "application/javascript; charset=utf-8", "cache-control": "no-cache" } });
      if (path === "/manifest.json") {
        return new Response(JSON.stringify({
          name: APP_TITLE, short_name: APP_TITLE, start_url: "/teacher", scope: "/teacher",
          display: "standalone", background_color: "#ffffff", theme_color: "#123A5C", dir: "rtl", lang: "fa",
          icons: [
            { src: "/icon.svg", sizes: "192x192", type: "image/svg+xml" },
            { src: "/icon.svg", sizes: "512x512", type: "image/svg+xml" },
          ],
        }), { headers: { "content-type": "application/manifest+json; charset=utf-8", "cache-control": "public, max-age=86400" } });
      }
      if (path === "/icon.svg") {
        const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><rect width="512" height="512" rx="96" fill="#123A5C"/><text x="256" y="330" font-size="280" text-anchor="middle" font-family="sans-serif">🎓</text></svg>`;
        return new Response(svg, { headers: { "content-type": "image/svg+xml; charset=utf-8", "cache-control": "public, max-age=86400" } });
      }
      if (path === "/qrcode.js") return new Response(qrcodeLibScript(), { headers: { "content-type": "application/javascript; charset=utf-8", "cache-control": "public, max-age=31536000, immutable" } });
      if (path.startsWith("/fonts/") && path.endsWith(".ttf")) {
        const fontKey = path.slice("/fonts/".length, -4);
        const b64 = CERT_FONT_B64[fontKey];
        if (b64) {
          const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
          return new Response(bytes, { headers: { "content-type": "font/ttf", "cache-control": "public, max-age=31536000, immutable" } });
        }
        return new Response("Font not found", { status: 404 });
      }

      if (path.startsWith("/api/")) return await handleApi(req, env, url, path);

      if (path.startsWith("/s/")) {
        const id = decodeURIComponent(path.slice(3));
        return await studentPage(env, id);
      }

      if (path.startsWith("/info/")) {
        const id = decodeURIComponent(path.slice(6));
        return await infoLinkPage(env, id);
      }

      if (path.startsWith("/w/")) {
        const id = decodeURIComponent(path.slice(3));
        return await workSheetPage(env, id);
      }

      if (path.startsWith("/class/")) {
        const id = decodeURIComponent(path.slice(7)).replace(/\/+$/, "");
        // این دو مسیر ویژه زیر همان پیشوند «/class/» ثبت می‌شوند (نه یک مسیر کاملاً جدا)
        // چون میزبان فعلی (RunFlare) فقط برای چند پیشوند مشخص (از جمله /class/) مسیر صریح تعریف کرده
        // و مسیرهای کاملاً جدید ممکن است قبل از رسیدن به منطق اصلی با «مسیر یافت نشد» مواجه شوند.
        if (id === "webinar") return await webinarJoinPage(env);
        if (id === "attendance") return await attendancePage(env, null);
        if (id.startsWith("attendance/")) return await attendancePage(env, id.slice("attendance/".length));
        if (id.startsWith("board/")) return await studentBoardPage(env, id.slice("board/".length));
        if (id.startsWith("interactive/")) return await studentInteractivePage(env, id.slice("interactive/".length));
        return await studentClassPage(env, id);
      }

      if (path === "/webinar" || path === "/webinar/") {
        return await webinarJoinPage(env);
      }

      if (path === "/attendance" || path === "/attendance/") {
        return await attendancePage(env, null);
      }

      if (path.startsWith("/g/")) {
        const id = decodeURIComponent(path.slice(3));
        return await htmlContentPage(env, id);
      }

      if (path.startsWith("/cert/")) {
        const rest = decodeURIComponent(path.slice(6)).replace(/\/+$/, "");
        const parts = rest.split("/");
        return await issuedCertPage(env, parts[0] || "", parts[1] || "");
      }

      if (path === "/teacher" || path === "/teacher/") return html(teacherPage(), 200, { "cache-control": "no-store" });

      if (path === "/") return Response.redirect(new URL("/teacher", url.origin).toString(), 302);

      return html(notFoundPage(), 404);
    } catch (err) {
      return json({ ok: false, error: String(err && err.message ? err.message : err) }, 500);
    }
  },
};

/* ------------------------- کلاس آنلاین (Durable Object) -------------------------
 * برای فعال شدن این بخش باید در wrangler.toml موارد زیر اضافه شود:
 *
 * [[durable_objects.bindings]]
 * name = "CLASSROOM"
 * class_name = "ClassRoom"
 *
 * [[migrations]]
 * tag = "v1"
 * new_sqlite_classes = ["ClassRoom"]
 *
 * توجه: از مدتی پیش Durable Objects (نوع SQLite) روی پلن رایگان Workers هم در دسترس
 * است و نیازی به پلن Paid نیست؛ فقط باید حتماً از "new_sqlite_classes" (نه
 * "new_classes") در migrations استفاده شود تا با پلن رایگان سازگار باشد.
 * -------------------------------------------------------------------------------- */

async function handleClassroomSocket(req, env, url) {
  return await handleRoomSocket(req, env, url, "main", "کلاس آنلاین", false);
}

async function handleWebinarSocket(req, env, url) {
  return await handleRoomSocket(req, env, url, "webinar", "وبینار", true);
}

// تماس تعاملی: یک اتاق کاملاً مستقل و جدا از کلاس آنلاین (Durable Object جدا با نام «interactive»)؛
// دوربین معلم و همه‌ی دانش‌آموزان هم‌زمان به‌صورت ردیف تصویر بالای صفحه و تخته/چت زیر آن است.
async function handleInteractiveSocket(req, env, url) {
  return await handleRoomSocket(req, env, url, "interactive", "تماس تعاملی", false);
}

// تخته آنلاین: اتاق کاملاً مستقل از کلاس آنلاین و وبینار (Durable Object جدا با نام «board»)، دسترسی دانش‌آموز از طریق همان لینک اختصاصی خودش (نه لینک عمومی مثل وبینار)
async function handleBoardSocket(req, env, url) {
  return await handleRoomSocket(req, env, url, "board", "تخته آنلاین", false);
}

// openParticipation=true یعنی هر کسی با لینک واحد و فقط با وارد کردن نام می‌تواند وارد شود (بدون نیاز به فهرست دانش‌آموزان)
async function handleRoomSocket(req, env, url, roomName, label, openParticipation) {
  const role = url.searchParams.get("role") === "teacher" ? "teacher" : "student";

  // مسیر تشخیصی: بدون WebSocket، فقط بررسی می‌کند که آیا اتصال باید موفق باشد یا نه
  // و در صورت خطا، دلیل دقیق را برمی‌گرداند (برای نمایش پیام مشخص به‌جای «قطع شد»).
  if (url.searchParams.get("check") === "1") {
    if (role === "teacher") {
      if (!(await isTeacher(req, env))) return json({ ok: false, error: "برای " + label + " باید ابتدا در پنل معلم وارد شوید." }, 401);
    } else if (openParticipation) {
      const name = (url.searchParams.get("name") || "").trim();
      if (!name) return json({ ok: false, error: "لطفاً نام و نام خانوادگی را وارد کنید." }, 400);
    } else {
      const id = url.searchParams.get("id") || "";
      const rec = id ? await env.EXAM_KV.get("student:" + id) : null;
      if (!rec) return json({ ok: false, error: "این لینک " + label + " معتبر نیست. لینک را از پنل معلم دوباره کپی کنید." }, 404);
    }
    if (!env.CLASSROOM) {
      return json({ ok: false, error: label + " روی این ورکر فعال نشده است. باید در wrangler.toml بخش durable_objects و migrations برای ClassRoom اضافه و دوباره deploy شود." }, 500);
    }
    return json({ ok: true });
  }

  if (req.headers.get("upgrade") !== "websocket") {
    return json({ ok: false, error: "این مسیر فقط برای اتصال WebSocket است" }, 400);
  }

  if (role === "teacher") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
  } else if (openParticipation) {
    const name = (url.searchParams.get("name") || "").trim();
    if (!name) return json({ ok: false, error: "نام و نام خانوادگی الزامی است" }, 400);
  } else {
    const id = url.searchParams.get("id") || "";
    const rec = await env.EXAM_KV.get("student:" + id);
    if (!rec) return json({ ok: false, error: "لینک نامعتبر است" }, 404);
  }

  if (!env.CLASSROOM) {
    return json({ ok: false, error: label + " روی این ورکر فعال نشده (Durable Object تنظیم نشده)" }, 500);
  }

  const roomId = env.CLASSROOM.idFromName(roomName);
  const stub = env.CLASSROOM.get(roomId);
  return stub.fetch(req);
}

export class ClassRoom {
  constructor(state, env) {
    this.state = state;
    this.env = env;
    this.sessions = new Map(); // ws -> { role, id, name }
    this.strokes = []; // تاریخچه تخته هوشمند برای سینک اعضای جدید
    this.chat = []; // آخرین پیام‌های چت
    this.boardBg = null; // صفحه‌ی PDF فعلی روی تخته (data URL) یا null
    this.boardBgW = 900;
    this.boardBgH = 560;
    this.allowedSpeakers = new Set(); // شناسه‌ی دانش‌آموزانی که معلم اجازه‌ی صحبت (میکروفون) به آن‌ها داده (فقط تخته آنلاین)
  }

  async fetch(req) {
    const url = new URL(req.url);
    if (req.headers.get("upgrade") !== "websocket") {
      return new Response("Expected WebSocket", { status: 400 });
    }
    const kind = url.pathname === "/api/webinar/ws" ? "webinar" : (url.pathname === "/api/board/ws" ? "board" : (url.pathname === "/api/interactive/ws" ? "interactive" : "classroom"));
    this.kind = kind;
    const role = url.searchParams.get("role") === "teacher" ? "teacher" : "student";
    const id = url.searchParams.get("id") || "";
    const name = (url.searchParams.get("name") || (role === "teacher" ? "معلم" : "دانش‌آموز")).slice(0, 60);

    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);
    server.accept();

    const session = { role, id, name };
    this.sessions.set(server, session);

    server.send(JSON.stringify({
      type: "init",
      role,
      strokes: this.strokes,
      boardBg: this.boardBg,
      boardBgW: this.boardBgW,
      boardBgH: this.boardBgH,
      chat: this.chat.slice(-50),
      participants: this.participantList(),
    }));

    this.broadcast({ type: "presence", event: "join", role, name, participants: this.participantList() }, server);

    server.addEventListener("message", (evt) => {
      let msg;
      try { msg = JSON.parse(evt.data); } catch { return; }
      this.handleMessage(server, session, msg);
    });

    const onClose = () => {
      if (!this.sessions.has(server)) return;
      this.sessions.delete(server);
      if ((this.kind === "board" || this.kind === "interactive") && session.role === "student" && session.id) this.allowedSpeakers.delete(session.id);
      this.broadcast({ type: "presence", event: "leave", role: session.role, name: session.name, participants: this.participantList() });
    };
    server.addEventListener("close", onClose);
    server.addEventListener("error", onClose);

    return new Response(null, { status: 101, webSocket: client });
  }

  participantList() {
    return Array.from(this.sessions.values()).map((s) => ({ role: s.role, name: s.name, id: s.id }));
  }

  handleMessage(sender, session, msg) {
    if (!msg || typeof msg !== "object") return;

    // وبینار تخته آنلاین ندارد؛ این پیام‌ها فقط برای اتاق کلاس آنلاین معتبرند (محافظتی، چون رابط کاربری وبینار اصلاً این دکمه‌ها را ندارد)
    if (this.kind === "webinar" && (msg.type === "draw" || msg.type === "clear" || msg.type === "board-bg" || msg.type === "undo")) return;

    // در وبینار فقط معلم تصویر می‌فرستد؛ شرکت‌کنندگان فقط صدا/چت/بلندکردن دست دارند (محافظتی سمت سرور)
    if (this.kind === "webinar" && session.role === "student" && (msg.type === "video-frame" || msg.type === "video-stop")) return;

    // تخته آنلاین کاملاً مستقل از کلاس آنلاین است: هیچ تصویر/دوربینی (نه معلم، نه دانش‌آموز) ندارد؛
    // دانش‌آموز فقط وقتی می‌تواند صدا بفرستد که معلم صراحتاً به او اجازه‌ی صحبت داده باشد (این کد: this.allowedSpeakers)
    if (this.kind === "board" && (msg.type === "video-frame" || msg.type === "video-stop")) return;
    if (this.kind === "board" && session.role === "student" && msg.type === "audio" && !this.allowedSpeakers.has(session.id)) return;

    // تماس تعاملی: دانش‌آموز فقط بعد از اینکه معلم صراحتاً درخواستش را تأیید کرد (this.allowedSpeakers)
    // می‌تواند صدا/تصویر بفرستد و وارد تماس شود؛ تا قبل از تأیید، پیام‌های صدا/تصویر او نادیده گرفته می‌شود.
    if (this.kind === "interactive" && session.role === "student" && (msg.type === "audio" || msg.type === "video-frame") && !this.allowedSpeakers.has(session.id)) return;

    // فقط معلم اجازه‌ی رسم روی تخته هوشمند و پخش صدا را دارد
    if (msg.type === "draw" && session.role === "teacher") {
      this.strokes.push(msg.stroke);
      if (this.strokes.length > 3000) this.strokes.splice(0, 1000);
      this.broadcast({ type: "draw", stroke: msg.stroke }, sender);
      return;
    }

    if (msg.type === "clear" && session.role === "teacher") {
      this.strokes = [];
      this.broadcast({ type: "clear" }, sender);
      return;
    }

    // واگرد (Undo): آخرین N مورد از تاریخچه‌ی ترسیم را حذف می‌کند (فقط معلم)
    if (msg.type === "undo" && session.role === "teacher") {
      const n = Math.max(1, Math.min(1000, parseInt(msg.count, 10) || 1));
      this.strokes.splice(-n, n);
      this.broadcast({ type: "undo", count: n }, sender);
      return;
    }

    if (msg.type === "board-bg" && session.role === "teacher") {
      if (msg.data && msg.data.length > 4_000_000) {
        try { sender.send(JSON.stringify({ type: "error", message: "حجم تصویر صفحه‌ی PDF برای ارسال زنده خیلی زیاد است." })); } catch {}
        return;
      }
      this.boardBg = msg.data || null;
      this.boardBgW = msg.w || 900;
      this.boardBgH = msg.h || 560;
      this.strokes = []; // با تغییر صفحه‌ی PDF، یادداشت‌های قبلی روی صفحه‌ی قبل پاک می‌شود
      this.broadcast({ type: "board-bg", data: this.boardBg, w: this.boardBgW, h: this.boardBgH }, sender);
      return;
    }

    // صدا/تصویر زنده: هم معلم و هم دانش‌آموزان اجازه دارند مایکروفون/دوربین خود را روشن کنند؛
    // برای هر پیام، هویت فرستنده (نام/نقش/شناسه) هم اضافه می‌شود تا گیرنده‌ها بدانند این جریان مال کیست.
    if (msg.type === "audio") {
      // چانک صوتی فشرده (base64) برای پخش تقریباً زنده برای بقیه‌ی حاضرین
      this.broadcastStream({ type: "audio", data: msg.data, mime: msg.mime || "audio/webm", from: session.name, role: session.role, id: session.id }, sender);
      return;
    }

    if (msg.type === "video-frame") {
      // فریم تصویر (JPEG با کیفیت پایین) برای تماس تصویری ساده‌ی زنده
      this.broadcastStream({ type: "video-frame", data: msg.data, from: session.name, role: session.role, id: session.id }, sender);
      return;
    }

    if (msg.type === "video-stop") {
      this.broadcast({ type: "video-stop", from: session.name, role: session.role, id: session.id }, sender);
      return;
    }

    if (msg.type === "chat") {
      const entry = {
        from: session.name,
        role: session.role,
        text: String(msg.text || "").slice(0, 1000),
        ts: Date.now(),
      };
      if (!entry.text) return;
      this.chat.push(entry);
      if (this.chat.length > 200) this.chat.splice(0, 100);
      this.broadcast({ type: "chat", entry });
      return;
    }

    if (msg.type === "file") {
      // ارسال فایل (عکس/سند) بین معلم و دانش‌آموزان - فقط زنده پخش می‌شود، در تاریخچه ذخیره نمی‌شود
      const name = String(msg.name || "file").slice(0, 200);
      const mime = String(msg.mime || "application/octet-stream").slice(0, 100);
      const data = String(msg.data || "");
      if (!data || data.length > 3_000_000) return; // حداکثر ~2 مگابایت فایل (بعد از base64)
      this.broadcast({ type: "file", from: session.name, role: session.role, name, mime, data, ts: Date.now() });
      return;
    }

    if (msg.type === "raise-hand" && session.role === "student") {
      this.broadcast({ type: "raise-hand", name: session.name });
      return;
    }

    // درخواست اجازه‌ی صحبت در تخته آنلاین (دانش‌آموز) و پاسخ معلم (اجازه/لغو اجازه)
    if (msg.type === "speak-request" && session.role === "student") {
      this.broadcast({ type: "speak-request", id: session.id, name: session.name });
      return;
    }
    if (msg.type === "speak-grant" && session.role === "teacher" && msg.id) {
      this.allowedSpeakers.add(String(msg.id));
      this.broadcast({ type: "speak-grant", id: msg.id });
      return;
    }
    if (msg.type === "speak-revoke" && session.role === "teacher" && msg.id) {
      this.allowedSpeakers.delete(String(msg.id));
      this.broadcast({ type: "speak-revoke", id: msg.id });
      return;
    }
  }

  broadcast(payload, exclude) {
    const data = JSON.stringify(payload);
    for (const ws of this.sessions.keys()) {
      if (ws === exclude) continue;
      try { ws.send(data); } catch { /* اتصال قطع شده - نادیده گرفته می‌شود */ }
    }
  }

  // برای داده‌های زنده‌ی پرتکرار (فریم تصویر دوربین/چانک صدا): اگر یکی از گیرنده‌ها اینترنت کندی داشته باشد،
  // پیام‌های ارسالی به همان یک نفر پشت سر هم در صف سوکت او تلنبار می‌شوند (چون این‌ها به‌ترتیب و بدون افت روی
  // یک WebSocket ارسال می‌شوند)؛ نتیجه‌اش این است که آن یک دانش‌آموز با فاصله‌ی چند دقیقه‌ای تصویر/صدا را
  // می‌بیند و این فاصله هیچ‌وقت جبران نمی‌شود چون فریم‌های تازه‌تر همچنان سریع‌تر از آن اضافه می‌شوند.
  // راه‌حل: برای هر گیرنده به‌صورت جداگانه، صف ارسال (bufferedAmount) را چک می‌کنیم و اگر پر بود، همین یک
  // فریم را فقط برای همان گیرنده‌ی کند رد می‌کنیم (بقیه‌ی گیرنده‌ها که وضعشان خوب است طبق معمول دریافت می‌کنند).
  broadcastStream(payload, exclude, maxBuffered = 131072) {
    const data = JSON.stringify(payload);
    for (const ws of this.sessions.keys()) {
      if (ws === exclude) continue;
      try {
        if (typeof ws.bufferedAmount === "number" && ws.bufferedAmount > maxBuffered) continue; // این گیرنده کند است؛ این فریم را رد کن، صف او را باز نگه دار
        ws.send(data);
      } catch { /* اتصال قطع شده - نادیده گرفته می‌شود */ }
    }
  }
}

/* ------------------------- API ------------------------- */

async function handleApi(req, env, url, path) {
  const method = req.method;

  /* --- دریافت و ارسال اطلاعات: پشتیبانی از ارسال بین دو پنل جدا روی کلودفلر (CORS) --- */
  const INFO_CORS_HEADERS = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
    "Access-Control-Allow-Headers": "content-type",
  };
  if (path.startsWith("/api/info/") && method === "OPTIONS") {
    return new Response(null, { status: 204, headers: INFO_CORS_HEADERS });
  }

  /* --- تشخیصی موقت: بررسی وجود کلید Gemini (بدون افشای مقدار) --- */
  if (path === "/api/debug/env-check" && method === "GET") {
    return json({
      hasGeminiKey: typeof env.GEMINI_API_KEY === "string" && env.GEMINI_API_KEY.length > 0,
      geminiKeyLength: env.GEMINI_API_KEY ? env.GEMINI_API_KEY.length : 0,
      hasGroqKey: typeof env.GROQ_API_KEY === "string" && env.GROQ_API_KEY.length > 0,
      groqKeyLength: env.GROQ_API_KEY ? env.GROQ_API_KEY.length : 0,
      hasTokenHarborKey: typeof env.TOKENHARBOR_API_KEY === "string" && env.TOKENHARBOR_API_KEY.length > 0,
      tokenHarborKeyLength: env.TOKENHARBOR_API_KEY ? env.TOKENHARBOR_API_KEY.length : 0,
      hasCloudflareAiBinding: typeof env.AI !== "undefined" && env.AI !== null,
    });
  }

  /* --- پشتیبان‌گیری کامل (خروجی/ورودی تمام کلیدهای KV) ---
     هر درخواست فقط یک صفحه (حداکثر ۴۰ کلید) را می‌خواند تا از سقف تعداد subrequest در هر
     اجرای Worker (روی پلن رایگان ۵۰ عدد) عبور نکنیم؛ کلاینت با cursor صفحه‌به‌صفحه جمع می‌کند. */
  if (path === "/api/teacher/backup/export" && method === "GET") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const cursor = url.searchParams.get("cursor") || undefined;
    const res = await env.EXAM_KV.list({ cursor, limit: 40 });
    const values = await Promise.all(res.keys.map((k) => env.EXAM_KV.get(k.name)));
    const items = res.keys.map((k, i) => ({ key: k.name, value: values[i] })).filter((it) => it.value !== null && it.value !== undefined);
    return json({ ok: true, items, done: res.list_complete, cursor: res.list_complete ? null : res.cursor });
  }

  if (path === "/api/teacher/backup/import" && method === "POST") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const body = await req.json().catch(() => ({}));
    if (!body.confirm) return json({ ok: false, error: "برای بازیابی باید تأیید صریح ارسال شود" }, 400);
    const items = Array.isArray(body.items) ? body.items.slice(0, 40) : [];
    if (!items.length) return json({ ok: false, error: "دسته‌ی ارسالی خالی است" }, 400);
    const includePassword = body.includePassword === true;
    let restored = 0, failed = 0, skippedPassword = 0;
    for (const it of items) {
      if (!it || typeof it.key !== "string" || typeof it.value !== "string") { failed++; continue; }
      if (it.key === "teacher_pass" && !includePassword) { skippedPassword++; continue; }
      try { await env.EXAM_KV.put(it.key, it.value); restored++; } catch (e) { failed++; }
    }
    return json({ ok: true, restored, failed, skippedPassword });
  }

  /* --- جست‌وجوی سراسری: نام دانش‌آموز/حاضر در فهرست‌ها --- */
  if (path === "/api/teacher/search" && method === "GET") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const q = String(url.searchParams.get("q") || "").trim().toLowerCase().slice(0, 80);
    if (!q) return json({ ok: true, results: [] });
    const results = [];
    const students = await listStudents(env);
    for (const s of students) {
      if (String(s.label || "").toLowerCase().indexOf(q) !== -1) {
        results.push({ type: "student", uuid: s.uuid, label: s.label, grade: s.grade });
      }
    }
    let cursor;
    do {
      const res = await env.EXAM_KV.list({ prefix: "attendance:", cursor, limit: 200 });
      const values = await Promise.all(res.keys.map((k) => env.EXAM_KV.get(k.name)));
      for (const v of values) {
        if (!v) continue;
        const rec = JSON.parse(v);
        const full = String(rec.name || "") + " " + String(rec.family || "");
        if (full.toLowerCase().indexOf(q) !== -1) {
          results.push({ type: "attendance", uuid: "att-" + rec.id, label: full.trim(), linkId: rec.linkId });
        }
      }
      cursor = res.list_complete ? null : res.cursor;
    } while (cursor && results.length < 200);
    return json({ ok: true, results: results.slice(0, 50) });
  }

  /* --- داشبورد آماری خلاصه --- */
  async function computeDashboardStats() {
    const students = await listStudents(env);
    let submissionsTotal = 0, graded = 0, pending = 0;
    {
      let cursor;
      do {
        const res = await env.EXAM_KV.list({ prefix: "submission:", cursor, limit: 200 });
        const values = await Promise.all(res.keys.map((k) => env.EXAM_KV.get(k.name)));
        for (const v of values) {
          if (!v) continue;
          submissionsTotal++;
          const sub = JSON.parse(v);
          if (sub.grading && sub.grading.graded) graded++; else pending++;
        }
        cursor = res.list_complete ? null : res.cursor;
      } while (cursor);
    }
    let certsTotal = 0;
    {
      let cursor;
      do {
        const res = await env.EXAM_KV.list({ prefix: "certificates:", cursor, limit: 200 });
        for (const k of res.keys) {
          const v = await env.EXAM_KV.get(k.name);
          if (v) { try { certsTotal += (JSON.parse(v) || []).length; } catch (e) {} }
        }
        cursor = res.list_complete ? null : res.cursor;
      } while (cursor);
    }
    let attendanceTotal = 0;
    {
      let cursor;
      do {
        const res = await env.EXAM_KV.list({ prefix: "attendance:", cursor, limit: 200 });
        attendanceTotal += res.keys.length;
        cursor = res.list_complete ? null : res.cursor;
      } while (cursor);
    }
    return { studentsTotal: students.length, submissionsTotal, graded, pending, certsTotal, attendanceTotal };
  }
  if (path === "/api/teacher/stats/dashboard" && method === "GET") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const stats = await computeDashboardStats();
    return json({ ok: true, stats });
  }

  /* --- اطلاع‌رسانی به والدین (تلگرام + بله + روبیکا + پیامک sms.ir): تنظیمات و ارسال پیام --- */
  async function getNotifySettings() {
    const raw = await env.EXAM_KV.get("settings:notify");
    const defaults = { telegramBotToken: "", smsApiKey: "", smsLineNumber: "", baleBotToken: "", rubikaBotToken: "", telegramBotUsername: "", telegramWebhookSecret: "", rubikaBotUsername: "" };
    return raw ? Object.assign(defaults, JSON.parse(raw)) : defaults;
  }
  async function sendTelegramMessage(chatId, text) {
    const cfg = await getNotifySettings();
    if (!cfg.telegramBotToken || !chatId) return { ok: false, error: "تنظیم نشده" };
    try {
      const r = await fetch("https://api.telegram.org/bot" + cfg.telegramBotToken + "/sendMessage", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ chat_id: chatId, text }),
      });
      const d = await r.json().catch(() => ({}));
      return { ok: Boolean(d && d.ok), error: d && d.description };
    } catch (e) {
      return { ok: false, error: "ارتباط با تلگرام برقرار نشد" };
    }
  }
  // ارسال پیام از طریق بات بله (Bale) - ساختار API آن با تلگرام یکسان است
  async function sendBaleMessage(chatId, text) {
    const cfg = await getNotifySettings();
    if (!cfg.baleBotToken || !chatId) return { ok: false, error: "تنظیم نشده" };
    try {
      const r = await fetch("https://tapi.bale.ai/bot" + cfg.baleBotToken + "/sendMessage", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ chat_id: chatId, text }),
      });
      const d = await r.json().catch(() => ({}));
      return { ok: Boolean(d && d.ok), error: d && d.description };
    } catch (e) {
      return { ok: false, error: "ارتباط با بله برقرار نشد" };
    }
  }
  // ارسال پیام از طریق بات روبیکا (Rubika)
  async function sendRubikaMessage(chatId, text) {
    const cfg = await getNotifySettings();
    if (!cfg.rubikaBotToken || !chatId) return { ok: false, error: "تنظیم نشده" };
    try {
      const r = await fetch("https://botapi.rubika.ir/v3/" + cfg.rubikaBotToken + "/sendMessage", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ chat_id: chatId, text }),
      });
      const d = await r.json().catch(() => ({}));
      return { ok: !d || !d.error, error: d && (d.error || d.message) };
    } catch (e) {
      return { ok: false, error: "ارتباط با روبیکا برقرار نشد" };
    }
  }
  // ارسال پیامک از طریق وب‌سرویس sms.ir (متد Bulk - مناسب برای ارسال تکی هم هست)
  async function sendSms(mobile, text) {
    const cfg = await getNotifySettings();
    const mobileClean = String(mobile || "").trim();
    if (!cfg.smsApiKey || !cfg.smsLineNumber || !mobileClean) return { ok: false, error: "تنظیم نشده" };
    try {
      const r = await fetch("https://api.sms.ir/v1/send/bulk", {
        method: "POST",
        headers: { "content-type": "application/json", "x-api-key": cfg.smsApiKey },
        body: JSON.stringify({ lineNumber: cfg.smsLineNumber, messageText: text, mobiles: [mobileClean], sendDateTime: null }),
      });
      const d = await r.json().catch(() => ({}));
      return { ok: Boolean(d && d.status === 1), error: d && d.message };
    } catch (e) {
      return { ok: false, error: "ارتباط با سامانه پیامک برقرار نشد" };
    }
  }
  if (path === "/api/teacher/notify/settings" && method === "GET") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const cfg = await getNotifySettings();
    return json({
      ok: true,
      configured: Boolean(cfg.telegramBotToken),
      baleConfigured: Boolean(cfg.baleBotToken),
      rubikaConfigured: Boolean(cfg.rubikaBotToken),
      smsConfigured: Boolean(cfg.smsApiKey && cfg.smsLineNumber),
      smsLineNumber: cfg.smsLineNumber || "",
      telegramBotUsername: cfg.telegramBotUsername || "",
      botWebhookConfigured: Boolean(cfg.telegramWebhookSecret),
      rubikaBotUsername: cfg.rubikaBotUsername || "",
    });
  }
  if (path === "/api/teacher/notify/settings" && method === "POST") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const body = await req.json().catch(() => ({}));
    const prev = await getNotifySettings();
    const cfg = {
      telegramBotToken: body.telegramBotToken !== undefined ? String(body.telegramBotToken || "").trim().slice(0, 200) : (prev.telegramBotToken || ""),
      baleBotToken: body.baleBotToken !== undefined ? String(body.baleBotToken || "").trim().slice(0, 200) : (prev.baleBotToken || ""),
      rubikaBotToken: body.rubikaBotToken !== undefined ? String(body.rubikaBotToken || "").trim().slice(0, 200) : (prev.rubikaBotToken || ""),
      smsApiKey: body.smsApiKey !== undefined ? String(body.smsApiKey || "").trim().slice(0, 200) : (prev.smsApiKey || ""),
      smsLineNumber: body.smsLineNumber !== undefined ? String(body.smsLineNumber || "").trim().slice(0, 20) : (prev.smsLineNumber || ""),
      telegramBotUsername: body.telegramBotUsername !== undefined ? String(body.telegramBotUsername || "").trim().replace(/^@/, "").slice(0, 64) : (prev.telegramBotUsername || ""),
      telegramWebhookSecret: prev.telegramWebhookSecret || "",
      rubikaBotUsername: body.rubikaBotUsername !== undefined ? String(body.rubikaBotUsername || "").trim().replace(/^@/, "").slice(0, 64) : (prev.rubikaBotUsername || ""),
    };
    await env.EXAM_KV.put("settings:notify", JSON.stringify(cfg));
    return json({ ok: true });
  }
  if (path === "/api/teacher/notify/test" && method === "POST") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const body = await req.json().catch(() => ({}));
    const r = await sendTelegramMessage(String(body.chatId || "").trim(), "✅ این یک پیام آزمایشی از پنل مدیریت کلاسی است.");
    return json(r);
  }
  // دریافت لیست آخرین چت‌هایی که به بات تلگرام پیام داده‌اند (برای پیدا کردن chat_id والدین)
  // نکته‌ی مهم: چون بات مکالمه‌ای همیشه روشن است (webhook فعال)، هر پیام تازه بلافاصله توسط خودِ webhook
  // «مصرف» می‌شود و متد getUpdates تلگرام دیگر هرگز آن را برنمی‌گرداند (نه فقط تا وقتی webhook فعال است؛
  // این وضعیت با روشن/خاموش کردن موقت webhook هم درست نمی‌شود). به همین دلیل این قسمت دیگر از getUpdates
  // استفاده نمی‌کند و به‌جایش لاگ داخلی‌ای را برمی‌گرداند که خودِ webhook (تابع tgLogRecentChat) هر بار که
  // کسی به بات پیام می‌دهد، ذخیره می‌کند. این لاگ فقط پیام‌هایی را می‌بیند که از همین حالا به بعد ارسال شوند.
  if (path === "/api/teacher/notify/telegram-updates" && method === "POST") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    try {
      const raw = await env.EXAM_KV.get("tg_recent_chats");
      let list = [];
      try { list = raw ? JSON.parse(raw) : []; } catch (e) { list = []; }
      if (!list.length) {
        return json({ ok: true, items: [], hint: "هنوز کسی از الان به بعد به بات پیام نداده. از والد بخواهید یک‌بار به بات پیام بدهد (مثلاً /start)، سپس دوباره اینجا را بزنید." });
      }
      const items = list.map((it) => ({ chatId: it.chatId, name: it.name || "", text: it.text || "" }));
      return json({ ok: true, items });
    } catch (e) {
      return json({ ok: false, error: "خطا در خواندن لاگ" });
    }
  }
  if (path === "/api/teacher/notify/test-bale" && method === "POST") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const body = await req.json().catch(() => ({}));
    const r = await sendBaleMessage(String(body.chatId || "").trim(), "✅ این یک پیام آزمایشی از پنل مدیریت کلاسی است.");
    return json(r);
  }
  if (path === "/api/teacher/notify/test-rubika" && method === "POST") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const body = await req.json().catch(() => ({}));
    const r = await sendRubikaMessage(String(body.chatId || "").trim(), "✅ این یک پیام آزمایشی از پنل مدیریت کلاسی است.");
    return json(r);
  }
  // دریافت لیست آخرین چت‌هایی که به بات روبیکا پیام داده‌اند (برای پیدا کردن chat_id والدین)
  // نکته‌ی مهم (مشابه تلگرام بالا): چون بات مکالمه‌ای روبیکا هم روی webhook کار می‌کند، پیام‌های تازه
  // بلافاصله توسط خودِ webhook مصرف می‌شوند و متد getUpdates روبیکا دیگر آن‌ها را برنمی‌گرداند؛ به همین
  // دلیل این قسمت هم مثل تلگرام از لاگ داخلی (rbLogRecentChat) به‌جای getUpdates استفاده می‌کند.
  if (path === "/api/teacher/notify/rubika-updates" && method === "POST") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const cfg = await getNotifySettings();
    if (!cfg.rubikaBotToken) return json({ ok: false, error: "اول توکن روبیکا را ذخیره کنید" });
    try {
      const raw = await env.EXAM_KV.get("rb_recent_chats");
      let list = [];
      try { list = raw ? JSON.parse(raw) : []; } catch (e) { list = []; }
      if (!list.length) {
        return json({ ok: true, items: [], hint: "هنوز کسی از الان به بعد به بات پیام نداده. از والد بخواهید یک‌بار به بات پیام بدهد (مثلاً /start)، سپس دوباره اینجا را بزنید." });
      }
      const items = list.map((it) => ({ chatId: it.chatId, text: it.text || "" }));
      // برای هرکدام تلاش می‌کنیم نام چت (نام والد) را هم از متد getChat بگیریم
      let rawChatSample = null;
      await Promise.all(
        items.slice(0, 15).map(async (it) => {
          try {
            const rc = await fetch("https://botapi.rubika.ir/v3/" + cfg.rubikaBotToken + "/getChat", {
              method: "POST",
              headers: { "content-type": "application/json" },
              body: JSON.stringify({ chat_id: it.chatId }),
            });
            const dc = await rc.json().catch(() => ({}));
            if (!rawChatSample) rawChatSample = dc;
            const chat = (dc && dc.data && dc.data.chat) || (dc && dc.chat) || (dc && dc.data) || {};
            const nameParts = [chat.first_name, chat.last_name].filter(Boolean).join(" ");
            it.name = nameParts || chat.title || chat.username || chat.name || "";
          } catch (e) {}
        })
      );
      return json({ ok: true, items, rawChatSample });
    } catch (e) {
      return json({ ok: false, error: "خطا در خواندن لاگ" });
    }
  }
  if (path === "/api/teacher/notify/test-sms" && method === "POST") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const body = await req.json().catch(() => ({}));
    const r = await sendSms(String(body.mobile || "").trim(), "این یک پیامک آزمایشی از پنل مدیریت کلاسی است.");
    return json(r);
  }

  /* ==================== بات مکالمه‌ای تلگرام (v1) ====================
     دانش‌آموز از طریق دیپ‌لینک اختصاصی (t.me/<bot>?start=<uuid>) شناسایی می‌شود، دقیقاً
     همان منطق «داشتن لینک = دسترسی» که در پنل هست. معلم با «/login رمزعبور» وارد می‌شود.
     برای مکالمات چندمرحله‌ای (ثبت سریع کارنامه، ارسال/بازخورد کاربرگ) یک state ساده
     در KV نگه‌داری می‌شود (tgstate:<chatId>). */

  function tgKeyboard(rows) { return { inline_keyboard: rows }; }

  async function tgSend(chatId, text, rows) {
    const cfg = await getNotifySettings();
    if (!cfg.telegramBotToken) return;
    const payload = { chat_id: chatId, text: text.slice(0, 4000) };
    if (rows) payload.reply_markup = tgKeyboard(rows);
    try {
      await fetch("https://api.telegram.org/bot" + cfg.telegramBotToken + "/sendMessage", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(payload),
      });
    } catch (e) {}
  }

  function tgBackRow() {
    return [[{ text: "🔙 بازگشت به منوی اصلی", callback_data: "back_main" }]];
  }
  function tgWithBack(rows) {
    return (rows || []).concat(tgBackRow());
  }

  async function tgAnswerCallback(id, text) {
    const cfg = await getNotifySettings();
    if (!cfg.telegramBotToken) return;
    try {
      await fetch("https://api.telegram.org/bot" + cfg.telegramBotToken + "/answerCallbackQuery", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ callback_query_id: id, text: text || "" }),
      });
    } catch (e) {}
  }

  async function tgSendFileFromDataUrl(chatId, dataUrl, caption) {
    const cfg = await getNotifySettings();
    if (!cfg.telegramBotToken || !dataUrl) return;
    try {
      const comma = dataUrl.indexOf(",");
      const meta = dataUrl.slice(5, comma);
      const mime = meta.split(";")[0] || "image/jpeg";
      const b64 = dataUrl.slice(comma + 1);
      const bin = atob(b64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      const isPdf = mime.indexOf("pdf") !== -1;
      const fd = new FormData();
      fd.append("chat_id", String(chatId));
      if (caption) fd.append("caption", caption.slice(0, 1000));
      const blob = new Blob([bytes], { type: mime });
      fd.append(isPdf ? "document" : "photo", blob, isPdf ? "file.pdf" : "file.jpg");
      await fetch("https://api.telegram.org/bot" + cfg.telegramBotToken + "/" + (isPdf ? "sendDocument" : "sendPhoto"), { method: "POST", body: fd });
    } catch (e) {}
  }

  async function tgDownloadPhotoAsDataUrl(fileId) {
    const cfg = await getNotifySettings();
    if (!cfg.telegramBotToken) return null;
    try {
      const r = await fetch("https://api.telegram.org/bot" + cfg.telegramBotToken + "/getFile?file_id=" + encodeURIComponent(fileId));
      const d = await r.json();
      if (!d || !d.ok || !d.result || !d.result.file_path) return null;
      const fr = await fetch("https://api.telegram.org/file/bot" + cfg.telegramBotToken + "/" + d.result.file_path);
      const buf = await fr.arrayBuffer();
      const bytes = new Uint8Array(buf);
      let bin = "";
      for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
      return "data:image/jpeg;base64," + btoa(bin);
    } catch (e) {
      return null;
    }
  }

  async function tgGetState(chatId) {
    const raw = await env.EXAM_KV.get("tgstate:" + chatId);
    return raw ? JSON.parse(raw) : null;
  }
  async function tgSetState(chatId, state) {
    if (state) await env.EXAM_KV.put("tgstate:" + chatId, JSON.stringify(state));
    else await env.EXAM_KV.delete("tgstate:" + chatId);
  }

  const TG_GRADE_LABELS = ["اول ابتدایی", "دوم ابتدایی", "سوم ابتدایی", "چهارم ابتدایی", "پنجم ابتدایی", "ششم ابتدایی", "هفتم", "هشتم", "نهم", "دهم", "یازدهم", "دوازدهم"];
  const TG_RC_MONTHS = ["مهر", "آبان", "آذر", "دی", "بهمن", "اسفند", "فروردین", "اردیبهشت"];
  const TG_LEVEL_LABELS = { excellent: "خیلی خوب", good: "خوب", acceptable: "قابل‌قبول", "needs-improve": "نیاز به تلاش" };
  const TG_LEVEL_MAP = { "عالی": "excellent", "خیلی خوب": "excellent", "خوب": "good", "قابل‌قبول": "acceptable", "قابل قبول": "acceptable", "ضعیف": "needs-improve", "نیاز به تلاش": "needs-improve" };
  const TG_LEVEL_OPTIONS = [["excellent", "خیلی خوب"], ["good", "خوب"], ["acceptable", "قابل‌قبول"], ["needs-improve", "نیاز به تلاش"]];
  // فهرست دروس واقعی کارنامه‌ی توصیفی به تفکیک پایه (فقط نام درس‌ها؛ همان دروسی که در خودِ پنل «کارنامه‌ساز» هست، پایه‌های ۱ تا ۶ ابتدایی)
  const TG_RC_SUBJECTS = [
    { name: "قرآن", grades: [1, 1, 1, 1, 1, 1] },
    { name: "هدیه‌های آسمان", grades: [0, 1, 1, 1, 1, 1] },
    { name: "فارسی", grades: [1, 1, 1, 1, 1, 1] },
    { name: "ریاضی", grades: [1, 1, 1, 1, 1, 1] },
    { name: "علوم", grades: [1, 1, 1, 1, 1, 1] },
    { name: "اجتماعی", grades: [0, 0, 1, 1, 1, 1] },
    { name: "تفکر و پژوهش", grades: [0, 0, 0, 0, 0, 1] },
    { name: "کار و فناوری", grades: [0, 0, 0, 0, 0, 1] },
    { name: "هنر", grades: [1, 1, 1, 1, 1, 1] },
    { name: "تربیت بدنی", grades: [1, 1, 1, 1, 1, 1] },
    { name: "شایستگی‌های عمومی", grades: [1, 1, 1, 1, 1, 1] },
  ];
  function tgActiveSubjects(gradeIdx) {
    return TG_RC_SUBJECTS.filter((s) => s.grades[gradeIdx]).map((s) => s.name);
  }
  function tgRcSubjectRows(state) {
    const active = tgActiveSubjects(state.gradeIdx);
    const rows = active.map((name) => {
      const done = state.subjects[name];
      return [{ text: (done ? "✅ " : "▫️ ") + name + (done ? " (" + (TG_LEVEL_LABELS[done.level] || "") + ")" : ""), callback_data: "rc_subj:" + name }];
    });
    rows.push([{ text: "➕ درس دیگر (تایپ آزاد)", callback_data: "rc_custom" }]);
    rows.push([{ text: "✅ پایان و ذخیره", callback_data: "rc_finish" }]);
    return rows;
  }

  function tgStudentMenu() {
    return [
      [{ text: "📊 کارنامه ماهیانه", callback_data: "s_rc" }],
      [{ text: "📅 برنامه هفتگی", callback_data: "s_sch" }],
      [{ text: "📓 کاربرگ", callback_data: "s_ws" }],
      [{ text: "🏅 لوح‌های تقدیر", callback_data: "s_cert" }],
      [{ text: "📝 آزمون آنلاین", callback_data: "s_exam" }],
    ];
  }
  function tgTeacherMenu() {
    return [
      [{ text: "👨‍🎓 لیست دانش‌آموزان", callback_data: "t_students" }],
      [{ text: "📝 ثبت سریع کارنامه", callback_data: "t_rc" }],
      [{ text: "📓 کاربرگ‌های ارسالی", callback_data: "t_ws" }],
      [{ text: "📊 آمار داشبورد", callback_data: "t_stats" }],
    ];
  }

  async function tgHandleStateMessage(chatId, msg, state) {
    if (state.step === "exam_identity") {
      const text = (msg.text || "").trim();
      if (!text) { await tgSend(chatId, "لطفاً پاسخ را به صورت متن بفرستید.", tgBackRow()); return; }
      if (state.identStep === 0) {
        state.identity.fatherName = text.slice(0, 120);
        state.identStep = 1;
        await tgSetState(chatId, state);
        await tgSend(chatId, "کد ملی را تایپ کنید:", tgBackRow());
        return;
      }
      if (state.identStep === 1) {
        state.identity.nationalId = text.slice(0, 30);
        const stRaw = await env.EXAM_KV.get("student:" + state.uuid);
        const st = stRaw ? JSON.parse(stRaw) : {};
        const meta = await getMeta(env, state.grade);
        const newState = {
          step: "exam",
          uuid: state.uuid,
          grade: state.grade,
          idx: 0,
          answers: {},
          awaitingText: false,
          startedAt: Date.now(),
          durationMinutes: parseInt(meta.examDuration, 10) || 30,
          identity: {
            name: st.label || "",
            fatherName: state.identity.fatherName,
            nationalId: state.identity.nationalId,
            courseName: meta.examName || "",
            examDate: new Date().toLocaleDateString("fa-IR"),
          },
        };
        await tgSetState(chatId, newState);
        await tgSend(chatId, "✅ اطلاعات ثبت شد. آزمون شروع می‌شود.");
        await tgSendExamQuestion(chatId, newState);
        return;
      }
      return;
    }
    if (state.step === "exam" && state.awaitingText) {
      const text = (msg.text || "").trim();
      if (!text) { await tgSend(chatId, "لطفاً پاسخ را به‌صورت متن بفرستید یا از دکمه‌ی «رد شدن» استفاده کنید."); return; }
      const questions = await getQuestions(env, state.grade);
      const q = questions[state.idx];
      if (q) state.answers[q.id] = text.slice(0, 4000);
      state.idx += 1;
      state.awaitingText = false;
      await tgSetState(chatId, state);
      await tgSendExamQuestion(chatId, state);
      return;
    }
    if (state.step === "ws_upload") {
      if (msg.photo && msg.photo.length) {
        const dataUrl = await tgDownloadPhotoAsDataUrl(msg.photo[msg.photo.length - 1].file_id);
        if (!dataUrl) { await tgSend(chatId, "دریافت عکس با خطا مواجه شد."); return; }
        const raw = await env.EXAM_KV.get("worksheet:" + state.uuid);
        const rec = raw ? JSON.parse(raw) : { uuid: state.uuid };
        rec.studentFiles = (rec.studentFiles || []).concat([dataUrl]).slice(-6);
        rec.studentUploadedAt = Date.now();
        await env.EXAM_KV.put("worksheet:" + state.uuid, JSON.stringify(rec));
        await tgSend(chatId, "✅ عکس ثبت شد. می‌توانید عکس دیگری بفرستید یا «پایان» را تایپ کنید.");
        return;
      }
      if ((msg.text || "").trim() === "پایان") {
        await tgSetState(chatId, null);
        await tgSend(chatId, "ارسال کاربرگ به پایان رسید ✅", tgStudentMenu());
        return;
      }
      await tgSend(chatId, "لطفاً عکسِ پاسخِ کاربرگ را بفرستید یا «پایان» را تایپ کنید.", tgBackRow());
      return;
    }
    if (state.step === "rc_collect") {
      const text = (msg.text || "").trim();
      if (text === "پایان") {
        const studentRaw = await env.EXAM_KV.get("student:" + state.uuid);
        const st = studentRaw ? JSON.parse(studentRaw) : {};
        const key = "reportcard:student:" + state.uuid + ":" + state.month;
        const prevRaw = await env.EXAM_KV.get("lbdata:" + key);
        const prev = prevRaw ? JSON.parse(prevRaw) : {};
        const rec = {
          uuid: state.uuid,
          name: st.label || prev.name || "",
          grade: Number.isInteger(st.grade) ? st.grade : prev.grade || 0,
          month: state.month,
          absence: prev.absence || "",
          generalNote: prev.generalNote || "",
          photo: prev.photo || "",
          font: prev.font || "",
          meta: prev.meta || {},
          data: state.subjects,
        };
        await env.EXAM_KV.put("lbdata:" + key, JSON.stringify(rec));
        await notifyReportCard(state.uuid, state.month);
        await tgSetState(chatId, null);
        await tgSend(chatId, "کارنامه‌ی «" + (rec.name || "دانش‌آموز") + "» برای ماه " + state.month + " ذخیره و برای والدین ارسال شد ✅", tgTeacherMenu());
        return;
      }
      if (!state.awaitingCustom) {
        await tgSend(chatId, "لطفاً درس را از دکمه‌های بالا انتخاب کنید، یا روی «➕ درس دیگر» بزنید.", tgWithBack(tgRcSubjectRows(state)));
        return;
      }
      const parts = text.split(":");
      if (parts.length < 2) { await tgSend(chatId, "فرمت درست نیست. به این شکل بفرستید:\nنام‌درس: سطح\nمثال: خوشنویسی: خیلی خوب", tgBackRow()); return; }
      const subject = parts[0].trim();
      const levelText = parts.slice(1).join(":").trim();
      const level = TG_LEVEL_MAP[levelText] || "";
      if (!subject || !level) { await tgSend(chatId, "سطح باید یکی از این‌ها باشد: عالی، خوب، قابل‌قبول، ضعیف", tgBackRow()); return; }
      state.subjects[subject] = { level, note: "" };
      state.awaitingCustom = false;
      await tgSetState(chatId, state);
      await tgSend(chatId, "✅ ثبت شد: " + subject + " — " + (TG_LEVEL_LABELS[level] || level), tgWithBack(tgRcSubjectRows(state)));
      return;
    }
    if (state.step === "ws_feedback") {
      const text = (msg.text || "").trim();
      if (!text) { await tgSend(chatId, "لطفاً بازخورد را به‌صورت متن بفرستید.", tgBackRow()); return; }
      const raw = await env.EXAM_KV.get("worksheet:" + state.uuid);
      const rec = raw ? JSON.parse(raw) : { uuid: state.uuid };
      rec.feedback = text.slice(0, 5000);
      rec.feedbackAt = Date.now();
      await env.EXAM_KV.put("worksheet:" + state.uuid, JSON.stringify(rec));
      await tgSetState(chatId, null);
      await tgSend(chatId, "بازخورد ثبت شد ✅", tgTeacherMenu());
      return;
    }
  }

  async function tgHandleCallback(cq) {
    const chatId = cq.message.chat.id;
    const data = cq.data || "";
    await tgAnswerCallback(cq.id, "");
    const studentUuid = await env.EXAM_KV.get("tgstudent:" + chatId);
    const isTgTeacher = Boolean(await env.EXAM_KV.get("tgteacher:" + chatId));

    if (data === "back_main") {
      const st0 = await tgGetState(chatId);
      if (!(st0 && st0.step === "exam")) await tgSetState(chatId, null);
      if (isTgTeacher) await tgSend(chatId, "یکی از گزینه‌ها را انتخاب کنید:", tgTeacherMenu());
      else if (studentUuid) await tgSend(chatId, "یکی از گزینه‌ها را انتخاب کنید:", tgStudentMenu());
      else await tgSend(chatId, "برای استفاده از ربات، از لینک اختصاصی‌تان استفاده کنید.");
      return;
    }

    if (data === "s_rc" && studentUuid) {
      await tgSend(chatId, "ماه مورد نظر را انتخاب کنید:", tgWithBack(TG_RC_MONTHS.map((m) => [{ text: m, callback_data: "s_rc_m:" + m }])));
      return;
    }
    if (data.indexOf("s_rc_m:") === 0 && studentUuid) {
      const month = data.slice(7);
      const raw = await env.EXAM_KV.get("lbdata:reportcard:student:" + studentUuid + ":" + month);
      if (!raw) { await tgSend(chatId, "برای ماه " + month + " هنوز کارنامه‌ای ثبت نشده است.", tgBackRow()); return; }
      const rec = JSON.parse(raw);
      let t = "📊 کارنامه‌ی ماه " + month + "\n\n";
      const subs = rec.data || {};
      for (const name in subs) {
        const v = subs[name] || {};
        t += "▫️ " + name + ": " + (TG_LEVEL_LABELS[v.level] || "—") + (v.note ? " («" + v.note + "»)" : "") + "\n";
      }
      if (rec.absence) t += "\nغیبت: " + rec.absence;
      if (rec.generalNote) t += "\nتوضیح کلی: " + rec.generalNote;
      await tgSend(chatId, t, tgBackRow());
      return;
    }
    if (data === "s_sch" && studentUuid) {
      const stRaw = await env.EXAM_KV.get("student:" + studentUuid);
      const st = stRaw ? JSON.parse(stRaw) : {};
      const g = Number.isInteger(st.grade) ? st.grade : 0;
      const raw = await env.EXAM_KV.get("schedule_data:grade:" + g);
      if (!raw) { await tgSend(chatId, "برنامه‌ی هفتگی‌ای برای پایه‌ی شما ثبت نشده است.", tgBackRow()); return; }
      const sd = JSON.parse(raw);
      const days = ["شنبه", "یکشنبه", "دوشنبه", "سه‌شنبه", "چهارشنبه"];
      let t = "📅 برنامه‌ی هفتگی\n\n";
      for (let d = 0; d < 5; d++) {
        t += days[d] + "\n";
        for (let i = 1; i <= 5; i++) {
          const v = (sd.cells && sd.cells["c" + d + i]) || "—";
          t += "  زنگ " + i + ": " + v + "\n";
        }
        t += "\n";
      }
      await tgSend(chatId, t, tgBackRow());
      return;
    }
    if (data === "s_ws" && studentUuid) {
      const raw = await env.EXAM_KV.get("worksheet:" + studentUuid);
      const rec = raw ? JSON.parse(raw) : {};
      if (rec.teacherFile) await tgSendFileFromDataUrl(chatId, rec.teacherFile, "📓 کاربرگ شما");
      else await tgSend(chatId, "هنوز کاربرگی برای شما ارسال نشده است.");
      if (rec.feedback) await tgSend(chatId, "📝 بازخورد معلم: " + rec.feedback);
      await tgSetState(chatId, { step: "ws_upload", uuid: studentUuid });
      await tgSend(chatId, "برای ارسال پاسخ، عکس کاربرگ حل‌شده را همین‌جا بفرستید. بعد از اتمام «پایان» را بفرستید.", tgBackRow());
      return;
    }
    if (data === "s_cert" && studentUuid) {
      const raw = await env.EXAM_KV.get("certificates:" + studentUuid);
      const list = raw ? JSON.parse(raw) : [];
      if (!list.length) { await tgSend(chatId, "هنوز لوح تقدیری برای شما صادر نشده است.", tgBackRow()); return; }
      let t = "🏅 لوح‌های تقدیر شما:\n\n";
      list.slice(0, 15).forEach((c) => {
        t += "▫️ " + (c.title || "لوح تقدیر") + "\n" + url.origin + "/cert/" + encodeURIComponent(studentUuid) + "/" + encodeURIComponent(c.id || "") + "\n\n";
      });
      await tgSend(chatId, t, tgBackRow());
      return;
    }

    /* ----- 📝 آزمون آنلاین (سمت دانش‌آموز) ----- */
    if (data === "s_exam" && studentUuid) {
      const existingSub = await env.EXAM_KV.get("submission:" + studentUuid);
      if (existingSub) {
        await tgSend(chatId, "✅ شما قبلاً در این آزمون شرکت کرده‌اید. برای دیدن نتیجه به معلم مراجعه کنید.", tgBackRow());
        return;
      }
      const stRaw = await env.EXAM_KV.get("student:" + studentUuid);
      const st = stRaw ? JSON.parse(stRaw) : {};
      const grade = clampGrade(st.grade);
      const meta = await getMeta(env, grade);
      const questions = await getQuestions(env, grade);
      if (!questions.length) {
        await tgSend(chatId, "در حال حاضر آزمونی برای پایه‌ی شما تعریف نشده است.", tgBackRow());
        return;
      }
      const existingState = await tgGetState(chatId);
      if (existingState && existingState.step === "exam" && existingState.uuid === studentUuid) {
        await tgSendExamQuestion(chatId, existingState);
        return;
      }
      const identState = { step: "exam_identity", identStep: 0, uuid: studentUuid, grade, identity: {} };
      await tgSetState(chatId, identState);
      const head = "📝 " + (meta.examName || "آزمون") + "\n🏫 " + (meta.school || "") + "\n👨‍🏫 " + (meta.teacher || "") +
        "\n⏱ مدت زمان: " + (meta.examDuration || 30) + " دقیقه\n📚 تعداد سوالات: " + questions.length +
        "\n\nقبل از شروع، چند اطلاعات کوتاه نیاز است.\nلطفاً نام پدر را تایپ کنید:";
      await tgSend(chatId, head, tgBackRow());
      return;
    }
    if (data.indexOf("exam_ans:") === 0 && studentUuid) {
      const state = await tgGetState(chatId);
      if (!state || state.step !== "exam") return;
      const questions = await getQuestions(env, state.grade);
      const q = questions[state.idx];
      if (q) state.answers[q.id] = data.slice(9);
      state.idx += 1;
      state.awaitingText = false;
      await tgSetState(chatId, state);
      await tgSendExamQuestion(chatId, state);
      return;
    }
    if (data === "exam_skip" && studentUuid) {
      const state = await tgGetState(chatId);
      if (!state || state.step !== "exam") return;
      state.idx += 1;
      state.awaitingText = false;
      await tgSetState(chatId, state);
      await tgSendExamQuestion(chatId, state);
      return;
    }
    if (data === "exam_prev" && studentUuid) {
      const state = await tgGetState(chatId);
      if (!state || state.step !== "exam") return;
      state.idx = Math.max(0, state.idx - 1);
      state.awaitingText = false;
      await tgSetState(chatId, state);
      await tgSendExamQuestion(chatId, state);
      return;
    }
    if (data === "exam_submit" && studentUuid) {
      const state = await tgGetState(chatId);
      if (!state || state.step !== "exam") return;
      await tgFinishExam(chatId, state, false);
      return;
    }

    if (!isTgTeacher) return;

    if (data === "t_students") {
      await tgSend(chatId, "پایه را انتخاب کنید:", tgWithBack(TG_GRADE_LABELS.map((lab, idx) => [{ text: lab, callback_data: "t_students_g:" + idx }])));
      return;
    }
    if (data.indexOf("t_students_g:") === 0) {
      const g = parseInt(data.slice(13), 10) || 0;
      const students = (await listStudents(env)).filter((s) => (Number.isInteger(s.grade) ? s.grade : 0) === g);
      if (!students.length) { await tgSend(chatId, "دانش‌آموزی برای این پایه ثبت نشده.", tgBackRow()); return; }
      const subs = await Promise.all(students.map((s) => env.EXAM_KV.get("submission:" + s.uuid)));
      let t = "👨‍🎓 دانش‌آموزان (" + students.length + " نفر):\n\n";
      students.forEach((s, i) => {
        let status = "بدون تکلیف ارسالی";
        if (subs[i]) { try { const sub = JSON.parse(subs[i]); status = sub.grading && sub.grading.graded ? "تصحیح‌شده ✅" : "در انتظار تصحیح ⏳"; } catch (e) {} }
        t += "▫️ " + (s.label || "—") + " — " + status + "\n";
      });
      const chunks = t.match(/[\s\S]{1,3500}/g) || [t];
      for (let i = 0; i < chunks.length; i++) await tgSend(chatId, chunks[i], i === chunks.length - 1 ? tgBackRow() : undefined);
      return;
    }
    if (data === "t_stats") {
      const stats = await computeDashboardStats();
      const t = "📊 آمار کلی:\n\nدانش‌آموزان: " + stats.studentsTotal + "\nتکالیف ارسالی: " + stats.submissionsTotal + " (تصحیح‌شده: " + stats.graded + " — در انتظار: " + stats.pending + ")\nلوح‌های تقدیر: " + stats.certsTotal + "\nثبت‌نام‌های حضور و غیاب: " + stats.attendanceTotal;
      await tgSend(chatId, t, tgBackRow());
      return;
    }
    if (data === "t_rc") {
      await tgSend(chatId, "پایه‌ی دانش‌آموز را انتخاب کنید:", tgWithBack(TG_GRADE_LABELS.map((lab, idx) => [{ text: lab, callback_data: "t_rc_g:" + idx }])));
      return;
    }
    if (data.indexOf("t_rc_g:") === 0) {
      const g = parseInt(data.slice(7), 10) || 0;
      const students = (await listStudents(env)).filter((s) => (Number.isInteger(s.grade) ? s.grade : 0) === g);
      if (!students.length) { await tgSend(chatId, "دانش‌آموزی برای این پایه ثبت نشده.", tgBackRow()); return; }
      await tgSend(chatId, "دانش‌آموز را انتخاب کنید:", tgWithBack(students.slice(0, 30).map((s) => [{ text: s.label || "—", callback_data: "t_rc_s:" + s.uuid }])));
      return;
    }
    if (data.indexOf("t_rc_s:") === 0) {
      const uuid = data.slice(7);
      await tgSend(chatId, "ماه را انتخاب کنید:", tgWithBack(TG_RC_MONTHS.map((m) => [{ text: m, callback_data: "t_rc_m:" + uuid + ":" + m }])));
      return;
    }
    if (data.indexOf("t_rc_m:") === 0) {
      const rest = data.slice(7);
      const sep = rest.lastIndexOf(":");
      const uuid = rest.slice(0, sep);
      const month = rest.slice(sep + 1);
      const stRaw = await env.EXAM_KV.get("student:" + uuid);
      const stRec = stRaw ? JSON.parse(stRaw) : {};
      const gradeIdx = Number.isInteger(stRec.grade) ? stRec.grade : 0;
      const prevRaw = await env.EXAM_KV.get("lbdata:reportcard:student:" + uuid + ":" + month);
      const prevSubjects = prevRaw ? (JSON.parse(prevRaw).data || {}) : {};
      const state = { step: "rc_collect", uuid, month, gradeIdx, subjects: Object.assign({}, prevSubjects) };
      await tgSetState(chatId, state);
      await tgSend(chatId, "درس مورد نظر را انتخاب کنید و سطح ارزشیابی را بزنید. وقتی تمام شد «✅ پایان و ذخیره» را بزنید:", tgWithBack(tgRcSubjectRows(state)));
      return;
    }
    if (data.indexOf("rc_subj:") === 0) {
      const state = await tgGetState(chatId);
      if (!state || state.step !== "rc_collect") return;
      const subject = data.slice(8);
      await tgSend(chatId, "سطح ارزشیابی «" + subject + "» را انتخاب کنید:", tgWithBack(TG_LEVEL_OPTIONS.map((o) => [{ text: o[1], callback_data: "rc_level:" + subject + ":" + o[0] }])));
      return;
    }
    if (data.indexOf("rc_level:") === 0) {
      const state = await tgGetState(chatId);
      if (!state || state.step !== "rc_collect") return;
      const rest = data.slice(9);
      const sep = rest.lastIndexOf(":");
      const subject = rest.slice(0, sep);
      const level = rest.slice(sep + 1);
      state.subjects[subject] = { level, note: (state.subjects[subject] && state.subjects[subject].note) || "" };
      await tgSetState(chatId, state);
      await tgSend(chatId, "✅ ثبت شد: " + subject + " — " + (TG_LEVEL_LABELS[level] || level), tgWithBack(tgRcSubjectRows(state)));
      return;
    }
    if (data === "rc_custom") {
      const state = await tgGetState(chatId);
      if (!state || state.step !== "rc_collect") return;
      state.awaitingCustom = true;
      await tgSetState(chatId, state);
      await tgSend(chatId, "نام درس و سطح را به این شکل تایپ کنید:\nنام‌درس: سطح\nسطح یکی از این‌ها: عالی، خوب، قابل‌قبول، ضعیف\nمثال: خوشنویسی: خیلی خوب", tgBackRow());
      return;
    }
    if (data === "rc_finish") {
      const state = await tgGetState(chatId);
      if (!state || state.step !== "rc_collect") return;
      const studentRaw = await env.EXAM_KV.get("student:" + state.uuid);
      const st = studentRaw ? JSON.parse(studentRaw) : {};
      const key = "reportcard:student:" + state.uuid + ":" + state.month;
      const prevRaw = await env.EXAM_KV.get("lbdata:" + key);
      const prev = prevRaw ? JSON.parse(prevRaw) : {};
      const rec = {
        uuid: state.uuid,
        name: st.label || prev.name || "",
        grade: Number.isInteger(st.grade) ? st.grade : prev.grade || 0,
        month: state.month,
        absence: prev.absence || "",
        generalNote: prev.generalNote || "",
        photo: prev.photo || "",
        font: prev.font || "",
        meta: prev.meta || {},
        data: state.subjects,
      };
      await env.EXAM_KV.put("lbdata:" + key, JSON.stringify(rec));
      await notifyReportCard(state.uuid, state.month);
      await tgSetState(chatId, null);
      await tgSend(chatId, "کارنامه‌ی «" + (rec.name || "دانش‌آموز") + "» برای ماه " + state.month + " ذخیره و برای والدین ارسال شد ✅", tgTeacherMenu());
      return;
    }
    if (data === "t_ws") {
      const students = await listStudents(env);
      const pending = [];
      for (const s of students) {
        const raw = await env.EXAM_KV.get("worksheet:" + s.uuid);
        if (!raw) continue;
        const rec = JSON.parse(raw);
        if (rec.studentFiles && rec.studentFiles.length) pending.push(s);
      }
      if (!pending.length) { await tgSend(chatId, "کاربرگ ارسالی جدیدی وجود ندارد.", tgBackRow()); return; }
      await tgSend(chatId, "دانش‌آموزان دارای کاربرگ ارسالی:", tgWithBack(pending.slice(0, 30).map((s) => [{ text: s.label || "—", callback_data: "t_ws_s:" + s.uuid }])));
      return;
    }
    if (data.indexOf("t_ws_s:") === 0) {
      const uuid = data.slice(7);
      const raw = await env.EXAM_KV.get("worksheet:" + uuid);
      const rec = raw ? JSON.parse(raw) : {};
      const files = rec.studentFiles || [];
      for (const f of files.slice(0, 6)) await tgSendFileFromDataUrl(chatId, f, "");
      if (!files.length) await tgSend(chatId, "فایلی ثبت نشده.");
      await tgSetState(chatId, { step: "ws_feedback", uuid });
      await tgSend(chatId, "بازخورد خود را برای این دانش‌آموز بفرستید:", tgBackRow());
      return;
    }
  }

  async function tgSendExamQuestion(chatId, state) {
    const meta = await getMeta(env, state.grade);
    const durationMinutes = state.durationMinutes || parseInt(meta.examDuration, 10) || 30;
    const elapsedMin = (Date.now() - state.startedAt) / 60000;
    if (elapsedMin >= durationMinutes) {
      await tgFinishExam(chatId, state, true);
      return;
    }
    const questions = await getQuestions(env, state.grade);
    if (state.idx >= questions.length) {
      const rows = tgWithBack([
        [{ text: "✅ ثبت نهایی آزمون", callback_data: "exam_submit" }],
        [{ text: "⏮ بازگشت به سوال قبل", callback_data: "exam_prev" }],
      ]);
      state.awaitingText = false;
      await tgSetState(chatId, state);
      await tgSend(chatId, "همه‌ی سوالات را دیدید. برای ثبت نهایی، دکمه‌ی زیر را بزنید:", rows);
      return;
    }
    const q = questions[state.idx];
    const remain = Math.max(0, Math.round(durationMinutes - elapsedMin));
    const plain = String(q.text || "").replace(/<[^>]*>/g, " ").replace(/&nbsp;/g, " ").replace(/\s+/g, " ").trim();
    let head = "❓ سوال " + (state.idx + 1) + " از " + questions.length + " (⏱ حدود " + remain + " دقیقه باقی‌مانده)\n\n" + plain;
    if (q.image) await tgSendFileFromDataUrl(chatId, q.image, "");
    let rows = [];
    if (q.type === "multiple") {
      rows = (q.options || []).map((o, oi) => [{ text: (["الف", "ب", "ج", "د"][oi] || String(oi + 1)) + ") " + String(o).slice(0, 60), callback_data: "exam_ans:" + oi }]);
    } else if (q.type === "truefalse") {
      rows = [[{ text: "✅ صحیح", callback_data: "exam_ans:true" }, { text: "❌ غلط", callback_data: "exam_ans:false" }]];
    }
    const nav = [];
    if (state.idx > 0) nav.push({ text: "⏮ قبلی", callback_data: "exam_prev" });
    nav.push({ text: "⏭ رد شدن", callback_data: "exam_skip" });
    rows.push(nav);
    if (q.type === "descriptive" || q.type === "short") {
      state.awaitingText = true;
      head += "\n\n✍️ پاسخ خود را به‌صورت متن تایپ کنید.";
    } else {
      state.awaitingText = false;
    }
    await tgSetState(chatId, state);
    await tgSend(chatId, head, tgWithBack(rows));
  }

  async function tgFinishExam(chatId, state, autoSubmit) {
    const existing = await env.EXAM_KV.get("submission:" + state.uuid);
    if (existing) {
      await tgSetState(chatId, null);
      await tgSend(chatId, "این آزمون قبلاً ثبت شده بود.", tgStudentMenu());
      return;
    }
    const meta = await getMeta(env, state.grade);
    const questions = await getQuestions(env, state.grade);
    const durationMinutes = parseInt(meta.examDuration, 10) || 30;
    const submittedAt = Date.now();
    const endTime = submittedAt + durationMinutes * 60 * 1000;
    const submission = {
      uuid: state.uuid,
      student: {
        name: (state.identity && state.identity.name) || "",
        fatherName: (state.identity && state.identity.fatherName) || "",
        nationalId: (state.identity && state.identity.nationalId) || "",
        courseName: (state.identity && state.identity.courseName) || "",
        examDate: (state.identity && state.identity.examDate) || "",
      },
      answers: state.answers || {},
      photoAnswers: {},
      meta,
      questionsSnapshot: questions,
      submittedAt,
      endTime,
      grading: null,
    };
    await env.EXAM_KV.put("submission:" + state.uuid, JSON.stringify(submission));
    await tgSetState(chatId, null);
    await tgSend(chatId, (autoSubmit ? "⏰ زمان آزمون تمام شد و " : "") + "✅ پاسخنامه‌ی شما با موفقیت ثبت شد. نتیجه پس از تصحیح توسط معلم اعلام می‌شود.", tgStudentMenu());
  }

  // چون بات مکالمه‌ای همیشه روشن است (webhook فعال)، هر پیامی که به بات می‌رسد بلافاصله همین‌جا
  // «مصرف» می‌شود و دیگر هیچ‌وقت با getUpdates قابل‌دریافت نیست (نه فقط تا زمانی که webhook فعال است).
  // به همین دلیل باید خودمان شناسه‌ی هر چتی که به بات پیام می‌دهد را همین‌جا در یک لاگ کوتاه ذخیره کنیم؛
  // تکیه به getUpdates برای «دریافت شناسه‌های اخیر» از وقتی بات مکالمه‌ای اضافه شده دیگر کار نمی‌کند.
  async function tgLogRecentChat(chatId, msg) {
    try {
      const chat = msg.chat || {};
      const nameParts = [chat.first_name, chat.last_name].filter(Boolean).join(" ");
      const name = nameParts || chat.title || chat.username || "";
      const text = (msg.text || "").slice(0, 200);
      const raw = await env.EXAM_KV.get("tg_recent_chats");
      let list = [];
      try { list = raw ? JSON.parse(raw) : []; } catch (e) { list = []; }
      list = list.filter((it) => String(it.chatId) !== String(chatId));
      list.unshift({ chatId: String(chatId), name, text, ts: Date.now() });
      list = list.slice(0, 30);
      await env.EXAM_KV.put("tg_recent_chats", JSON.stringify(list));
    } catch (e) {}
  }

  async function tgHandleUpdate(update) {
    if (update.callback_query) { await tgHandleCallback(update.callback_query); return; }
    const msg = update.message;
    if (!msg) return;
    const chatId = msg.chat.id;
    const text = (msg.text || "").trim();
    await tgLogRecentChat(chatId, msg);

    if (text.indexOf("/start") === 0) {
      const payload = text.slice(6).trim();
      if (payload) {
        const studentRaw = await env.EXAM_KV.get("student:" + payload);
        if (studentRaw) {
          await env.EXAM_KV.put("tgstudent:" + chatId, payload);
          await tgSetState(chatId, null);
          const st = JSON.parse(studentRaw);
          // شناسه چت تلگرام خود دانش‌آموز را هم روی رکوردش ذخیره می‌کنیم تا بشود مستقیماً
          // (مثلاً هنگام غیبت) بدون واسطه‌ی والدین به خودِ دانش‌آموز پیام داد.
          if (st.tgChatId !== String(chatId)) {
            st.tgChatId = String(chatId);
            await env.EXAM_KV.put("student:" + payload, JSON.stringify(st));
          }
          await tgSend(chatId, "سلام " + (st.label || "") + " 👋\nبه بات کلاس خوش آمدید. یکی از گزینه‌ها را انتخاب کنید:", tgStudentMenu());
          return;
        }
      }
      await tgSend(chatId, "سلام 👋\nاگر دانش‌آموز هستید، از لینک اختصاصی خودتان در پنل، دکمه‌ی «اتصال به بات تلگرام» را بزنید.\nاگر معلم هستید، این‌طور وارد شوید:\n/login رمزعبور_شما");
      return;
    }
    if (text.indexOf("/login") === 0) {
      const pass = text.slice(6).trim();
      const hash = await getTeacherHash(env);
      if (hash && pass && (await sha256(pass)) === hash) {
        await env.EXAM_KV.put("tgteacher:" + chatId, "1");
        await tgSetState(chatId, null);
        await tgSend(chatId, "ورود موفق ✅ یکی از گزینه‌ها را انتخاب کنید:", tgTeacherMenu());
      } else {
        await tgSend(chatId, "رمز عبور اشتباه است.");
      }
      return;
    }

    const state = await tgGetState(chatId);
    if (state) { await tgHandleStateMessage(chatId, msg, state); return; }

    const linkedStudent = await env.EXAM_KV.get("tgstudent:" + chatId);
    if (linkedStudent) { await tgSend(chatId, "یکی از گزینه‌ها را انتخاب کنید:", tgStudentMenu()); return; }
    const linkedTeacher = await env.EXAM_KV.get("tgteacher:" + chatId);
    if (linkedTeacher) { await tgSend(chatId, "یکی از گزینه‌ها را انتخاب کنید:", tgTeacherMenu()); return; }

    await tgSend(chatId, "برای شروع، از لینک اختصاصی‌تان استفاده کنید یا با /login وارد شوید.");
  }

  /* ============================================================
     🟠 بات مکالمه‌ای روبیکا (Rubika) — معادل کامل بات تلگرام بالا
     API روبیکا با تلگرام فرق دارد: دکمه‌ها به شکل inline_keypad
     (rows -> buttons -> {id,type:"Simple",button_text}) هستند و
     رویدادها (پیام یا کلیک دکمه) هر دو در قالب یک بروزرسانی مشابه
     می‌رسند (بدون callback_query جدا مثل تلگرام).
     ============================================================ */

  function rbKeypad(rows) {
    return { rows: rows.map((row) => ({ buttons: row.map((b) => ({ id: b.id, type: "Simple", button_text: b.text })) })) };
  }

  async function rbSend(chatId, text, rows) {
    const cfg = await getNotifySettings();
    if (!cfg.rubikaBotToken) return;
    const payload = { chat_id: chatId, text: text.slice(0, 4000) };
    if (rows) payload.inline_keypad = rbKeypad(rows);
    try {
      await fetch("https://botapi.rubika.ir/v3/" + cfg.rubikaBotToken + "/sendMessage", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(payload),
      });
    } catch (e) {}
  }

  function rbBackRow() {
    return [[{ text: "🔙 بازگشت به منوی اصلی", id: "back_main" }]];
  }
  function rbWithBack(rows) {
    return (rows || []).concat(rbBackRow());
  }

  async function rbSendFileFromDataUrl(chatId, dataUrl, caption) {
    const cfg = await getNotifySettings();
    if (!cfg.rubikaBotToken || !dataUrl) return;
    try {
      const comma = dataUrl.indexOf(",");
      const meta = dataUrl.slice(5, comma);
      const mime = meta.split(";")[0] || "image/jpeg";
      const b64 = dataUrl.slice(comma + 1);
      const bin = atob(b64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      const isPdf = mime.indexOf("pdf") !== -1;
      const fileType = isPdf ? "File" : "Image";
      const fileName = isPdf ? "file.pdf" : "file.jpg";
      const reqR = await fetch("https://botapi.rubika.ir/v3/" + cfg.rubikaBotToken + "/requestSendFile", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ type: fileType }),
      });
      const reqD = await reqR.json().catch(() => ({}));
      const uploadUrl = reqD && reqD.data && reqD.data.upload_url;
      if (!uploadUrl) return;
      const fd = new FormData();
      const blob = new Blob([bytes], { type: mime });
      fd.append("file", blob, fileName);
      const upR = await fetch(uploadUrl, { method: "POST", body: fd });
      const upD = await upR.json().catch(() => ({}));
      const fileId = upD && (upD.file_id || (upD.data && upD.data.file_id));
      if (!fileId) return;
      await fetch("https://botapi.rubika.ir/v3/" + cfg.rubikaBotToken + "/sendFile", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ chat_id: chatId, file_id: fileId, text: caption ? caption.slice(0, 1000) : undefined }),
      });
    } catch (e) {}
  }

  async function rbDownloadFileAsDataUrl(fileId) {
    const cfg = await getNotifySettings();
    if (!cfg.rubikaBotToken || !fileId) return null;
    try {
      const r = await fetch("https://botapi.rubika.ir/v3/" + cfg.rubikaBotToken + "/getFile", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ file_id: fileId }),
      });
      const d = await r.json().catch(() => ({}));
      const downloadUrl = d && d.data && d.data.download_url;
      if (!downloadUrl) return null;
      const fr = await fetch(downloadUrl);
      const buf = await fr.arrayBuffer();
      const bytes = new Uint8Array(buf);
      let bin = "";
      for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
      return "data:image/jpeg;base64," + btoa(bin);
    } catch (e) {
      return null;
    }
  }

  async function rbGetState(chatId) {
    const raw = await env.EXAM_KV.get("rbstate:" + chatId);
    return raw ? JSON.parse(raw) : null;
  }
  async function rbSetState(chatId, state) {
    if (state) await env.EXAM_KV.put("rbstate:" + chatId, JSON.stringify(state));
    else await env.EXAM_KV.delete("rbstate:" + chatId);
  }

  function rbRcSubjectRows(state) {
    const active = tgActiveSubjects(state.gradeIdx);
    const rows = active.map((name) => {
      const done = state.subjects[name];
      return [{ text: (done ? "✅ " : "▫️ ") + name + (done ? " (" + (TG_LEVEL_LABELS[done.level] || "") + ")" : ""), id: "rc_subj:" + name }];
    });
    rows.push([{ text: "➕ درس دیگر (تایپ آزاد)", id: "rc_custom" }]);
    rows.push([{ text: "✅ پایان و ذخیره", id: "rc_finish" }]);
    return rows;
  }

  function rbStudentMenu() {
    return [
      [{ text: "📊 کارنامه ماهیانه", id: "s_rc" }],
      [{ text: "📅 برنامه هفتگی", id: "s_sch" }],
      [{ text: "📓 کاربرگ", id: "s_ws" }],
      [{ text: "🏅 لوح‌های تقدیر", id: "s_cert" }],
      [{ text: "📝 آزمون آنلاین", id: "s_exam" }],
    ];
  }
  function rbTeacherMenu() {
    return [
      [{ text: "👨‍🎓 لیست دانش‌آموزان", id: "t_students" }],
      [{ text: "📝 ثبت سریع کارنامه", id: "t_rc" }],
      [{ text: "📓 کاربرگ‌های ارسالی", id: "t_ws" }],
      [{ text: "📊 آمار داشبورد", id: "t_stats" }],
    ];
  }

  async function rbHandleStateMessage(chatId, n, state) {
    if (state.step === "exam_identity") {
      const text = (n.text || "").trim();
      if (!text) { await rbSend(chatId, "لطفاً پاسخ را به صورت متن بفرستید.", rbBackRow()); return; }
      if (state.identStep === 0) {
        state.identity.fatherName = text.slice(0, 120);
        state.identStep = 1;
        await rbSetState(chatId, state);
        await rbSend(chatId, "کد ملی را تایپ کنید:", rbBackRow());
        return;
      }
      if (state.identStep === 1) {
        state.identity.nationalId = text.slice(0, 30);
        const stRaw = await env.EXAM_KV.get("student:" + state.uuid);
        const st = stRaw ? JSON.parse(stRaw) : {};
        const meta = await getMeta(env, state.grade);
        const newState = {
          step: "exam",
          uuid: state.uuid,
          grade: state.grade,
          idx: 0,
          answers: {},
          awaitingText: false,
          startedAt: Date.now(),
          durationMinutes: parseInt(meta.examDuration, 10) || 30,
          identity: {
            name: st.label || "",
            fatherName: state.identity.fatherName,
            nationalId: state.identity.nationalId,
            courseName: meta.examName || "",
            examDate: new Date().toLocaleDateString("fa-IR"),
          },
        };
        await rbSetState(chatId, newState);
        await rbSend(chatId, "✅ اطلاعات ثبت شد. آزمون شروع می‌شود.");
        await rbSendExamQuestion(chatId, newState);
        return;
      }
      return;
    }
    if (state.step === "exam" && state.awaitingText) {
      const text = (n.text || "").trim();
      if (!text) { await rbSend(chatId, "لطفاً پاسخ را به‌صورت متن بفرستید یا از دکمه‌ی «رد شدن» استفاده کنید."); return; }
      const questions = await getQuestions(env, state.grade);
      const q = questions[state.idx];
      if (q) state.answers[q.id] = text.slice(0, 4000);
      state.idx += 1;
      state.awaitingText = false;
      await rbSetState(chatId, state);
      await rbSendExamQuestion(chatId, state);
      return;
    }
    if (state.step === "ws_upload") {
      if (n.fileId) {
        const dataUrl = await rbDownloadFileAsDataUrl(n.fileId);
        if (!dataUrl) { await rbSend(chatId, "دریافت عکس با خطا مواجه شد."); return; }
        const raw = await env.EXAM_KV.get("worksheet:" + state.uuid);
        const rec = raw ? JSON.parse(raw) : { uuid: state.uuid };
        rec.studentFiles = (rec.studentFiles || []).concat([dataUrl]).slice(-6);
        rec.studentUploadedAt = Date.now();
        await env.EXAM_KV.put("worksheet:" + state.uuid, JSON.stringify(rec));
        await rbSend(chatId, "✅ عکس ثبت شد. می‌توانید عکس دیگری بفرستید یا «پایان» را تایپ کنید.");
        return;
      }
      if ((n.text || "").trim() === "پایان") {
        await rbSetState(chatId, null);
        await rbSend(chatId, "ارسال کاربرگ به پایان رسید ✅", rbStudentMenu());
        return;
      }
      await rbSend(chatId, "لطفاً عکسِ پاسخِ کاربرگ را بفرستید یا «پایان» را تایپ کنید.", rbBackRow());
      return;
    }
    if (state.step === "rc_collect") {
      const text = (n.text || "").trim();
      if (text === "پایان") {
        const studentRaw = await env.EXAM_KV.get("student:" + state.uuid);
        const st = studentRaw ? JSON.parse(studentRaw) : {};
        const key = "reportcard:student:" + state.uuid + ":" + state.month;
        const prevRaw = await env.EXAM_KV.get("lbdata:" + key);
        const prev = prevRaw ? JSON.parse(prevRaw) : {};
        const rec = {
          uuid: state.uuid,
          name: st.label || prev.name || "",
          grade: Number.isInteger(st.grade) ? st.grade : prev.grade || 0,
          month: state.month,
          absence: prev.absence || "",
          generalNote: prev.generalNote || "",
          photo: prev.photo || "",
          font: prev.font || "",
          meta: prev.meta || {},
          data: state.subjects,
        };
        await env.EXAM_KV.put("lbdata:" + key, JSON.stringify(rec));
        await notifyReportCard(state.uuid, state.month);
        await rbSetState(chatId, null);
        await rbSend(chatId, "کارنامه‌ی «" + (rec.name || "دانش‌آموز") + "» برای ماه " + state.month + " ذخیره و برای والدین ارسال شد ✅", rbTeacherMenu());
        return;
      }
      if (!state.awaitingCustom) {
        await rbSend(chatId, "لطفاً درس را از دکمه‌های بالا انتخاب کنید، یا روی «➕ درس دیگر» بزنید.", rbWithBack(rbRcSubjectRows(state)));
        return;
      }
      const parts = text.split(":");
      if (parts.length < 2) { await rbSend(chatId, "فرمت درست نیست. به این شکل بفرستید:\nنام‌درس: سطح\nمثال: خوشنویسی: خیلی خوب", rbBackRow()); return; }
      const subject = parts[0].trim();
      const levelText = parts.slice(1).join(":").trim();
      const level = TG_LEVEL_MAP[levelText] || "";
      if (!subject || !level) { await rbSend(chatId, "سطح باید یکی از این‌ها باشد: عالی، خوب، قابل‌قبول، ضعیف", rbBackRow()); return; }
      state.subjects[subject] = { level, note: "" };
      state.awaitingCustom = false;
      await rbSetState(chatId, state);
      await rbSend(chatId, "✅ ثبت شد: " + subject + " — " + (TG_LEVEL_LABELS[level] || level), rbWithBack(rbRcSubjectRows(state)));
      return;
    }
    if (state.step === "ws_feedback") {
      const text = (n.text || "").trim();
      if (!text) { await rbSend(chatId, "لطفاً بازخورد را به‌صورت متن بفرستید.", rbBackRow()); return; }
      const raw = await env.EXAM_KV.get("worksheet:" + state.uuid);
      const rec = raw ? JSON.parse(raw) : { uuid: state.uuid };
      rec.feedback = text.slice(0, 5000);
      rec.feedbackAt = Date.now();
      await env.EXAM_KV.put("worksheet:" + state.uuid, JSON.stringify(rec));
      await rbSetState(chatId, null);
      await rbSend(chatId, "بازخورد ثبت شد ✅", rbTeacherMenu());
      return;
    }
  }

  async function rbHandleButton(chatId, buttonId) {
    const data = buttonId || "";
    const studentUuid = await env.EXAM_KV.get("rbstudent:" + chatId);
    const isRbTeacher = Boolean(await env.EXAM_KV.get("rbteacher:" + chatId));

    if (data === "back_main") {
      const st0 = await rbGetState(chatId);
      if (!(st0 && st0.step === "exam")) await rbSetState(chatId, null);
      if (isRbTeacher) await rbSend(chatId, "یکی از گزینه‌ها را انتخاب کنید:", rbTeacherMenu());
      else if (studentUuid) await rbSend(chatId, "یکی از گزینه‌ها را انتخاب کنید:", rbStudentMenu());
      else await rbSend(chatId, "برای استفاده از ربات، از لینک اختصاصی‌تان استفاده کنید.");
      return;
    }

    if (data === "s_rc" && studentUuid) {
      await rbSend(chatId, "ماه مورد نظر را انتخاب کنید:", rbWithBack(TG_RC_MONTHS.map((m) => [{ text: m, id: "s_rc_m:" + m }])));
      return;
    }
    if (data.indexOf("s_rc_m:") === 0 && studentUuid) {
      const month = data.slice(7);
      const raw = await env.EXAM_KV.get("lbdata:reportcard:student:" + studentUuid + ":" + month);
      if (!raw) { await rbSend(chatId, "برای ماه " + month + " هنوز کارنامه‌ای ثبت نشده است.", rbBackRow()); return; }
      const rec = JSON.parse(raw);
      let t = "📊 کارنامه‌ی ماه " + month + "\n\n";
      const subs = rec.data || {};
      for (const name in subs) {
        const v = subs[name] || {};
        t += "▫️ " + name + ": " + (TG_LEVEL_LABELS[v.level] || "—") + (v.note ? " («" + v.note + "»)" : "") + "\n";
      }
      if (rec.absence) t += "\nغیبت: " + rec.absence;
      if (rec.generalNote) t += "\nتوضیح کلی: " + rec.generalNote;
      await rbSend(chatId, t, rbBackRow());
      return;
    }
    if (data === "s_sch" && studentUuid) {
      const stRaw = await env.EXAM_KV.get("student:" + studentUuid);
      const st = stRaw ? JSON.parse(stRaw) : {};
      const g = Number.isInteger(st.grade) ? st.grade : 0;
      const raw = await env.EXAM_KV.get("schedule_data:grade:" + g);
      if (!raw) { await rbSend(chatId, "برنامه‌ی هفتگی‌ای برای پایه‌ی شما ثبت نشده است.", rbBackRow()); return; }
      const sd = JSON.parse(raw);
      const days = ["شنبه", "یکشنبه", "دوشنبه", "سه‌شنبه", "چهارشنبه"];
      let t = "📅 برنامه‌ی هفتگی\n\n";
      for (let d = 0; d < 5; d++) {
        t += days[d] + "\n";
        for (let i = 1; i <= 5; i++) {
          const v = (sd.cells && sd.cells["c" + d + i]) || "—";
          t += "  زنگ " + i + ": " + v + "\n";
        }
        t += "\n";
      }
      await rbSend(chatId, t, rbBackRow());
      return;
    }
    if (data === "s_ws" && studentUuid) {
      const raw = await env.EXAM_KV.get("worksheet:" + studentUuid);
      const rec = raw ? JSON.parse(raw) : {};
      if (rec.teacherFile) await rbSendFileFromDataUrl(chatId, rec.teacherFile, "📓 کاربرگ شما");
      else await rbSend(chatId, "هنوز کاربرگی برای شما ارسال نشده است.");
      if (rec.feedback) await rbSend(chatId, "📝 بازخورد معلم: " + rec.feedback);
      await rbSetState(chatId, { step: "ws_upload", uuid: studentUuid });
      await rbSend(chatId, "برای ارسال پاسخ، عکس کاربرگ حل‌شده را همین‌جا بفرستید. بعد از اتمام «پایان» را بفرستید.", rbBackRow());
      return;
    }
    if (data === "s_cert" && studentUuid) {
      const raw = await env.EXAM_KV.get("certificates:" + studentUuid);
      const list = raw ? JSON.parse(raw) : [];
      if (!list.length) { await rbSend(chatId, "هنوز لوح تقدیری برای شما صادر نشده است.", rbBackRow()); return; }
      let t = "🏅 لوح‌های تقدیر شما:\n\n";
      list.slice(0, 15).forEach((c) => {
        t += "▫️ " + (c.title || "لوح تقدیر") + "\n" + url.origin + "/cert/" + encodeURIComponent(studentUuid) + "/" + encodeURIComponent(c.id || "") + "\n\n";
      });
      await rbSend(chatId, t, rbBackRow());
      return;
    }

    /* ----- 📝 آزمون آنلاین (سمت دانش‌آموز) ----- */
    if (data === "s_exam" && studentUuid) {
      const existingSub = await env.EXAM_KV.get("submission:" + studentUuid);
      if (existingSub) {
        await rbSend(chatId, "✅ شما قبلاً در این آزمون شرکت کرده‌اید. برای دیدن نتیجه به معلم مراجعه کنید.", rbBackRow());
        return;
      }
      const stRaw = await env.EXAM_KV.get("student:" + studentUuid);
      const st = stRaw ? JSON.parse(stRaw) : {};
      const grade = clampGrade(st.grade);
      const meta = await getMeta(env, grade);
      const questions = await getQuestions(env, grade);
      if (!questions.length) {
        await rbSend(chatId, "در حال حاضر آزمونی برای پایه‌ی شما تعریف نشده است.", rbBackRow());
        return;
      }
      const existingState = await rbGetState(chatId);
      if (existingState && existingState.step === "exam" && existingState.uuid === studentUuid) {
        await rbSendExamQuestion(chatId, existingState);
        return;
      }
      const identState = { step: "exam_identity", identStep: 0, uuid: studentUuid, grade, identity: {} };
      await rbSetState(chatId, identState);
      const head = "📝 " + (meta.examName || "آزمون") + "\n🏫 " + (meta.school || "") + "\n👨‍🏫 " + (meta.teacher || "") +
        "\n⏱ مدت زمان: " + (meta.examDuration || 30) + " دقیقه\n📚 تعداد سوالات: " + questions.length +
        "\n\nقبل از شروع، چند اطلاعات کوتاه نیاز است.\nلطفاً نام پدر را تایپ کنید:";
      await rbSend(chatId, head, rbBackRow());
      return;
    }
    if (data.indexOf("exam_ans:") === 0 && studentUuid) {
      const state = await rbGetState(chatId);
      if (!state || state.step !== "exam") return;
      const questions = await getQuestions(env, state.grade);
      const q = questions[state.idx];
      if (q) state.answers[q.id] = data.slice(9);
      state.idx += 1;
      state.awaitingText = false;
      await rbSetState(chatId, state);
      await rbSendExamQuestion(chatId, state);
      return;
    }
    if (data === "exam_skip" && studentUuid) {
      const state = await rbGetState(chatId);
      if (!state || state.step !== "exam") return;
      state.idx += 1;
      state.awaitingText = false;
      await rbSetState(chatId, state);
      await rbSendExamQuestion(chatId, state);
      return;
    }
    if (data === "exam_prev" && studentUuid) {
      const state = await rbGetState(chatId);
      if (!state || state.step !== "exam") return;
      state.idx = Math.max(0, state.idx - 1);
      state.awaitingText = false;
      await rbSetState(chatId, state);
      await rbSendExamQuestion(chatId, state);
      return;
    }
    if (data === "exam_submit" && studentUuid) {
      const state = await rbGetState(chatId);
      if (!state || state.step !== "exam") return;
      await rbFinishExam(chatId, state, false);
      return;
    }

    if (!isRbTeacher) return;

    if (data === "t_students") {
      await rbSend(chatId, "پایه را انتخاب کنید:", rbWithBack(TG_GRADE_LABELS.map((lab, idx) => [{ text: lab, id: "t_students_g:" + idx }])));
      return;
    }
    if (data.indexOf("t_students_g:") === 0) {
      const g = parseInt(data.slice(13), 10) || 0;
      const students = (await listStudents(env)).filter((s) => (Number.isInteger(s.grade) ? s.grade : 0) === g);
      if (!students.length) { await rbSend(chatId, "دانش‌آموزی برای این پایه ثبت نشده.", rbBackRow()); return; }
      const subs = await Promise.all(students.map((s) => env.EXAM_KV.get("submission:" + s.uuid)));
      let t = "👨‍🎓 دانش‌آموزان (" + students.length + " نفر):\n\n";
      students.forEach((s, i) => {
        let status = "بدون تکلیف ارسالی";
        if (subs[i]) { try { const sub = JSON.parse(subs[i]); status = sub.grading && sub.grading.graded ? "تصحیح‌شده ✅" : "در انتظار تصحیح ⏳"; } catch (e) {} }
        t += "▫️ " + (s.label || "—") + " — " + status + "\n";
      });
      const chunks = t.match(/[\s\S]{1,3500}/g) || [t];
      for (let i = 0; i < chunks.length; i++) await rbSend(chatId, chunks[i], i === chunks.length - 1 ? rbBackRow() : undefined);
      return;
    }
    if (data === "t_stats") {
      const stats = await computeDashboardStats();
      const t = "📊 آمار کلی:\n\nدانش‌آموزان: " + stats.studentsTotal + "\nتکالیف ارسالی: " + stats.submissionsTotal + " (تصحیح‌شده: " + stats.graded + " — در انتظار: " + stats.pending + ")\nلوح‌های تقدیر: " + stats.certsTotal + "\nثبت‌نام‌های حضور و غیاب: " + stats.attendanceTotal;
      await rbSend(chatId, t, rbBackRow());
      return;
    }
    if (data === "t_rc") {
      await rbSend(chatId, "پایه‌ی دانش‌آموز را انتخاب کنید:", rbWithBack(TG_GRADE_LABELS.map((lab, idx) => [{ text: lab, id: "t_rc_g:" + idx }])));
      return;
    }
    if (data.indexOf("t_rc_g:") === 0) {
      const g = parseInt(data.slice(7), 10) || 0;
      const students = (await listStudents(env)).filter((s) => (Number.isInteger(s.grade) ? s.grade : 0) === g);
      if (!students.length) { await rbSend(chatId, "دانش‌آموزی برای این پایه ثبت نشده.", rbBackRow()); return; }
      await rbSend(chatId, "دانش‌آموز را انتخاب کنید:", rbWithBack(students.slice(0, 30).map((s) => [{ text: s.label || "—", id: "t_rc_s:" + s.uuid }])));
      return;
    }
    if (data.indexOf("t_rc_s:") === 0) {
      const uuid = data.slice(7);
      await rbSend(chatId, "ماه را انتخاب کنید:", rbWithBack(TG_RC_MONTHS.map((m) => [{ text: m, id: "t_rc_m:" + uuid + ":" + m }])));
      return;
    }
    if (data.indexOf("t_rc_m:") === 0) {
      const rest = data.slice(7);
      const sep = rest.lastIndexOf(":");
      const uuid = rest.slice(0, sep);
      const month = rest.slice(sep + 1);
      const stRaw = await env.EXAM_KV.get("student:" + uuid);
      const stRec = stRaw ? JSON.parse(stRaw) : {};
      const gradeIdx = Number.isInteger(stRec.grade) ? stRec.grade : 0;
      const prevRaw = await env.EXAM_KV.get("lbdata:reportcard:student:" + uuid + ":" + month);
      const prevSubjects = prevRaw ? (JSON.parse(prevRaw).data || {}) : {};
      const state = { step: "rc_collect", uuid, month, gradeIdx, subjects: Object.assign({}, prevSubjects) };
      await rbSetState(chatId, state);
      await rbSend(chatId, "درس مورد نظر را انتخاب کنید و سطح ارزشیابی را بزنید. وقتی تمام شد «✅ پایان و ذخیره» را بزنید:", rbWithBack(rbRcSubjectRows(state)));
      return;
    }
    if (data.indexOf("rc_subj:") === 0) {
      const state = await rbGetState(chatId);
      if (!state || state.step !== "rc_collect") return;
      const subject = data.slice(8);
      await rbSend(chatId, "سطح ارزشیابی «" + subject + "» را انتخاب کنید:", rbWithBack(TG_LEVEL_OPTIONS.map((o) => [{ text: o[1], id: "rc_level:" + subject + ":" + o[0] }])));
      return;
    }
    if (data.indexOf("rc_level:") === 0) {
      const state = await rbGetState(chatId);
      if (!state || state.step !== "rc_collect") return;
      const rest = data.slice(9);
      const sep = rest.lastIndexOf(":");
      const subject = rest.slice(0, sep);
      const level = rest.slice(sep + 1);
      state.subjects[subject] = { level, note: (state.subjects[subject] && state.subjects[subject].note) || "" };
      await rbSetState(chatId, state);
      await rbSend(chatId, "✅ ثبت شد: " + subject + " — " + (TG_LEVEL_LABELS[level] || level), rbWithBack(rbRcSubjectRows(state)));
      return;
    }
    if (data === "rc_custom") {
      const state = await rbGetState(chatId);
      if (!state || state.step !== "rc_collect") return;
      state.awaitingCustom = true;
      await rbSetState(chatId, state);
      await rbSend(chatId, "نام درس و سطح را به این شکل تایپ کنید:\nنام‌درس: سطح\nسطح یکی از این‌ها: عالی، خوب، قابل‌قبول، ضعیف\nمثال: خوشنویسی: خیلی خوب", rbBackRow());
      return;
    }
    if (data === "rc_finish") {
      const state = await rbGetState(chatId);
      if (!state || state.step !== "rc_collect") return;
      const studentRaw = await env.EXAM_KV.get("student:" + state.uuid);
      const st = studentRaw ? JSON.parse(studentRaw) : {};
      const key = "reportcard:student:" + state.uuid + ":" + state.month;
      const prevRaw = await env.EXAM_KV.get("lbdata:" + key);
      const prev = prevRaw ? JSON.parse(prevRaw) : {};
      const rec = {
        uuid: state.uuid,
        name: st.label || prev.name || "",
        grade: Number.isInteger(st.grade) ? st.grade : prev.grade || 0,
        month: state.month,
        absence: prev.absence || "",
        generalNote: prev.generalNote || "",
        photo: prev.photo || "",
        font: prev.font || "",
        meta: prev.meta || {},
        data: state.subjects,
      };
      await env.EXAM_KV.put("lbdata:" + key, JSON.stringify(rec));
      await notifyReportCard(state.uuid, state.month);
      await rbSetState(chatId, null);
      await rbSend(chatId, "کارنامه‌ی «" + (rec.name || "دانش‌آموز") + "» برای ماه " + state.month + " ذخیره و برای والدین ارسال شد ✅", rbTeacherMenu());
      return;
    }
    if (data === "t_ws") {
      const students = await listStudents(env);
      const pending = [];
      for (const s of students) {
        const raw = await env.EXAM_KV.get("worksheet:" + s.uuid);
        if (!raw) continue;
        const rec = JSON.parse(raw);
        if (rec.studentFiles && rec.studentFiles.length) pending.push(s);
      }
      if (!pending.length) { await rbSend(chatId, "کاربرگ ارسالی جدیدی وجود ندارد.", rbBackRow()); return; }
      await rbSend(chatId, "دانش‌آموزان دارای کاربرگ ارسالی:", rbWithBack(pending.slice(0, 30).map((s) => [{ text: s.label || "—", id: "t_ws_s:" + s.uuid }])));
      return;
    }
    if (data.indexOf("t_ws_s:") === 0) {
      const uuid = data.slice(7);
      const raw = await env.EXAM_KV.get("worksheet:" + uuid);
      const rec = raw ? JSON.parse(raw) : {};
      const files = rec.studentFiles || [];
      for (const f of files.slice(0, 6)) await rbSendFileFromDataUrl(chatId, f, "");
      if (!files.length) await rbSend(chatId, "فایلی ثبت نشده.");
      await rbSetState(chatId, { step: "ws_feedback", uuid });
      await rbSend(chatId, "بازخورد خود را برای این دانش‌آموز بفرستید:", rbBackRow());
      return;
    }
  }

  async function rbSendExamQuestion(chatId, state) {
    const meta = await getMeta(env, state.grade);
    const durationMinutes = state.durationMinutes || parseInt(meta.examDuration, 10) || 30;
    const elapsedMin = (Date.now() - state.startedAt) / 60000;
    if (elapsedMin >= durationMinutes) {
      await rbFinishExam(chatId, state, true);
      return;
    }
    const questions = await getQuestions(env, state.grade);
    if (state.idx >= questions.length) {
      const rows = rbWithBack([
        [{ text: "✅ ثبت نهایی آزمون", id: "exam_submit" }],
        [{ text: "⏮ بازگشت به سوال قبل", id: "exam_prev" }],
      ]);
      state.awaitingText = false;
      await rbSetState(chatId, state);
      await rbSend(chatId, "همه‌ی سوالات را دیدید. برای ثبت نهایی، دکمه‌ی زیر را بزنید:", rows);
      return;
    }
    const q = questions[state.idx];
    const remain = Math.max(0, Math.round(durationMinutes - elapsedMin));
    const plain = String(q.text || "").replace(/<[^>]*>/g, " ").replace(/&nbsp;/g, " ").replace(/\s+/g, " ").trim();
    let head = "❓ سوال " + (state.idx + 1) + " از " + questions.length + " (⏱ حدود " + remain + " دقیقه باقی‌مانده)\n\n" + plain;
    if (q.image) await rbSendFileFromDataUrl(chatId, q.image, "");
    let rows = [];
    if (q.type === "multiple") {
      rows = (q.options || []).map((o, oi) => [{ text: (["الف", "ب", "ج", "د"][oi] || String(oi + 1)) + ") " + String(o).slice(0, 60), id: "exam_ans:" + oi }]);
    } else if (q.type === "truefalse") {
      rows = [[{ text: "✅ صحیح", id: "exam_ans:true" }, { text: "❌ غلط", id: "exam_ans:false" }]];
    }
    const nav = [];
    if (state.idx > 0) nav.push({ text: "⏮ قبلی", id: "exam_prev" });
    nav.push({ text: "⏭ رد شدن", id: "exam_skip" });
    rows.push(nav);
    if (q.type === "descriptive" || q.type === "short") {
      state.awaitingText = true;
      head += "\n\n✍️ پاسخ خود را به‌صورت متن تایپ کنید.";
    } else {
      state.awaitingText = false;
    }
    await rbSetState(chatId, state);
    await rbSend(chatId, head, rbWithBack(rows));
  }

  async function rbFinishExam(chatId, state, autoSubmit) {
    const existing = await env.EXAM_KV.get("submission:" + state.uuid);
    if (existing) {
      await rbSetState(chatId, null);
      await rbSend(chatId, "این آزمون قبلاً ثبت شده بود.", rbStudentMenu());
      return;
    }
    const meta = await getMeta(env, state.grade);
    const questions = await getQuestions(env, state.grade);
    const durationMinutes = parseInt(meta.examDuration, 10) || 30;
    const submittedAt = Date.now();
    const endTime = submittedAt + durationMinutes * 60 * 1000;
    const submission = {
      uuid: state.uuid,
      student: {
        name: (state.identity && state.identity.name) || "",
        fatherName: (state.identity && state.identity.fatherName) || "",
        nationalId: (state.identity && state.identity.nationalId) || "",
        courseName: (state.identity && state.identity.courseName) || "",
        examDate: (state.identity && state.identity.examDate) || "",
      },
      answers: state.answers || {},
      photoAnswers: {},
      meta,
      questionsSnapshot: questions,
      submittedAt,
      endTime,
      grading: null,
    };
    await env.EXAM_KV.put("submission:" + state.uuid, JSON.stringify(submission));
    await rbSetState(chatId, null);
    await rbSend(chatId, (autoSubmit ? "⏰ زمان آزمون تمام شد و " : "") + "✅ پاسخنامه‌ی شما با موفقیت ثبت شد. نتیجه پس از تصحیح توسط معلم اعلام می‌شود.", rbStudentMenu());
  }

  function rbNormalizeUpdate(body) {
    if (body && body.inline_message) {
      const im = body.inline_message;
      return { chatId: im.chat_id, text: im.text || "", buttonId: (im.aux_data && im.aux_data.button_id) || "", fileId: null };
    }
    const upd = (body && body.update) || body;
    if (!upd) return null;
    const nm = upd.new_message || upd;
    const chatId = upd.chat_id || nm.chat_id;
    if (!chatId) return null;
    return {
      chatId,
      text: nm.text || "",
      buttonId: (nm.aux_data && nm.aux_data.button_id) || "",
      fileId: (nm.file_inline && nm.file_inline.file_id) || null,
    };
  }

  // مشابه tgLogRecentChat: چون بات مکالمه‌ای روبیکا هم روی webhook کار می‌کند، getUpdates روبیکا هم
  // پیام‌های تازه را نمی‌بیند (خودِ webhook مصرفشان می‌کند)؛ پس همین‌جا لاگ می‌کنیم.
  async function rbLogRecentChat(chatId, text) {
    try {
      const raw = await env.EXAM_KV.get("rb_recent_chats");
      let list = [];
      try { list = raw ? JSON.parse(raw) : []; } catch (e) { list = []; }
      list = list.filter((it) => String(it.chatId) !== String(chatId));
      list.unshift({ chatId: String(chatId), text: String(text || "").slice(0, 200), ts: Date.now() });
      list = list.slice(0, 30);
      await env.EXAM_KV.put("rb_recent_chats", JSON.stringify(list));
    } catch (e) {}
  }

  async function rbHandleUpdate(body) {
    const n = rbNormalizeUpdate(body);
    if (!n || !n.chatId) return;
    const chatId = n.chatId;
    const text = (n.text || "").trim();
    await rbLogRecentChat(chatId, text);

    if (n.buttonId) { await rbHandleButton(chatId, n.buttonId); return; }

    if (text.indexOf("/start") === 0) {
      const payload = text.slice(6).trim();
      if (payload) {
        const studentRaw = await env.EXAM_KV.get("student:" + payload);
        if (studentRaw) {
          await env.EXAM_KV.put("rbstudent:" + chatId, payload);
          await rbSetState(chatId, null);
          const st = JSON.parse(studentRaw);
          // شناسه چت روبیکای خود دانش‌آموز را هم روی رکوردش ذخیره می‌کنیم تا بشود مستقیماً
          // (مثلاً هنگام غیبت) بدون واسطه‌ی والدین به خودِ دانش‌آموز پیام داد.
          if (st.rubikaChatId !== String(chatId)) {
            st.rubikaChatId = String(chatId);
            await env.EXAM_KV.put("student:" + payload, JSON.stringify(st));
          }
          await rbSend(chatId, "سلام " + (st.label || "") + " 👋\nبه بات کلاس خوش آمدید. یکی از گزینه‌ها را انتخاب کنید:", rbStudentMenu());
          return;
        }
      }
      await rbSend(chatId, "سلام 👋\nاگر دانش‌آموز هستید، از لینک اختصاصی خودتان در پنل، دکمه‌ی «اتصال به بات روبیکا» را بزنید.\nاگر معلم هستید، این‌طور وارد شوید:\n/login رمزعبور_شما");
      return;
    }
    if (text.indexOf("/login") === 0) {
      const pass = text.slice(6).trim();
      const hash = await getTeacherHash(env);
      if (hash && pass && (await sha256(pass)) === hash) {
        await env.EXAM_KV.put("rbteacher:" + chatId, "1");
        await rbSetState(chatId, null);
        await rbSend(chatId, "ورود موفق ✅ یکی از گزینه‌ها را انتخاب کنید:", rbTeacherMenu());
      } else {
        await rbSend(chatId, "رمز عبور اشتباه است.");
      }
      return;
    }

    const state = await rbGetState(chatId);
    if (state) { await rbHandleStateMessage(chatId, n, state); return; }

    const linkedStudent = await env.EXAM_KV.get("rbstudent:" + chatId);
    if (linkedStudent) { await rbSend(chatId, "یکی از گزینه‌ها را انتخاب کنید:", rbStudentMenu()); return; }
    const linkedTeacher = await env.EXAM_KV.get("rbteacher:" + chatId);
    if (linkedTeacher) { await rbSend(chatId, "یکی از گزینه‌ها را انتخاب کنید:", rbTeacherMenu()); return; }

    await rbSend(chatId, "برای شروع، از لینک اختصاصی‌تان استفاده کنید یا با /login وارد شوید.");
  }

  if (path === "/api/bot/webhook" && method === "POST") {
    const cfg = await getNotifySettings();
    const secretHeader = req.headers.get("x-telegram-bot-api-secret-token") || "";
    if (cfg.telegramWebhookSecret && secretHeader !== cfg.telegramWebhookSecret) return json({ ok: false }, 401);
    const update = await req.json().catch(() => null);
    if (update) { try { await tgHandleUpdate(update); } catch (e) {} }
    return json({ ok: true });
  }

  /* --- ثبت خودکار وبهوک بات تلگرام روی همین دامنه (فقط معلم) --- */
  if (path === "/api/teacher/bot/setup" && method === "POST") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const cfg = await getNotifySettings();
    if (!cfg.telegramBotToken) return json({ ok: false, error: "ابتدا توکن بات تلگرام را در تنظیمات ذخیره کنید" }, 400);
    const secret = cfg.telegramWebhookSecret || Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2);
    cfg.telegramWebhookSecret = secret;
    await env.EXAM_KV.put("settings:notify", JSON.stringify(cfg));
    try {
      const r = await fetch("https://api.telegram.org/bot" + cfg.telegramBotToken + "/setWebhook", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ url: url.origin + "/api/bot/webhook", secret_token: secret, allowed_updates: ["message", "callback_query"] }),
      });
      const d = await r.json().catch(() => ({}));
      if (!d || !d.ok) return json({ ok: false, error: (d && d.description) || "ثبت webhook ناموفق بود" });
      return json({ ok: true });
    } catch (e) {
      return json({ ok: false, error: "ارتباط با تلگرام برقرار نشد" });
    }
  }

  /* --- ساخت دیپ‌لینک اتصال بات برای یک دانش‌آموز خاص --- */
  if (path.startsWith("/api/teacher/bot/student-link/") && method === "GET") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const uuid = decodeURIComponent(path.slice("/api/teacher/bot/student-link/".length));
    const cfg = await getNotifySettings();
    if (!cfg.telegramBotUsername) return json({ ok: false, error: "نام کاربری بات تلگرام در تنظیمات ثبت نشده (بدون @، مثل: MyClassBot)" }, 400);
    return json({ ok: true, link: "https://t.me/" + cfg.telegramBotUsername + "?start=" + encodeURIComponent(uuid) });
  }

  /* ==================== پایان بات مکالمه‌ای تلگرام ==================== */

  /* ==================== 🟠 بات مکالمه‌ای روبیکا ==================== */
  if (path === "/api/rubika/webhook" && method === "POST") {
    const body = await req.json().catch(() => null);
    if (body) { try { await rbHandleUpdate(body); } catch (e) {} }
    return json({ ok: true });
  }

  /* --- ثبت خودکار endpoint بات روبیکا روی همین دامنه (فقط معلم) --- */
  if (path === "/api/teacher/rubika/setup" && method === "POST") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const cfg = await getNotifySettings();
    if (!cfg.rubikaBotToken) return json({ ok: false, error: "ابتدا توکن بات روبیکا را در تنظیمات ذخیره کنید" }, 400);
    async function rbRegisterEndpoint(type) {
      const r = await fetch("https://botapi.rubika.ir/v3/" + cfg.rubikaBotToken + "/updateBotEndpoints", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ url: url.origin + "/api/rubika/webhook", type }),
      });
      const d = await r.json().catch(() => ({}));
      if (!d || (d.status && d.status !== "OK") || d.error) {
        return { ok: false, error: (d && (d.dev_message || d.error || d.message || d.status)) || "ثبت endpoint ناموفق بود" };
      }
      return { ok: true };
    }
    try {
      // پیام‌های متنی (دستورها) از کانال ReceiveUpdate می‌آیند
      const r1 = await rbRegisterEndpoint("ReceiveUpdate");
      if (!r1.ok) return json({ ok: false, error: "پیام‌های متنی: " + r1.error });
      // کلیک روی دکمه‌های inline_keypad از یک کانال جداگانه (ReceiveInlineMessage) می‌آید
      const r2 = await rbRegisterEndpoint("ReceiveInlineMessage");
      if (!r2.ok) return json({ ok: false, error: "دکمه‌های اینلاین: " + r2.error });
      return json({ ok: true });
    } catch (e) {
      return json({ ok: false, error: "ارتباط با روبیکا برقرار نشد" });
    }
  }

  /* --- ساخت دیپ‌لینک اتصال بات روبیکا برای یک دانش‌آموز خاص --- */
  if (path.startsWith("/api/teacher/rubika/student-link/") && method === "GET") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const uuid = decodeURIComponent(path.slice("/api/teacher/rubika/student-link/".length));
    const cfg = await getNotifySettings();
    if (!cfg.rubikaBotUsername) return json({ ok: false, error: "نام کاربری بات روبیکا در تنظیمات ثبت نشده (بدون @)" }, 400);
    return json({ ok: true, link: "https://rubika.ir/" + cfg.rubikaBotUsername + "?start=" + encodeURIComponent(uuid) });
  }
  /* ==================== پایان بات مکالمه‌ای روبیکا ==================== */

  /* --- معلم: ورود/خروج --- */
  if (path === "/api/teacher/login" && method === "POST") {
    const body = await req.json().catch(() => ({}));
    const pass = String(body.password || "");
    const stored = await getTeacherHash(env);
    const cookieFor = (h) => `t_auth=${h}; Path=/; HttpOnly; SameSite=Lax; Max-Age=86400`;
    if (!stored) {
      if (pass.length < 4) return json({ ok: false, error: "رمز باید حداقل ۴ کاراکتر باشد" }, 400);
      const hash = await sha256(pass);
      await env.EXAM_KV.put("teacher_pass", hash);
      return json({ ok: true, created: true }, 200, { "set-cookie": cookieFor(hash) });
    }
    const hash = await sha256(pass);
    if (hash === stored) return json({ ok: true }, 200, { "set-cookie": cookieFor(hash) });
    return json({ ok: false, error: "رمز عبور اشتباه است" }, 401);
  }

  if (path === "/api/teacher/logout" && method === "POST") {
    return json({ ok: true }, 200, { "set-cookie": "t_auth=; Path=/; Max-Age=0" });
  }

  if (path === "/api/teacher/state" && method === "GET") {
    const stored = await getTeacherHash(env);
    return json({ ok: true, auth: await isTeacher(req, env), configured: Boolean(stored) });
  }

  /* --- آزمون دانش‌آموز (عمومی) --- */
  if (path.startsWith("/api/exam/")) {
    const rest = path.slice("/api/exam/".length);
    const parts = rest.split("/");
    const id = decodeURIComponent(parts[0] || "");
    const studentRaw = await env.EXAM_KV.get("student:" + id);
    if (!studentRaw) return json({ ok: false, error: "لینک نامعتبر است" }, 404);
    const st = JSON.parse(studentRaw);
    const studentGrade = clampGrade(st.grade);

    if (parts[1] === "submit" && method === "POST") {
      const existing = await env.EXAM_KV.get("submission:" + id);
      if (existing) return json({ ok: false, error: "این آزمون قبلاً ثبت شده است" }, 409);
      
      const body = await req.json().catch(() => ({}));
      const meta = await getMeta(env, studentGrade);
      const questions = await getQuestions(env, studentGrade);
      
      const durationMinutes = parseInt(meta.examDuration) || 30;
      const endTime = Date.now() + (durationMinutes * 60 * 1000);
      
      const submission = {
        uuid: id,
        student: {
          name: String(body.name || "").slice(0, 120),
          fatherName: String(body.fatherName || "").slice(0, 120),
          nationalId: String(body.nationalId || "").slice(0, 30),
          courseName: String(body.courseName || "").slice(0, 120),
          examDate: String(body.examDate || "").slice(0, 40),
        },
        answers: body.answers || {},
        photoAnswers: body.photoAnswers || {},
        meta,
        questionsSnapshot: questions,
        submittedAt: Date.now(),
        endTime: endTime,
        grading: null,
      };
      await env.EXAM_KV.put("submission:" + id, JSON.stringify(submission));
      return json({ ok: true });
    }

    if (method === "GET") {
      const meta = await getMeta(env, studentGrade);
      const subRaw = await env.EXAM_KV.get("submission:" + id);
      
      if (subRaw) {
        const sub = JSON.parse(subRaw);
        const resultQuestions = (sub.questionsSnapshot || []).map(safeQuestion);
        
        const now = Date.now();
        const remaining = Math.max(0, Math.floor((sub.endTime - now) / 1000));
        const isExpired = remaining <= 0;
        
        return json({
          ok: true,
          meta,
          grade: studentGrade,
          submitted: true,
          timeCheck: true,
          remaining: remaining,
          isExpired: isExpired,
          label: st.label || "",
          photo: st.photo || "",
          result: {
            questions: resultQuestions,
            answers: sub.answers || {},
            student: sub.student || {},
            grading: sub.grading || null,
          },
        });
      }
      const questions = (await getQuestions(env, studentGrade)).map(safeQuestion);
      const durationMinutes = parseInt(meta.examDuration) || 30;
      
      return json({ 
        ok: true, 
        meta, 
        grade: studentGrade,
        submitted: false, 
        questions, 
        label: st.label || "", 
        photo: st.photo || "",
        timeCheck: true,
        duration: durationMinutes * 60
      });
    }
  }

  /* --- کاربرگ دانش‌آموز (عمومی) --- */
  if (path.startsWith("/api/worksheet/")) {
    const rest = path.slice("/api/worksheet/".length);
    const parts = rest.split("/");
    const id = decodeURIComponent(parts[0] || "");
    const studentRaw = await env.EXAM_KV.get("student:" + id);
    if (!studentRaw) return json({ ok: false, error: "لینک نامعتبر است" }, 404);
    const st = JSON.parse(studentRaw);

    if (parts[1] === "submit" && method === "POST") {
      const body = await req.json().catch(() => ({}));
      const photos = Array.isArray(body.photos) ? body.photos.slice(0, 6) : [];
      for (const p of photos) {
        if (typeof p !== "string" || !p.startsWith("data:image/")) return json({ ok: false, error: "فرمت عکس نامعتبر است" }, 400);
        if (p.length > 2_800_000) return json({ ok: false, error: "حجم یکی از عکس‌ها بیش از حد مجاز است (حداکثر ۲ مگابایت)" }, 400);
      }
      if (!photos.length) return json({ ok: false, error: "حداقل یک عکس باید بارگذاری شود" }, 400);
      const raw = await env.EXAM_KV.get("worksheet:" + id);
      const rec = raw ? JSON.parse(raw) : { uuid: id };
      rec.studentFiles = photos;
      rec.studentUploadedAt = Date.now();
      await env.EXAM_KV.put("worksheet:" + id, JSON.stringify(rec));
      return json({ ok: true });
    }

    if (method === "GET") {
      const raw = await env.EXAM_KV.get("worksheet:" + id);
      const rec = raw ? JSON.parse(raw) : {};
      return json({
        ok: true,
        label: st.label || "",
        teacherFile: rec.teacherFile || "",
        teacherFileName: rec.teacherFileName || "",
        teacherFileType: rec.teacherFileType || "",
        teacherUploadedAt: rec.teacherUploadedAt || null,
        studentFiles: rec.studentFiles || [],
        studentUploadedAt: rec.studentUploadedAt || null,
        feedback: rec.feedback || "",
        feedbackAt: rec.feedbackAt || null,
      });
    }
  }

  /* --- برنامه‌ی هفتگی پایه‌ی دانش‌آموز (عمومی، فقط خواندنی) --- */
  if (path.startsWith("/api/student/schedule/")) {
    const uuid = decodeURIComponent(path.slice("/api/student/schedule/".length));
    const studentRaw = await env.EXAM_KV.get("student:" + uuid);
    if (!studentRaw) return json({ ok: false, error: "لینک نامعتبر است" }, 404);
    const studentRec = JSON.parse(studentRaw);
    const g = Number.isInteger(studentRec.grade) ? studentRec.grade : 0;
    let raw = await env.EXAM_KV.get("schedule_data:grade:" + g);
    if (!raw && g === 0) raw = await env.EXAM_KV.get("schedule_data");
    return json({ ok: true, data: raw ? JSON.parse(raw) : null });
  }

  /* --- کارنامه‌ی ماهیانه‌ی دانش‌آموز (عمومی، فقط خواندنی) --- */
  if (path.startsWith("/api/student/reportcard/")) {
    const uuid = decodeURIComponent(path.slice("/api/student/reportcard/".length));
    const studentRaw = await env.EXAM_KV.get("student:" + uuid);
    if (!studentRaw) return json({ ok: false, error: "لینک نامعتبر است" }, 404);
    const RC_MONTHS = ["مهر", "آبان", "آذر", "دی", "بهمن", "اسفند", "فروردین", "اردیبهشت"];
    const months = {};
    for (const m of RC_MONTHS) {
      const raw = await env.EXAM_KV.get("lbdata:reportcard:student:" + uuid + ":" + m);
      if (raw) months[m] = JSON.parse(raw);
    }
    return json({ ok: true, months });
  }

  /* --- لوح تقدیر: فهرست لوح‌های صادرشده برای یک دانش‌آموز (عمومی، فقط خواندنی) --- */
  if (path.startsWith("/api/student/certificates/")) {
    const certStudentUuid = decodeURIComponent(path.slice("/api/student/certificates/".length));
    const studentRaw = await env.EXAM_KV.get("student:" + certStudentUuid);
    if (!studentRaw) return json({ ok: false, error: "لینک نامعتبر است" }, 404);
    const listRaw = await env.EXAM_KV.get("certificates:" + certStudentUuid);
    const list = listRaw ? JSON.parse(listRaw) : [];
    return json({ ok: true, items: list.map((c) => ({ id: c.id, title: c.title, issuedAt: c.issuedAt })) });
  }

  /* --- دریافت و ارسال اطلاعات: صفحه‌ی عمومی لینک اختصاصی (بدون نیاز به ورود) --- */
  if (path.startsWith("/api/info/link/") && !path.includes("/reply")) {
    const rest = path.slice("/api/info/link/".length);
    const parts = rest.split("/");
    const linkId = decodeURIComponent(parts[0] || "");

    if (parts.length === 1 && method === "GET") {
      const raw = await env.EXAM_KV.get("infolink:" + linkId);
      if (!raw) return json({ ok: false, error: "این لینک معتبر نیست" }, 404, INFO_CORS_HEADERS);
      const meta = JSON.parse(raw);
      return json({ ok: true, ownerName: meta.ownerName, ownerRole: meta.ownerRole }, 200, INFO_CORS_HEADERS);
    }

    if (parts[1] === "send" && method === "POST") {
      const raw = await env.EXAM_KV.get("infolink:" + linkId);
      if (!raw) return json({ ok: false, error: "این لینک معتبر نیست" }, 404, INFO_CORS_HEADERS);
      const body = await req.json().catch(() => ({}));
      const senderName = String(body.senderName || "").slice(0, 80);
      const message = String(body.message || "").slice(0, 3000);
      const files = Array.isArray(body.files) ? body.files.slice(0, 6) : [];
      if (!senderName) return json({ ok: false, error: "نام فرستنده الزامی است" }, 400, INFO_CORS_HEADERS);
      if (!message && !files.length) return json({ ok: false, error: "پیام یا حداقل یک فایل الزامی است" }, 400, INFO_CORS_HEADERS);
      for (const f of files) {
        if (!f || typeof f.data !== "string" || !/^data:(image\/|application\/pdf|application\/vnd\.|application\/msword)/.test(f.data)) {
          return json({ ok: false, error: "فرمت یکی از فایل‌ها معتبر نیست" }, 400, INFO_CORS_HEADERS);
        }
        if (f.data.length > 6_000_000) return json({ ok: false, error: "حجم یکی از فایل‌ها بیش از حد مجاز است (حداکثر ۴ مگابایت)" }, 400, INFO_CORS_HEADERS);
      }
      const code = Math.random().toString(36).slice(2, 8).toUpperCase();
      const inboxRaw = await env.EXAM_KV.get("infolink-inbox:" + linkId);
      const inbox = inboxRaw ? JSON.parse(inboxRaw) : [];
      inbox.unshift({
        code, senderName, message,
        files: files.map((f) => ({ name: f.name || "فایل", mime: f.mime || "", data: f.data })),
        reply: null, createdAt: Date.now(),
      });
      await env.EXAM_KV.put("infolink-inbox:" + linkId, JSON.stringify(inbox.slice(0, 300)));
      return json({ ok: true, code }, 200, INFO_CORS_HEADERS);
    }

    if (parts[1] === "thread" && parts[2] && method === "GET") {
      const code = decodeURIComponent(parts[2]);
      const inboxRaw = await env.EXAM_KV.get("infolink-inbox:" + linkId);
      const inbox = inboxRaw ? JSON.parse(inboxRaw) : [];
      const thread = inbox.find((t) => t.code === code);
      if (!thread) return json({ ok: false, error: "کدی با این مشخصات پیدا نشد" }, 404, INFO_CORS_HEADERS);
      return json({ ok: true, thread }, 200, INFO_CORS_HEADERS);
    }
  }

  /* --- بازی و محتوای درسی HTML (عمومی، فقط لیست عنوان‌ها؛ فقط خواندنی؛ فیلترشده بر اساس پایه) --- */
  if (path === "/api/htmlcontent" && method === "GET") {
    const raw = await env.EXAM_KV.get("htmlcontent-index");
    const list = raw ? JSON.parse(raw) : [];
    const gradeParam = url.searchParams.get("grade");
    const wantGrade = gradeParam !== null && gradeParam !== "" ? parseInt(gradeParam, 10) : null;
    const filtered = wantGrade === null ? list : list.filter((it) => it.grade === undefined || it.grade === null || it.grade === wantGrade);
    return json({ ok: true, items: filtered.map((it) => ({ id: it.id, title: it.title, grade: it.grade })) });
  }

  /* --- لینک فیلم درس (عمومی، فقط لیست؛ فقط خواندنی؛ فیلترشده بر اساس پایه) --- */
  if (path === "/api/videolinks" && method === "GET") {
    const raw = await env.EXAM_KV.get("videolinks-index");
    const list = raw ? JSON.parse(raw) : [];
    const gradeParam = url.searchParams.get("grade");
    const wantGrade = gradeParam !== null && gradeParam !== "" ? parseInt(gradeParam, 10) : null;
    const filtered = wantGrade === null ? list : list.filter((it) => it.grade === undefined || it.grade === null || it.grade === wantGrade);
    return json({ ok: true, items: filtered.map((it) => ({ id: it.id, title: it.title, grade: it.grade, url: it.url })) });
  }

  /* --- وبینار: موضوع/عنوان (لینک ثابت و واحد است، فقط موضوع قابل تنظیم است) --- */
  /* عمومی است (بدون نیاز به ورود معلم برای GET)، پس باید قبل از دیوار «از این به بعد فقط معلم» باشد */
  if (path === "/api/webinar/topic" && method === "GET") {
    const topic = (await env.EXAM_KV.get("webinar:topic")) || "";
    return json({ ok: true, topic });
  }
  if (path === "/api/webinar/topic" && method === "POST") {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
    const body = await req.json().catch(() => ({}));
    const topic = String(body.topic || "").slice(0, 200);
    await env.EXAM_KV.put("webinar:topic", topic);
    return json({ ok: true, topic });
  }

  /* --- فرم حضور و غیاب: می‌تواند چند «لیست/لینک» جدا داشته باشد؛ ثبت‌شده‌ها برای معلم قابل مشاهده است --- */
  /* عمومی است (بدون نیاز به ورود معلم)، پس باید قبل از دیوار «از این به بعد فقط معلم» باشد */
  if (path === "/api/attendance/submit" && method === "POST") {
    const body = await req.json().catch(() => ({}));
    const name = String(body.name || "").trim().slice(0, 80);
    const family = String(body.family || "").trim().slice(0, 80);
    const nationalCode = String(body.nationalCode || "").trim().slice(0, 20);
    const school = String(body.school || "").trim().slice(0, 150);
    const region = String(body.region || "").trim().slice(0, 100);
    let linkId = String(body.linkId || "default").trim().slice(0, 80) || "default";
    if (!name || !family) return json({ ok: false, error: "نام و نام خانوادگی الزامی است" }, 400);
    if (linkId !== "default") {
      const linkRaw = await env.EXAM_KV.get("attlink:" + linkId);
      if (!linkRaw) return json({ ok: false, error: "این لینک معتبر نیست یا حذف شده است" }, 400);
    }
    const id = uuid();
    const rec = { id, linkId, name, family, nationalCode, school, region, role: "", ts: Date.now() };
    await env.EXAM_KV.put("attendance:" + id, JSON.stringify(rec));
    await bumpAttendanceCount(env, linkId, 1);
    return json({ ok: true });
  }

  /* --- از این به بعد فقط معلم --- */
  if (path.startsWith("/api/teacher/")) {
    if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);

    if (path === "/api/teacher/password" && method === "POST") {
      const body = await req.json().catch(() => ({}));
      const np = String(body.newPassword || "");
      if (np.length < 4) return json({ ok: false, error: "رمز جدید باید حداقل ۴ کاراکتر باشد" }, 400);
      const hash = await sha256(np);
      await env.EXAM_KV.put("teacher_pass", hash);
      return json({ ok: true }, 200, { "set-cookie": `t_auth=${hash}; Path=/; HttpOnly; SameSite=Lax; Max-Age=86400` });
    }

    if (path === "/api/teacher/schedule" && method === "GET") {
      let g = parseInt(url.searchParams.get("grade"), 10);
      if (!Number.isInteger(g) || g < 0 || g > 11) g = 0;
      let raw = await env.EXAM_KV.get("schedule_data:grade:" + g);
      if (!raw && g === 0) raw = await env.EXAM_KV.get("schedule_data"); // سازگاری با داده‌ی قدیمی تک‌برنامه‌ای
      return json({ ok: true, data: raw ? JSON.parse(raw) : null });
    }

    /* --- دریافت و ارسال اطلاعات: مدیریت لینک‌های اختصاصی (فقط معلم/راهبر/مدیر با ورود) --- */
    if (path === "/api/teacher/info-links" && method === "GET") {
      const raw = await env.EXAM_KV.get("infolinks-index");
      const list = raw ? JSON.parse(raw) : [];
      return json({ ok: true, links: list });
    }
    if (path === "/api/teacher/info-links" && method === "POST") {
      const body = await req.json().catch(() => ({}));
      const ownerName = String(body.ownerName || "").slice(0, 80);
      const ownerRole = String(body.ownerRole || "معلم").slice(0, 40);
      if (!ownerName) return json({ ok: false, error: "نام الزامی است" }, 400);
      const linkId = uuid();
      const rec = { uuid: linkId, ownerName, ownerRole, createdAt: Date.now() };
      await env.EXAM_KV.put("infolink:" + linkId, JSON.stringify(rec));
      const idxRaw = await env.EXAM_KV.get("infolinks-index");
      const idx = idxRaw ? JSON.parse(idxRaw) : [];
      idx.unshift(rec);
      await env.EXAM_KV.put("infolinks-index", JSON.stringify(idx));
      return json({ ok: true, link: rec });
    }
    if (path.startsWith("/api/teacher/info-links/") && method === "DELETE") {
      const linkId = decodeURIComponent(path.slice("/api/teacher/info-links/".length));
      await env.EXAM_KV.delete("infolink:" + linkId);
      await env.EXAM_KV.delete("infolink-inbox:" + linkId);
      const idxRaw = await env.EXAM_KV.get("infolinks-index");
      const idx = idxRaw ? JSON.parse(idxRaw) : [];
      await env.EXAM_KV.put("infolinks-index", JSON.stringify(idx.filter((l) => l.uuid !== linkId)));
      return json({ ok: true });
    }
    if (path.startsWith("/api/teacher/info-links/") && path.endsWith("/inbox") && method === "GET") {
      const linkId = decodeURIComponent(path.slice("/api/teacher/info-links/".length, -"/inbox".length));
      const raw = await env.EXAM_KV.get("infolink-inbox:" + linkId);
      return json({ ok: true, inbox: raw ? JSON.parse(raw) : [] });
    }
    if (path.startsWith("/api/teacher/info-links/") && path.includes("/thread/") && method === "DELETE") {
      const rest = path.slice("/api/teacher/info-links/".length);
      const [linkId, , code] = rest.split("/"); // linkId / thread / code
      const raw = await env.EXAM_KV.get("infolink-inbox:" + linkId);
      const inbox = raw ? JSON.parse(raw) : [];
      await env.EXAM_KV.put("infolink-inbox:" + linkId, JSON.stringify(inbox.filter((t) => t.code !== decodeURIComponent(code))));
      return json({ ok: true });
    }
    if (path.startsWith("/api/teacher/info-links/") && path.includes("/thread/") && path.endsWith("/reply") && method === "POST") {
      const rest = path.slice("/api/teacher/info-links/".length);
      const [linkId, , code] = rest.split("/"); // linkId / thread / code / reply
      const body = await req.json().catch(() => ({}));
      const message = String(body.message || "").slice(0, 3000);
      const files = Array.isArray(body.files) ? body.files.slice(0, 6) : [];
      for (const f of files) {
        if (!f || typeof f.data !== "string" || !/^data:(image\/|application\/pdf|application\/vnd\.|application\/msword)/.test(f.data)) {
          return json({ ok: false, error: "فرمت یکی از فایل‌ها معتبر نیست" }, 400);
        }
        if (f.data.length > 6_000_000) return json({ ok: false, error: "حجم یکی از فایل‌ها بیش از حد مجاز است (حداکثر ۴ مگابایت)" }, 400);
      }
      const inboxRaw = await env.EXAM_KV.get("infolink-inbox:" + linkId);
      const inbox = inboxRaw ? JSON.parse(inboxRaw) : [];
      const thread = inbox.find((t) => t.code === decodeURIComponent(code));
      if (!thread) return json({ ok: false, error: "پیام پیدا نشد" }, 404);
      thread.reply = { message, files: files.map((f) => ({ name: f.name || "فایل", mime: f.mime || "", data: f.data })), repliedAt: Date.now() };
      await env.EXAM_KV.put("infolink-inbox:" + linkId, JSON.stringify(inbox));
      return json({ ok: true });
    }

    /* --- دریافت و ارسال اطلاعات: پیام‌های ارسالی معلم (بدون نیاز به کد رهگیری) --- */
    if (path === "/api/teacher/info-outbox" && method === "GET") {
      const raw = await env.EXAM_KV.get("infoex-outbox");
      return json({ ok: true, outbox: raw ? JSON.parse(raw) : [] });
    }
    if (path === "/api/teacher/info-outbox" && method === "POST") {
      const body = await req.json().catch(() => ({}));
      const rec = {
        id: uuid(),
        targetOrigin: String(body.targetOrigin || "").slice(0, 300),
        targetCode: String(body.targetCode || "").slice(0, 60),
        targetLabel: String(body.targetLabel || "").slice(0, 120),
        senderName: String(body.senderName || "").slice(0, 80),
        message: String(body.message || "").slice(0, 3000),
        files: Array.isArray(body.files) ? body.files.slice(0, 6).map((f) => ({ name: f && f.name || "فایل" })) : [],
        trackingCode: String(body.trackingCode || "").slice(0, 20),
        createdAt: Date.now(),
      };
      const raw = await env.EXAM_KV.get("infoex-outbox");
      const list = raw ? JSON.parse(raw) : [];
      list.unshift(rec);
      await env.EXAM_KV.put("infoex-outbox", JSON.stringify(list.slice(0, 300)));
      return json({ ok: true, sent: rec });
    }
    if (path.startsWith("/api/teacher/info-outbox/") && method === "DELETE") {
      const id = decodeURIComponent(path.slice("/api/teacher/info-outbox/".length));
      const raw = await env.EXAM_KV.get("infoex-outbox");
      const list = raw ? JSON.parse(raw) : [];
      await env.EXAM_KV.put("infoex-outbox", JSON.stringify(list.filter((r) => r.id !== id)));
      return json({ ok: true });
    }

    if (path === "/api/teacher/schedule" && method === "POST") {
      const body = await req.json().catch(() => ({}));
      let g = parseInt(body.grade, 10);
      if (!Number.isInteger(g) || g < 0 || g > 11) g = 0;
      await env.EXAM_KV.put("schedule_data:grade:" + g, JSON.stringify(body.data || {}));
      // «ذخیره و ارسال»: وقتی body.notify=true باشد، برای همه‌ی دانش‌آموزان همین پایه (بر اساس s.grade)
      // از هر کانالی که برایشان ثبت شده (تلگرام/روبیکا/بله/پیامک) پیام اطلاع‌رسانی با لینک پنل ارسال می‌شود.
      // پیش از این، ذخیره‌ی برنامه‌ی هفتگی اصلاً هیچ پیامی نمی‌فرستاد؛ برخلاف کارنامه/کاربرگ/لوح تقدیر که
      // این مسیر را داشتند و همین باعث می‌شد دانش‌آموز هیچ‌وقت در تلگرام خبردار نشود.
      let notify = null;
      if (body.notify) {
        notify = {
          studentsInGrade: 0,
          studentsWithChannel: 0,
          telegram: { sent: 0, failed: 0, errors: [] },
          rubika: { sent: 0, failed: 0, errors: [] },
          bale: { sent: 0, failed: 0, errors: [] },
          sms: { sent: 0, failed: 0, errors: [] },
          tokenMissing: [],
        };
        try {
          const cfg = await getNotifySettings();
          if (!cfg.telegramBotToken) notify.tokenMissing.push("تلگرام");
          if (!cfg.rubikaBotToken) notify.tokenMissing.push("روبیکا");
          const gradeLabel = (body.data && body.data.grade) || "";
          const students = (await listStudents(env)).filter((s) => (Number.isInteger(s.grade) ? s.grade : 0) === g);
          notify.studentsInGrade = students.length;
          for (const s of students) {
            const link = url.origin + "/s/" + encodeURIComponent(s.uuid);
            const msgText = "📅 برنامه‌ی هفتگی جدید برای " + (gradeLabel || "کلاس شما") + " ثبت/به‌روزرسانی شد.\n" + link;
            let hasAnyChannel = false;
            if (s.parentChatId) {
              hasAnyChannel = true;
              if (cfg.telegramBotToken) {
                const r = await sendTelegramMessage(s.parentChatId, msgText);
                if (r.ok) notify.telegram.sent++;
                else {
                  notify.telegram.failed++;
                  if (notify.telegram.errors.length < 5) notify.telegram.errors.push((s.label || "دانش‌آموز") + ": " + (r.error || "خطای نامشخص"));
                }
              }
            }
            if (s.parentPhone) {
              hasAnyChannel = true;
              const r = await sendSms(s.parentPhone, "برنامه‌ی هفتگی جدید برای " + (gradeLabel || "کلاس شما") + " ثبت شد. مشاهده: " + link);
              if (r.ok) notify.sms.sent++;
              else {
                notify.sms.failed++;
                if (notify.sms.errors.length < 5) notify.sms.errors.push((s.label || "دانش‌آموز") + ": " + (r.error || "خطای نامشخص"));
              }
            }
            if (s.parentBaleChatId) {
              hasAnyChannel = true;
              const r = await sendBaleMessage(s.parentBaleChatId, msgText);
              if (r.ok) notify.bale.sent++;
              else {
                notify.bale.failed++;
                if (notify.bale.errors.length < 5) notify.bale.errors.push((s.label || "دانش‌آموز") + ": " + (r.error || "خطای نامشخص"));
              }
            }
            if (s.parentRubikaChatId) {
              hasAnyChannel = true;
              if (cfg.rubikaBotToken) {
                const r = await sendRubikaMessage(s.parentRubikaChatId, msgText);
                if (r.ok) notify.rubika.sent++;
                else {
                  notify.rubika.failed++;
                  if (notify.rubika.errors.length < 5) notify.rubika.errors.push((s.label || "دانش‌آموز") + ": " + (r.error || "خطای نامشخص"));
                }
              }
            }
            if (hasAnyChannel) notify.studentsWithChannel++;
          }
        } catch (e) {
          notify.systemError = String((e && e.message) || e);
        }
      }
      return json(notify ? { ok: true, notify } : { ok: true });
    }

    /* --- بازی و محتوای درسی HTML: آپلود/فهرست/حذف --- */
    if (path === "/api/teacher/html-content" && method === "GET") {
      const raw = await env.EXAM_KV.get("htmlcontent-index");
      return json({ ok: true, items: raw ? JSON.parse(raw) : [] });
    }
    if (path === "/api/teacher/html-content" && method === "POST") {
      const body = await req.json().catch(() => ({}));
      const title = String(body.title || "").slice(0, 120) || "بدون عنوان";
      const contentHtml = String(body.html || "");
      if (!contentHtml.trim()) return json({ ok: false, error: "فایل HTML خالی است" }, 400);
      const byteLen = new TextEncoder().encode(contentHtml).length;
      if (byteLen > 4 * 1024 * 1024) return json({ ok: false, error: "حجم فایل نباید بیشتر از ۴ مگابایت باشد" }, 400);
      let grade = null;
      if (body.grade !== undefined && body.grade !== null && body.grade !== "") {
        const g = parseInt(body.grade, 10);
        if (Number.isInteger(g) && g >= 0 && g <= 11) grade = g;
      }
      const id = uuid();
      await env.EXAM_KV.put("htmlcontent:" + id, contentHtml);
      const idxRaw = await env.EXAM_KV.get("htmlcontent-index");
      const idx = idxRaw ? JSON.parse(idxRaw) : [];
      const rec = { id, title, grade, size: byteLen, uploadedAt: Date.now() };
      idx.unshift(rec);
      await env.EXAM_KV.put("htmlcontent-index", JSON.stringify(idx));
      return json({ ok: true, item: rec });
    }
    if (path.startsWith("/api/teacher/html-content/") && method === "DELETE") {
      const id = decodeURIComponent(path.slice("/api/teacher/html-content/".length));
      await env.EXAM_KV.delete("htmlcontent:" + id);
      const idxRaw = await env.EXAM_KV.get("htmlcontent-index");
      const idx = idxRaw ? JSON.parse(idxRaw) : [];
      await env.EXAM_KV.put("htmlcontent-index", JSON.stringify(idx.filter((it) => it.id !== id)));
      return json({ ok: true });
    }

    /* --- لینک فیلم درس: افزودن/فهرست/حذف --- */
    if (path === "/api/teacher/video-links" && method === "GET") {
      const raw = await env.EXAM_KV.get("videolinks-index");
      return json({ ok: true, items: raw ? JSON.parse(raw) : [] });
    }
    if (path === "/api/teacher/video-links" && method === "POST") {
      const body = await req.json().catch(() => ({}));
      const title = String(body.title || "").slice(0, 120) || "بدون عنوان";
      const videoUrl = String(body.url || "").trim();
      if (!/^https?:\/\//i.test(videoUrl)) return json({ ok: false, error: "لینک باید با http:// یا https:// شروع شود" }, 400);
      let grade = null;
      if (body.grade !== undefined && body.grade !== null && body.grade !== "") {
        const g = parseInt(body.grade, 10);
        if (Number.isInteger(g) && g >= 0 && g <= 11) grade = g;
      }
      const id = uuid();
      const rec = { id, title, grade, url: videoUrl, uploadedAt: Date.now() };
      const idxRaw = await env.EXAM_KV.get("videolinks-index");
      const idx = idxRaw ? JSON.parse(idxRaw) : [];
      idx.unshift(rec);
      await env.EXAM_KV.put("videolinks-index", JSON.stringify(idx));
      return json({ ok: true, item: rec });
    }
    if (path.startsWith("/api/teacher/video-links/") && method === "DELETE") {
      const id = decodeURIComponent(path.slice("/api/teacher/video-links/".length));
      const idxRaw = await env.EXAM_KV.get("videolinks-index");
      const idx = idxRaw ? JSON.parse(idxRaw) : [];
      await env.EXAM_KV.put("videolinks-index", JSON.stringify(idx.filter((it) => it.id !== id)));
      return json({ ok: true });
    }

    /* --- لوح تقدیر: صدور و ارسال یک لوح ساخته‌شده (HTML آماده چاپ) به پنل یک دانش‌آموز مشخص --- */
    if (path === "/api/teacher/certificates/issue" && method === "POST") {
      const body = await req.json().catch(() => ({}));
      const studentUuid = String(body.studentUuid || "").trim();
      const title = String(body.title || "لوح تقدیر").slice(0, 120);
      const certHtml = String(body.html || "");
      const clientId = String(body.id || "").trim().replace(/[^A-Za-z0-9_-]/g, "").slice(0, 64);
      if (!studentUuid) return json({ ok: false, error: "دانش‌آموز نامعتبر است" }, 400);
      // افرادی که از «حضور و غیاب / ثبت لیست دستی» به لوح تقدیر یا گواهی وبینار اضافه می‌شوند
      // پنل دانش‌آموزی ندارند، پس رکورد آن‌ها به‌صورت "attendance:"+id ذخیره شده، نه "student:"+uuid.
      // بدون این تفکیک، صدور لوح برای این افراد همیشه با خطای «دانش‌آموز پیدا نشد» رد می‌شد و QR آن‌ها
      // هرگز به یک لینک واقعی تبدیل نمی‌شد.
      const isAttendee = studentUuid.indexOf("att-") === 0;
      const existsRaw = isAttendee
        ? await env.EXAM_KV.get("attendance:" + studentUuid.slice(4))
        : await env.EXAM_KV.get("student:" + studentUuid);
      if (!existsRaw) return json({ ok: false, error: isAttendee ? "این فرد در فهرست حضور و غیاب پیدا نشد (ممکن است حذف شده باشد)" : "این دانش‌آموز پیدا نشد (ممکن است حذف شده باشد)" }, 404);
      if (!certHtml.trim()) return json({ ok: false, error: "محتوای لوح خالی است" }, 400);
      const byteLen = new TextEncoder().encode(certHtml).length;
      if (byteLen > 500 * 1024) return json({ ok: false, error: "حجم لوح بیش از حد مجاز است" }, 400);
      const id = clientId || uuid();
      const listRaw = await env.EXAM_KV.get("certificates:" + studentUuid);
      const list = listRaw ? JSON.parse(listRaw) : [];
      list.unshift({ id, title, issuedAt: Date.now(), html: certHtml });
      await env.EXAM_KV.put("certificates:" + studentUuid, JSON.stringify(list.slice(0, 30)));
      if (!isAttendee) {
        try {
          const studentRec = JSON.parse(existsRaw);
          if (studentRec.parentChatId) {
            const certLink = url.origin + "/cert/" + encodeURIComponent(studentUuid) + "/" + encodeURIComponent(id);
            await sendTelegramMessage(studentRec.parentChatId, "🏅 لوح تقدیر جدید برای " + (studentRec.label || "دانش‌آموز") + " صادر شد.\n" + certLink);
          }
          if (studentRec.parentPhone) {
            const certLink2 = url.origin + "/cert/" + encodeURIComponent(studentUuid) + "/" + encodeURIComponent(id);
            await sendSms(studentRec.parentPhone, "لوح تقدیر جدید برای " + (studentRec.label || "دانش‌آموز") + " صادر شد. مشاهده: " + certLink2);
          }
          if (studentRec.parentBaleChatId) {
            const certLink3 = url.origin + "/cert/" + encodeURIComponent(studentUuid) + "/" + encodeURIComponent(id);
            await sendBaleMessage(studentRec.parentBaleChatId, "🏅 لوح تقدیر جدید برای " + (studentRec.label || "دانش‌آموز") + " صادر شد.\n" + certLink3);
          }
          if (studentRec.parentRubikaChatId) {
            const certLink4 = url.origin + "/cert/" + encodeURIComponent(studentUuid) + "/" + encodeURIComponent(id);
            await sendRubikaMessage(studentRec.parentRubikaChatId, "🏅 لوح تقدیر جدید برای " + (studentRec.label || "دانش‌آموز") + " صادر شد.\n" + certLink4);
          }
        } catch (e) {}
      }
      return json({ ok: true, id });
    }

  // اطلاع‌رسانی به والدین هنگام ثبت/بروزرسانی کارنامه‌ی ماهیانه (هم از پنل معلم، هم از بات تلگرام صدا زده می‌شود)
  async function notifyReportCard(studentUuid, month) {
    const notify = [];
    try {
      const studentRaw = await env.EXAM_KV.get("student:" + studentUuid);
      if (!studentRaw) {
        notify.push({ channel: "عمومی", ok: false, error: "رکورد دانش‌آموز پیدا نشد (uuid: " + studentUuid + ")" });
        return notify;
      }
      const studentRec = JSON.parse(studentRaw);
      const rcLink = url.origin + "/s/" + encodeURIComponent(studentUuid);
      const msgText = "🎓 کارنامه‌ی ماه " + month + " برای " + (studentRec.label || "دانش‌آموز") + " ثبت شد.\n" + rcLink;
      const cfg = await getNotifySettings();
      if (studentRec.parentChatId) {
        if (!cfg.telegramBotToken) {
          notify.push({ channel: "تلگرام", ok: false, error: "توکن بات تلگرام در تنظیمات ذخیره نشده" });
        } else {
          const r = await sendTelegramMessage(studentRec.parentChatId, msgText);
          notify.push({ channel: "تلگرام", ok: Boolean(r.ok), error: r.error });
        }
      }
      if (studentRec.parentPhone) {
        const r = await sendSms(studentRec.parentPhone, "کارنامه‌ی ماه " + month + " برای " + (studentRec.label || "دانش‌آموز") + " ثبت شد. مشاهده: " + rcLink);
        notify.push({ channel: "پیامک", ok: Boolean(r.ok), error: r.error });
      }
      if (studentRec.parentBaleChatId) {
        const r = await sendBaleMessage(studentRec.parentBaleChatId, msgText);
        notify.push({ channel: "بله", ok: Boolean(r.ok), error: r.error });
      }
      if (studentRec.parentRubikaChatId) {
        if (!cfg.rubikaBotToken) {
          notify.push({ channel: "روبیکا", ok: false, error: "توکن بات روبیکا در تنظیمات ذخیره نشده" });
        } else {
          const r = await sendRubikaMessage(studentRec.parentRubikaChatId, msgText);
          notify.push({ channel: "روبیکا", ok: Boolean(r.ok), error: r.error });
        }
      }
      if (!notify.length) {
        notify.push({ channel: "عمومی", ok: false, error: "برای این دانش‌آموز هیچ شناسه‌ی چت والد (تلگرام/روبیکا/بله/پیامک) ثبت نشده" });
      }
    } catch (e) {
      notify.push({ channel: "سیستم", ok: false, error: String((e && e.message) || e) });
    }
    return notify;
  }

  // اطلاع‌رسانی غیبتِ همان‌روزِ دانش‌آموز: هم به خودِ دانش‌آموز (اگر بات تلگرام/روبیکا را وصل کرده باشد)
  // و هم به والدین (از طریق هر کدام از تلگرام/پیامک/بله/روبیکا که برایشان ثبت شده) پیام می‌فرستد.
  async function notifyAbsenceToday(studentUuid) {
    const notify = [];
    try {
      const studentRaw = await env.EXAM_KV.get("student:" + studentUuid);
      if (!studentRaw) {
        notify.push({ channel: "عمومی", ok: false, error: "رکورد دانش‌آموز پیدا نشد" });
        return notify;
      }
      const studentRec = JSON.parse(studentRaw);
      const todayKey = new Date().toISOString().slice(0, 10);
      studentRec.absences = studentRec.absences || {};
      studentRec.absences[todayKey] = Date.now();
      await env.EXAM_KV.put("student:" + studentUuid, JSON.stringify(studentRec));

      const name = studentRec.label || "دانش‌آموز";
      const cfg = await getNotifySettings();

      // --- پیام مستقیم به خودِ دانش‌آموز ---
      const studentMsg = "📌 " + name + " عزیز، طبق ثبت معلم، امروز در کلاس غایب اعلام شدید.\nاگر این اشتباه است، لطفاً با معلم خود تماس بگیرید.";
      if (studentRec.tgChatId) {
        if (!cfg.telegramBotToken) notify.push({ channel: "تلگرام (دانش‌آموز)", ok: false, error: "توکن بات تلگرام در تنظیمات ذخیره نشده" });
        else {
          const r = await sendTelegramMessage(studentRec.tgChatId, studentMsg);
          notify.push({ channel: "تلگرام (دانش‌آموز)", ok: Boolean(r.ok), error: r.error });
        }
      }
      if (studentRec.rubikaChatId) {
        if (!cfg.rubikaBotToken) notify.push({ channel: "روبیکا (دانش‌آموز)", ok: false, error: "توکن بات روبیکا در تنظیمات ذخیره نشده" });
        else {
          const r = await sendRubikaMessage(studentRec.rubikaChatId, studentMsg);
          notify.push({ channel: "روبیکا (دانش‌آموز)", ok: Boolean(r.ok), error: r.error });
        }
      }

      // --- پیام اطلاع‌رسانی به والدین ---
      const parentMsg = "📌 اطلاع غیبت\n" + name + " امروز در کلاس غایب اعلام شد.";
      if (studentRec.parentChatId) {
        const r = await sendTelegramMessage(studentRec.parentChatId, parentMsg);
        notify.push({ channel: "تلگرام (والدین)", ok: Boolean(r.ok), error: r.error });
      }
      if (studentRec.parentPhone) {
        const r = await sendSms(studentRec.parentPhone, name + " امروز در کلاس غایب اعلام شد.");
        notify.push({ channel: "پیامک (والدین)", ok: Boolean(r.ok), error: r.error });
      }
      if (studentRec.parentBaleChatId) {
        const r = await sendBaleMessage(studentRec.parentBaleChatId, parentMsg);
        notify.push({ channel: "بله (والدین)", ok: Boolean(r.ok), error: r.error });
      }
      if (studentRec.parentRubikaChatId) {
        const r = await sendRubikaMessage(studentRec.parentRubikaChatId, parentMsg);
        notify.push({ channel: "روبیکا (والدین)", ok: Boolean(r.ok), error: r.error });
      }

      if (!notify.length) {
        notify.push({ channel: "عمومی", ok: false, error: "هیچ کانال اطلاع‌رسانی‌ای (نه برای خودِ دانش‌آموز، نه والدین) برای این دانش‌آموز ثبت نشده" });
      }
    } catch (e) {
      notify.push({ channel: "سیستم", ok: false, error: String((e && e.message) || e) });
    }
    return notify;
  }

  /* --- دفتر مدیریت کلاسی: ذخیره/بازیابی عمومی --- */
  if (path === "/api/teacher/lb-save" && method === "POST") {
    const body = await req.json().catch(() => ({}));
    const key = String(body.key || "").slice(0, 200);
    if (!key) return json({ ok: false, error: "کلید نامعتبر است" }, 400);
    await env.EXAM_KV.put("lbdata:" + key, JSON.stringify(body.value ?? null));
    let notify = null;
    if (body.value && key.indexOf("reportcard:student:") === 0) {
      const rest = key.slice("reportcard:student:".length);
      const sep = rest.lastIndexOf(":");
      const studentUuid = sep > -1 ? rest.slice(0, sep) : rest;
      const month = sep > -1 ? rest.slice(sep + 1) : "";
      notify = await notifyReportCard(studentUuid, month);
    }
    return json(notify ? { ok: true, notify } : { ok: true });
  }

    if (path === "/api/teacher/lb-load" && method === "GET") {
      const key = url.searchParams.get("key") || "";
      if (!key) return json({ ok: false, error: "کلید نامعتبر است" }, 400);
      const raw = await env.EXAM_KV.get("lbdata:" + key);
      return json({ ok: true, value: raw ? JSON.parse(raw) : null });
    }

    if (path.startsWith("/api/teacher/worksheet/") && path.endsWith("/feedback") && method === "POST") {
      const id = decodeURIComponent(path.slice("/api/teacher/worksheet/".length, -"/feedback".length));
      const studentRaw = await env.EXAM_KV.get("student:" + id);
      if (!studentRaw) return json({ ok: false, error: "دانش‌آموز پیدا نشد" }, 404);
      const body = await req.json().catch(() => ({}));
      const raw = await env.EXAM_KV.get("worksheet:" + id);
      const rec = raw ? JSON.parse(raw) : { uuid: id };
      rec.feedback = String(body.feedback || "").slice(0, 5000);
      rec.feedbackAt = Date.now();
      await env.EXAM_KV.put("worksheet:" + id, JSON.stringify(rec));
      return json({ ok: true });
    }

    if (path.startsWith("/api/teacher/worksheet/") && method === "GET") {
      const id = decodeURIComponent(path.slice("/api/teacher/worksheet/".length));
      const raw = await env.EXAM_KV.get("worksheet:" + id);
      const rec = raw ? JSON.parse(raw) : {};
      return json({ ok: true, worksheet: rec });
    }

    if (path.startsWith("/api/teacher/worksheet/") && method === "POST") {
      const id = decodeURIComponent(path.slice("/api/teacher/worksheet/".length));
      const studentRaw = await env.EXAM_KV.get("student:" + id);
      if (!studentRaw) return json({ ok: false, error: "دانش‌آموز پیدا نشد" }, 404);
      const body = await req.json().catch(() => ({}));
      const fileDataUrl = String(body.fileDataUrl || "");
      if (!fileDataUrl.startsWith("data:image/") && !fileDataUrl.startsWith("data:application/pdf")) {
        return json({ ok: false, error: "فرمت فایل باید عکس یا PDF باشد" }, 400);
      }
      if (fileDataUrl.length > 4_500_000) return json({ ok: false, error: "حجم فایل بیش از حد مجاز است (حداکثر حدود ۴ مگابایت)" }, 400);
      const raw = await env.EXAM_KV.get("worksheet:" + id);
      const rec = raw ? JSON.parse(raw) : { uuid: id };
      rec.teacherFile = fileDataUrl;
      rec.teacherFileName = String(body.fileName || "").slice(0, 200);
      rec.teacherFileType = fileDataUrl.startsWith("data:application/pdf") ? "pdf" : "image";
      rec.teacherUploadedAt = Date.now();
      await env.EXAM_KV.put("worksheet:" + id, JSON.stringify(rec));
      try {
        const studentRec = JSON.parse(studentRaw);
        if (studentRec.parentChatId) {
          const wsLink = url.origin + "/s/" + encodeURIComponent(id);
          await sendTelegramMessage(studentRec.parentChatId, "📓 کاربرگ جدیدی برای " + (studentRec.label || "دانش‌آموز") + " بارگذاری شد.\n" + wsLink);
        }
        if (studentRec.parentPhone) {
          const wsLink2 = url.origin + "/s/" + encodeURIComponent(id);
          await sendSms(studentRec.parentPhone, "کاربرگ جدیدی برای " + (studentRec.label || "دانش‌آموز") + " بارگذاری شد. مشاهده: " + wsLink2);
        }
        if (studentRec.parentBaleChatId) {
          const wsLink3 = url.origin + "/s/" + encodeURIComponent(id);
          await sendBaleMessage(studentRec.parentBaleChatId, "📓 کاربرگ جدیدی برای " + (studentRec.label || "دانش‌آموز") + " بارگذاری شد.\n" + wsLink3);
        }
        if (studentRec.parentRubikaChatId) {
          const wsLink4 = url.origin + "/s/" + encodeURIComponent(id);
          await sendRubikaMessage(studentRec.parentRubikaChatId, "📓 کاربرگ جدیدی برای " + (studentRec.label || "دانش‌آموز") + " بارگذاری شد.\n" + wsLink4);
        }
      } catch (e) {}
      return json({ ok: true });
    }

    if (path.startsWith("/api/teacher/worksheet/") && method === "DELETE") {
      const id = decodeURIComponent(path.slice("/api/teacher/worksheet/".length));
      const raw = await env.EXAM_KV.get("worksheet:" + id);
      if (raw) {
        const rec = JSON.parse(raw);
        delete rec.teacherFile;
        delete rec.teacherFileName;
        delete rec.teacherFileType;
        delete rec.teacherUploadedAt;
        await env.EXAM_KV.put("worksheet:" + id, JSON.stringify(rec));
      }
      return json({ ok: true });
    }

    if (path === "/api/teacher/students" && method === "GET") {
      const students = await listStudents(env);
      const subs = await Promise.all(students.map((s) => env.EXAM_KV.get("submission:" + s.uuid)));
      const withStatus = students.map((s, idx) => {
        const subRaw = subs[idx];
        let status = "pending";
        if (subRaw) {
          const sub = JSON.parse(subRaw);
          status = sub.grading && sub.grading.graded ? "graded" : "submitted";
        }
        return { ...s, status };
      });
      return json({ ok: true, students: withStatus });
    }

    if (path === "/api/teacher/students" && method === "POST") {
      const body = await req.json().catch(() => ({}));
      const id = uuid();
      let photo = "";
      if (typeof body.photo === "string" && body.photo.startsWith("data:image/")) {
        if (body.photo.length > 2_800_000) return json({ ok: false, error: "حجم عکس پروفایل بیش از حد مجاز است (حداکثر ۲ مگابایت)" }, 400);
        photo = body.photo;
      }
      let grade = parseInt(body.grade, 10);
      if (!Number.isInteger(grade) || grade < 0 || grade > 11) grade = 0;
      const rec = { uuid: id, label: String(body.label || "").slice(0, 120), photo, grade, createdAt: Date.now() };
      await env.EXAM_KV.put("student:" + id, JSON.stringify(rec));
      return json({ ok: true, student: rec });
    }

    if (path.startsWith("/api/teacher/students/") && method === "PATCH") {
      const id = decodeURIComponent(path.slice("/api/teacher/students/".length));
      const raw = await env.EXAM_KV.get("student:" + id);
      if (!raw) return json({ ok: false, error: "دانش‌آموز پیدا نشد" }, 404);
      const rec = JSON.parse(raw);
      const body = await req.json().catch(() => ({}));
      if (typeof body.photo === "string") {
        if (body.photo && body.photo.startsWith("data:image/")) {
          if (body.photo.length > 2_800_000) return json({ ok: false, error: "حجم عکس پروفایل بیش از حد مجاز است (حداکثر ۲ مگابایت)" }, 400);
          rec.photo = body.photo;
        } else if (body.photo === "") {
          rec.photo = "";
        }
      }
      if (typeof body.label === "string") rec.label = body.label.slice(0, 120);
      if (typeof body.parentChatId === "string") rec.parentChatId = body.parentChatId.trim().slice(0, 40);
      if (typeof body.parentPhone === "string") rec.parentPhone = body.parentPhone.trim().slice(0, 20);
      if (typeof body.parentBaleChatId === "string") rec.parentBaleChatId = body.parentBaleChatId.trim().slice(0, 40);
      if (typeof body.parentRubikaChatId === "string") rec.parentRubikaChatId = body.parentRubikaChatId.trim().slice(0, 60);
      if (body.grade !== undefined) {
        const g = parseInt(body.grade, 10);
        if (Number.isInteger(g) && g >= 0 && g <= 11) rec.grade = g;
      }
      await env.EXAM_KV.put("student:" + id, JSON.stringify(rec));
      return json({ ok: true, student: rec });
    }

    // --- ثبت غیبتِ امروزِ یک دانش‌آموز و اطلاع‌رسانی همان‌روز به خودِ او و والدینش ---
    if (path.startsWith("/api/teacher/students/") && path.endsWith("/absent-today") && method === "POST") {
      if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
      const id = decodeURIComponent(path.slice("/api/teacher/students/".length, -"/absent-today".length));
      const raw = await env.EXAM_KV.get("student:" + id);
      if (!raw) return json({ ok: false, error: "دانش‌آموز پیدا نشد" }, 404);
      const notify = await notifyAbsenceToday(id);
      return json({ ok: true, notify });
    }

    // --- لینک عمومی اتصال خودِ دانش‌آموز به بات مکالمه‌ای تلگرام/روبیکا (بدون نیاز به ورود معلم؛
    // احراز هویت همان uuid اختصاصی صفحه‌ی دانش‌آموز است) ---
    if (path.startsWith("/api/student/bot-link/") && method === "GET") {
      const id = decodeURIComponent(path.slice("/api/student/bot-link/".length));
      const studentRaw = await env.EXAM_KV.get("student:" + id);
      if (!studentRaw) return json({ ok: false, error: "دانش‌آموز پیدا نشد" }, 404);
      const cfg = await getNotifySettings();
      if (!cfg.telegramBotUsername) return json({ ok: false, error: "بات تلگرام هنوز توسط معلم فعال نشده است" }, 400);
      const st = JSON.parse(studentRaw);
      return json({ ok: true, link: "https://t.me/" + cfg.telegramBotUsername + "?start=" + encodeURIComponent(id), connected: Boolean(st.tgChatId) });
    }
    if (path.startsWith("/api/student/rubika-bot-link/") && method === "GET") {
      const id = decodeURIComponent(path.slice("/api/student/rubika-bot-link/".length));
      const studentRaw = await env.EXAM_KV.get("student:" + id);
      if (!studentRaw) return json({ ok: false, error: "دانش‌آموز پیدا نشد" }, 404);
      const cfg = await getNotifySettings();
      if (!cfg.rubikaBotUsername) return json({ ok: false, error: "بات روبیکا هنوز توسط معلم فعال نشده است" }, 400);
      const st = JSON.parse(studentRaw);
      return json({ ok: true, link: "https://rubika.ir/" + cfg.rubikaBotUsername + "?start=" + encodeURIComponent(id), connected: Boolean(st.rubikaChatId) });
    }

    if (path.startsWith("/api/teacher/students/") && method === "DELETE") {
      const id = decodeURIComponent(path.slice("/api/teacher/students/".length));
      await env.EXAM_KV.delete("student:" + id);
      await env.EXAM_KV.delete("submission:" + id);
      return json({ ok: true });
    }

    if (path === "/api/teacher/attendance" && method === "GET") {
      if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
      const linkFilter = url.searchParams.get("linkId");
      const out = [];
      let cursor;
      do {
        const res = await env.EXAM_KV.list({ prefix: "attendance:", cursor });
        const values = await Promise.all(res.keys.map((k) => env.EXAM_KV.get(k.name)));
        for (const v of values) {
          if (!v) continue;
          const rec = JSON.parse(v);
          if (linkFilter && (rec.linkId || "default") !== linkFilter) continue;
          out.push(rec);
        }
        cursor = res.list_complete ? null : res.cursor;
      } while (cursor);
      out.sort((a, b) => (b.ts || 0) - (a.ts || 0));
      return json({ ok: true, records: out.slice(0, 500) });
    }
    if (path === "/api/teacher/attendance" && method === "DELETE") {
      if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
      let cursor;
      do {
        const res = await env.EXAM_KV.list({ prefix: "attendance:", cursor });
        await Promise.all(res.keys.map((k) => env.EXAM_KV.delete(k.name)));
        cursor = res.list_complete ? null : res.cursor;
      } while (cursor);
      await env.EXAM_KV.put("attendance-counts", JSON.stringify({}));
      return json({ ok: true });
    }
    if (path.startsWith("/api/teacher/attendance/") && method === "DELETE") {
      const id = decodeURIComponent(path.slice("/api/teacher/attendance/".length));
      const recRaw = await env.EXAM_KV.get("attendance:" + id);
      let recLinkId = "default";
      if (recRaw) { try { recLinkId = JSON.parse(recRaw).linkId || "default"; } catch (e) {} }
      await env.EXAM_KV.delete("attendance:" + id);
      await bumpAttendanceCount(env, recLinkId, -1);
      return json({ ok: true });
    }

    /* --- لیست‌های (لینک‌های) حضور و غیاب: هر لیست یک لینک عمومی جدا برای ثبت‌نام دارد --- */
    if (path === "/api/teacher/attendance-links" && method === "GET") {
      if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
      const links = [];
      let cursor;
      do {
        const res = await env.EXAM_KV.list({ prefix: "attlink:", cursor });
        const values = await Promise.all(res.keys.map((k) => env.EXAM_KV.get(k.name)));
        for (const v of values) { if (v) links.push(JSON.parse(v)); }
        cursor = res.list_complete ? null : res.cursor;
      } while (cursor);
      // شمارش ثبت‌نام‌های هر لیست: به‌جای اسکن کامل تمام رکوردهای «attendance:» در هر بار (که با زیاد شدن
      // تعداد ثبت‌نام‌ها کند می‌شد)، از کلید «attendance-counts» (شمارنده‌ی از‌پیش‌محاسبه‌شده) استفاده می‌شود.
      // این اسکن کامل فقط یک‌بار (اولین اجرای این کد روی داده‌های قدیمی که هنوز شمارنده ندارند) انجام می‌شود.
      let counts = {};
      const countsRaw = await env.EXAM_KV.get("attendance-counts");
      if (countsRaw !== null) {
        try { counts = JSON.parse(countsRaw); } catch (e) { counts = {}; }
      } else {
        let hasLegacy = false;
        let legacyEarliest = 0;
        let cursor2;
        do {
          const res = await env.EXAM_KV.list({ prefix: "attendance:", cursor: cursor2 });
          const values = await Promise.all(res.keys.map((k) => env.EXAM_KV.get(k.name)));
          for (const v of values) {
            if (!v) continue;
            const rec = JSON.parse(v);
            const lid = rec.linkId || "default";
            counts[lid] = (counts[lid] || 0) + 1;
            if (lid === "default") { hasLegacy = true; if (!legacyEarliest || (rec.ts || 0) < legacyEarliest) legacyEarliest = rec.ts || 0; }
          }
          cursor2 = res.list_complete ? null : res.cursor;
        } while (cursor2);
        if (hasLegacy && !links.some((l) => l.id === "default")) {
          const defRec = { id: "default", shortId: "DEFAULT", title: "لینک اصلی (قبلی)", createdAt: legacyEarliest || Date.now() };
          await env.EXAM_KV.put("attlink:default", JSON.stringify(defRec));
          links.push(defRec);
        }
        await env.EXAM_KV.put("attendance-counts", JSON.stringify(counts));
      }
      links.forEach((l) => { l.count = counts[l.id] || 0; });
      links.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
      return json({ ok: true, links });
    }
    /* --- حضور و غیاب: افزودن دستی اطلاعات پرسنل توسط معلم (با فیلد «سمت») ---
       رکورد دقیقاً در همان ساختار رکوردهای عادی حضور و غیاب ذخیره می‌شود تا به‌صورت
       خودکار در بخش «لوح تقدیر» و «گواهی حضور در وبینار» هم قابل انتخاب باشد. */
    if (path === "/api/teacher/attendance-manual" && method === "POST") {
      if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
      const body = await req.json().catch(() => ({}));
      const name = String(body.name || "").trim().slice(0, 80);
      const family = String(body.family || "").trim().slice(0, 80);
      const nationalCode = String(body.nationalCode || "").trim().slice(0, 20);
      const school = String(body.school || "").trim().slice(0, 150);
      const region = String(body.region || "").trim().slice(0, 100);
      const role = String(body.role || "").trim().slice(0, 100);
      let linkId = String(body.linkId || "default").trim().slice(0, 80) || "default";
      if (!name || !family) return json({ ok: false, error: "نام و نام خانوادگی الزامی است" }, 400);
      if (linkId !== "default") {
        const linkRaw = await env.EXAM_KV.get("attlink:" + linkId);
        if (!linkRaw) return json({ ok: false, error: "این لیست معتبر نیست یا حذف شده است" }, 400);
      }
      const id = uuid();
      const rec = { id, linkId, name, family, nationalCode, school, region, role, manual: true, ts: Date.now() };
      await env.EXAM_KV.put("attendance:" + id, JSON.stringify(rec));
      await bumpAttendanceCount(env, linkId, 1);
      return json({ ok: true, record: rec });
    }
    /* --- حضور و غیاب: ثبت دسته‌ای (batch) برای ورود دستی سریع‌تر --- */
    if (path === "/api/teacher/attendance-manual-batch" && method === "POST") {
      if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
      const body = await req.json().catch(() => ({}));
      const rows = Array.isArray(body.rows) ? body.rows.slice(0, 500) : [];
      const results = [];
      const countsByLink = {};
      for (const row of rows) {
        const name = String(row.name || "").trim().slice(0, 80);
        const family = String(row.family || "").trim().slice(0, 80);
        if (!name || !family) { results.push({ ok: false, error: "نام الزامی است" }); continue; }
        const nationalCode = String(row.nationalCode || "").trim().slice(0, 20);
        const school = String(row.school || "").trim().slice(0, 150);
        const region = String(row.region || "").trim().slice(0, 100);
        const role = String(row.role || "").trim().slice(0, 100);
        let linkId = String(row.linkId || "default").trim().slice(0, 80) || "default";
        if (linkId !== "default") {
          const linkRaw = await env.EXAM_KV.get("attlink:" + linkId);
          if (!linkRaw) { results.push({ ok: false, error: "لیست معتبر نیست" }); continue; }
        }
        const id = uuid();
        const rec = { id, linkId, name, family, nationalCode, school, region, role, manual: true, ts: Date.now() };
        await env.EXAM_KV.put("attendance:" + id, JSON.stringify(rec));
        countsByLink[linkId] = (countsByLink[linkId] || 0) + 1;
        results.push({ ok: true, record: rec });
      }
      // یکجا شمارنده‌ها را به‌روز کن
      for (const [lid, cnt] of Object.entries(countsByLink)) {
        await bumpAttendanceCount(env, lid, cnt);
      }
      const added = results.filter(r => r.ok).length;
      return json({ ok: true, added, failed: results.length - added, results });
    }
    if (path === "/api/teacher/attendance-links" && method === "POST") {
      if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
      const body = await req.json().catch(() => ({}));
      const title = String(body.title || "").trim().slice(0, 120) || "لیست بدون عنوان";
      const id = uuid();
      const shortId = id.slice(0, 8).toUpperCase();
      const rec = { id, shortId, title, createdAt: Date.now() };
      await env.EXAM_KV.put("attlink:" + id, JSON.stringify(rec));
      return json({ ok: true, link: rec });
    }
    if (path.startsWith("/api/teacher/attendance-links/") && method === "DELETE") {
      if (!(await isTeacher(req, env))) return json({ ok: false, error: "دسترسی غیرمجاز" }, 401);
      const id = decodeURIComponent(path.slice("/api/teacher/attendance-links/".length));
      await env.EXAM_KV.delete("attlink:" + id);
      let deletedCount = 0;
      let cursor;
      do {
        const res = await env.EXAM_KV.list({ prefix: "attendance:", cursor });
        const values = await Promise.all(res.keys.map((k) => env.EXAM_KV.get(k.name)));
        const toDelete = [];
        res.keys.forEach((k, i) => {
          const v = values[i];
          if (!v) return;
          const rec = JSON.parse(v);
          if ((rec.linkId || "default") === id) toDelete.push(k.name);
        });
        await Promise.all(toDelete.map((name) => env.EXAM_KV.delete(name)));
        deletedCount += toDelete.length;
        cursor = res.list_complete ? null : res.cursor;
      } while (cursor);
      const countsRaw2 = await env.EXAM_KV.get("attendance-counts");
      if (countsRaw2 !== null) {
        let counts2;
        try { counts2 = JSON.parse(countsRaw2); } catch (e) { counts2 = {}; }
        delete counts2[id];
        await env.EXAM_KV.put("attendance-counts", JSON.stringify(counts2));
      }
      return json({ ok: true, deletedCount });
    }

    if (path === "/api/teacher/questions" && method === "GET") {
      const grade = clampGrade(url.searchParams.get("grade"));
      return json({ ok: true, meta: await getMeta(env, grade), questions: await getQuestions(env, grade) });
    }

    if (path === "/api/teacher/questions" && method === "PUT") {
      const body = await req.json().catch(() => ({}));
      const grade = clampGrade(body.grade);
      const questions = (Array.isArray(body.questions) ? body.questions : []).map((q, i) => {
        const type = QUESTION_TYPES[q.type] ? q.type : "descriptive";
        const rich = type === "descriptive" && Boolean(q.rich);
        return {
          id: q.id || uuid(),
          type,
          rich,
          text: rich ? sanitizeHtml(String(q.text || "")) : String(q.text || ""),
          options: Array.isArray(q.options) ? q.options.map((o) => String(o)) : [],
          correct: q.correct == null ? "" : q.correct,
          image: typeof q.image === "string" ? q.image : "",
          imageWidth: Number.isFinite(parseInt(q.imageWidth, 10)) ? Math.min(900, Math.max(80, parseInt(q.imageWidth, 10))) : 320,
          imageAsQuestion: Boolean(q.imageAsQuestion),
          imageAlign: q.imageAlign === "center" || q.imageAlign === "left" ? q.imageAlign : "right",
          imagePos: q.imagePos === "above" ? "above" : "below",
          weight: Math.min(20, Math.max(0.5, parseFloat(q.weight) || 1)),
          order: i,
        };
      });
      await env.EXAM_KV.put("questions:" + grade, JSON.stringify(questions));
      if (body.meta) {
        const meta = { ...DEFAULT_META, ...body.meta, gradeLevel: gradeLevelOf(grade) };
        await env.EXAM_KV.put("meta:" + grade, JSON.stringify(meta));
      }
      return json({ ok: true });
    }

    if (path === "/api/teacher/submissions" && method === "GET") {
      const students = await listStudents(env);
      const out = [];
      for (const s of students) {
        const raw = await env.EXAM_KV.get("submission:" + s.uuid);
        if (raw) {
          const sub = JSON.parse(raw);
          sub.label = s.label || "";
          sub.studentPhoto = s.photo || "";
          out.push(sub);
        }
      }
      out.sort((a, b) => (b.submittedAt || 0) - (a.submittedAt || 0));
      return json({ ok: true, submissions: out });
    }

    if (path === "/api/teacher/grade" && method === "POST") {
      const body = await req.json().catch(() => ({}));
      const id = body.uuid;
      const raw = await env.EXAM_KV.get("submission:" + id);
      if (!raw) return json({ ok: false, error: "پاسخنامه یافت نشد" }, 404);
      const sub = JSON.parse(raw);
      sub.grading = {
        graded: true,
        overall: String(body.overall || ""),
        feedback: body.feedback && typeof body.feedback === "object" ? body.feedback : {},
        marks: body.marks && typeof body.marks === "object" ? body.marks : {},
        gradedAt: Date.now(),
      };
      await env.EXAM_KV.put("submission:" + id, JSON.stringify(sub));
      return json({ ok: true });
    }

    if (path === "/api/teacher/word" && method === "GET") {
      const type = url.searchParams.get("type") || "questions";
      const wordGrade = clampGrade(url.searchParams.get("grade"));
      const meta = await getMeta(env, wordGrade);
      if (type === "answers") {
        const id = url.searchParams.get("uuid");
        const raw = await env.EXAM_KV.get("submission:" + id);
        if (!raw) return json({ ok: false, error: "پاسخنامه یافت نشد" }, 404);
        const sub = JSON.parse(raw);
        return wordResponse(answerSheetWord(sub), `پاسخنامه-${sub.student.name || id}.doc`);
      }
      const questions = await getQuestions(env, wordGrade);
      if (type === "examsheet") {
        const raw = await env.EXAM_KV.get("lbdata:examsheet");
        const data = raw ? JSON.parse(raw) : {};
        return wordResponse(examSheetWord(data), "برگه-آزمون-چاپی.doc", "0.6cm");
      }
      return wordResponse(examWord(meta, questions), "برگه-آزمون.doc");
    }

    if (path === "/api/teacher/ai/chat" && method === "POST") {
      const body = await req.json().catch(() => ({}));
      const messages = body.messages || [];
      const maxTokens = Math.min(Math.max(parseInt(body.max_tokens, 10) || 1024, 256), 8192);
      const provider = body.provider === "groq" ? "groq" : body.provider === "cloudflare" ? "cloudflare" : body.provider === "tokenharbor" ? "tokenharbor" : "gemini";

      // ----- موتور Token Harbor — دروازه‌ی سازگار با OpenAI برای چند مدل (شامل DeepSeek V4 Flash رایگان) -----
      if (provider === "tokenharbor") {
        const thKey = env.TOKENHARBOR_API_KEY;
        if (!thKey) return json({ error: "کلید TOKENHARBOR_API_KEY تنظیم نشده" }, 500);
        const thModel = body.model || env.TOKENHARBOR_MODEL || "deepseek-v4-flash:free";
        const trimmedThMessages = messages.slice(-10);
        const result = await callOpenAiCompatible(
          "https://tokenharbor.ai/v1/chat/completions",
          thKey, thModel, trimmedThMessages, maxTokens
        );
        if (!result.ok) return json({ error: "Token Harbor: " + result.error }, result.status);
        return json({ ok: true, content: result.content });
      }

      // ----- موتور Groq — سازگار با فرمت OpenAI، سخت‌افزار LPU با سرعت بسیار بالا -----
      if (provider === "groq") {
        const groqKey = env.GROQ_API_KEY;
        if (!groqKey) return json({ error: "کلید GROQ_API_KEY تنظیم نشده" }, 500);
        let groqModel = body.model || env.GROQ_MODEL || "openai/gpt-oss-20b";
        // فقط مدل‌های Qwen ورودی تصویر (content آرایه‌ای) را قبول می‌کنند؛ بقیه با خطای
        // "content must be a string" رد می‌شوند، پس اگر عکسی در پیام‌ها بود خودکار سوییچ کن
        const GROQ_VISION_MODELS = ["qwen/qwen3.6-27b", "qwen/qwen3.8-27b"];
        const trimmedGroqMessages = messages.slice(-10);
        const hasImage = trimmedGroqMessages.some((m) => Array.isArray(m.content) && m.content.some((c) => c && c.type === "image_url"));
        if (hasImage && !GROQ_VISION_MODELS.includes(groqModel)) groqModel = "qwen/qwen3.6-27b";
        const result = await callOpenAiCompatible(
          "https://api.groq.com/openai/v1/chat/completions",
          groqKey, groqModel, trimmedGroqMessages, maxTokens
        );
        if (!result.ok) return json({ error: "Groq: " + result.error }, result.status);
        return json({ ok: true, content: result.content });
      }

      // ----- موتور Cloudflare Workers AI — بدون نیاز به API key، از طریق AI binding خودِ همین Worker -----
      if (provider === "cloudflare") {
        if (!env.AI) return json({ error: 'AI binding تنظیم نشده — باید [ai] binding = "AI" را به wrangler.toml اضافه و دوباره deploy کنید' }, 500);
        let cfModel = body.model || env.CLOUDFLARE_AI_MODEL || "@cf/meta/llama-3.1-8b-instruct-fast";
        const trimmedMessages = messages.slice(-10);
        // برخلاف Gemini/Groq که فرمت OpenAI-style با content آرایه‌ای (image_url) را می‌پذیرند،
        // AI binding بومی Cloudflare انتظار دارد content هر پیام یک رشته‌ی ساده باشد و عکس در فیلد جداگانه‌ی
        // top-level به نام image (به‌صورت data URL کامل) ارسال شود — وگرنه خطای schema validation می‌دهد.
        let cfImage = null;
        const cfMessages = trimmedMessages.map((m) => {
          if (typeof m.content === "string") return { role: m.role, content: m.content };
          if (Array.isArray(m.content)) {
            let text = "";
            for (const c of m.content) {
              if (c && c.type === "text") text += (text ? "\n" : "") + (c.text || "");
              else if (c && c.type === "image_url" && c.image_url?.url) cfImage = c.image_url.url;
            }
            return { role: m.role, content: text };
          }
          return { role: m.role, content: "" };
        });
        // اگر عکسی در پیام‌ها بود ولی مدل انتخاب‌شده از تصویر پشتیبانی نمی‌کند، خودکار به مدل Vision سوییچ کن
        const CF_VISION_MODELS = ["@cf/google/gemma-4-26b-a4b-it", "@cf/mistralai/mistral-small-3.1-24b-instruct"];
        if (cfImage && !CF_VISION_MODELS.includes(cfModel)) cfModel = "@cf/google/gemma-4-26b-a4b-it";
        const cfInput = { messages: cfMessages, max_tokens: maxTokens };
        if (cfImage) cfInput.image = cfImage;
        const MAX_ATTEMPTS = 3;
        let lastErr = null;
        for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
          try {
            const result = await env.AI.run(cfModel, cfInput);
            // بعضی مدل‌های جدیدتر (مثل gpt-oss) فرمت Chat Completions برمی‌گردانند
            // (choices[0].message.content) نه فرمت بومی run() که response نام دارد؛ هر دو را پوشش بده
            // وگرنه پیام "خالی" برمی‌گردد در حالی که مدل واقعاً جواب داده است.
            const content = (result && (result.response || result.result?.response || result.choices?.[0]?.message?.content)) || "";
            if (!content) console.log("Cloudflare AI empty content, raw result:", JSON.stringify(result).slice(0, 500));
            return json({ ok: true, content });
          } catch (e) {
            lastErr = e.message || String(e);
            const retryable = /429|3040|capacity/i.test(lastErr);
            if (retryable && attempt < MAX_ATTEMPTS) { await new Promise((r) => setTimeout(r, attempt * 1200)); continue; }
            return json({ error: "Cloudflare AI: " + lastErr }, 500);
          }
        }
        return json({ error: "Cloudflare AI: " + (lastErr || "خطای نامشخص") }, 500);
      }

      // ----- موتور Gemini (پیش‌فرض) -----
      const geminiKey = env.GEMINI_API_KEY;
      if (!geminiKey) return json({ error: "کلید GEMINI_API_KEY تنظیم نشده" }, 500);
      // مدل فعلی: gemini-3.6-flash (نسخه‌ی پایدار/GA در سال ۲۰۲۶؛ در صورت بازنشستگی باید به‌روزرسانی شود)
      const geminiModel = "gemini-3.6-flash";
      // تبدیل قالب پیام‌های OpenAI-style به قالب contents مورد نیاز Gemini
      let systemInstruction = "";
      const contents = [];
      for (const m of messages.slice(-10)) {
        if (m.role === "system") { systemInstruction += (systemInstruction ? "\n" : "") + (typeof m.content === "string" ? m.content : ""); continue; }
        const role = m.role === "assistant" ? "model" : "user";
        const parts = [];
        if (typeof m.content === "string") {
          parts.push({ text: m.content });
        } else if (Array.isArray(m.content)) {
          for (const c of m.content) {
            if (c.type === "text") parts.push({ text: c.text });
            else if (c.type === "image_url" && c.image_url?.url) {
              const durl = c.image_url.url;
              const match = /^data:(.+?);base64,(.+)$/.exec(durl);
              if (match) parts.push({ inline_data: { mime_type: match[1], data: match[2] } });
            }
          }
        }
        if (parts.length) contents.push({ role, parts });
      }
      // تلاش مجدد خودکار برای خطاهای موقت گوگل (503 = مدل شلوغ، 429 = محدودیت نرخ)
      const RETRYABLE_STATUSES = [503, 429];
      const MAX_ATTEMPTS = 3;
      let lastErr = null, lastStatus = 500;
      for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
        try {
          const aiRes = await fetch(
            `https://generativelanguage.googleapis.com/v1beta/models/${geminiModel}:generateContent?key=${geminiKey}`,
            {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                contents,
                systemInstruction: systemInstruction ? { parts: [{ text: systemInstruction }] } : undefined,
                generationConfig: { maxOutputTokens: maxTokens }
              })
            }
          );
          if (!aiRes.ok) {
            const errText = await aiRes.text();
            lastErr = "Gemini: " + errText;
            lastStatus = aiRes.status;
            if (RETRYABLE_STATUSES.includes(aiRes.status) && attempt < MAX_ATTEMPTS) {
              await new Promise(r => setTimeout(r, attempt * 1200));
              continue;
            }
            return json({ error: lastErr }, lastStatus);
          }
          const aiData = await aiRes.json();
          const text = aiData.candidates?.[0]?.content?.parts?.map(p => p.text || "").join("") || "";
          return json({ ok: true, content: text });
        } catch (e) {
          lastErr = "Error: " + e.message;
          lastStatus = 500;
          if (attempt < MAX_ATTEMPTS) { await new Promise(r => setTimeout(r, attempt * 1200)); continue; }
          return json({ error: lastErr }, lastStatus);
        }
      }
      return json({ error: lastErr || "خطای نامشخص در ارتباط با هوش مصنوعی" }, lastStatus);
    }
  }

  return json({ ok: false, error: "مسیر یافت نشد" }, 404);
}

/* ------------------------- خروجی Word ------------------------- */

function wordResponse(bodyHtml, filename, margin) {
  const doc =
    `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">` +
    `<head><meta charset="utf-8">` +
    `<style>
      @page { size: A4; margin: ${margin || "1.5cm"}; }
      body { font-family: 'B Nazanin','Tahoma',sans-serif; direction: rtl; font-size: 13pt; }
      .hdr { text-align:center; border-bottom: 2px solid #000; padding-bottom:8px; margin-bottom:14px; }
      .hdr h1 { font-size: 15pt; margin: 2px 0; }
      .hdr h2 { font-size: 12pt; margin: 2px 0; font-weight: normal; }
      .hdr h3 { font-size: 12pt; margin: 2px 0; font-weight: normal; }
      .meta-table { width:100%; mso-table-layout-alt:fixed; border-collapse: collapse; margin-bottom: 14px; }
      .meta-table td { border: 1px solid #000; padding: 6px 8px; }
      table.q { width:100%; mso-table-layout-alt:fixed; border-collapse: collapse; margin-bottom: 10px; }
      table.q td, table.q th { border: 1px solid #000; padding: 6px 8px; vertical-align: top; }
      .qnum { width: 36px; text-align:center; font-weight:bold; }
      .opt { padding: 2px 18px; }
      .ans { min-height: 40px; }
      img { max-width: 900px; }
      .frac{display:inline-block;text-align:center;vertical-align:middle;margin:0 3px}
      .frac .fn{display:block;border-bottom:1.5px solid #000;padding:0 4px}
      .frac .fd{display:block;padding:0 4px}
      .shape{display:inline-block;vertical-align:middle;line-height:1;margin:0 2px}
      .shape svg{display:block}
      .ldiv{border-collapse:collapse;display:inline-table;margin:6px 4px;vertical-align:middle}
      .ldiv td{padding:3px 10px;text-align:center;vertical-align:top}
      .ldiv td.ld-bar{border-right:2px solid #000}
      .ldiv td.ld-top{border-bottom:2px solid #000;min-width:60px;min-height:20px}
      .ldiv .ld-divisor{vertical-align:bottom;padding-bottom:6px;font-weight:bold}
      .ldiv .ld-dividend{padding:2px 6px;text-align:center}
      .ldiv .ld-work{min-height:26px}
      .mt-frac{display:inline-block;text-align:center;vertical-align:middle;margin:0 4px}
      .mt-frac .mt-num{display:block;border-bottom:2px solid #000;padding:0 4px}
      .mt-frac .mt-den{display:block;padding:0 4px}
      .mt-root{display:inline-block;vertical-align:middle;margin:0 4px}
      .mt-root .mt-idx{font-size:.6em;vertical-align:top}
      .mt-root .mt-rad{text-decoration:overline;padding:0 3px}
      .mt-op{display:inline-block;vertical-align:middle;margin:0 4px}
      .mt-op-stack{display:inline-block;text-align:center;vertical-align:middle}
      .mt-op-over,.mt-op-under{display:block;font-size:.55em}
      .mt-op-sign{display:block;font-size:1.6em;line-height:1}
      .mt-op-arg{display:inline-block;vertical-align:middle}
      .mt-lim{display:inline-block;vertical-align:middle;margin:0 4px}
      .mt-lim-stack{display:inline-block;text-align:center;vertical-align:middle}
      .mt-lim-word{display:block;font-size:.7em}
      .mt-lim-under{display:block;font-size:.55em}
      .mt-matrix{border-collapse:collapse;display:inline-table;vertical-align:middle;margin:0 5px;border-left:2px solid #000;border-right:2px solid #000}
      .mt-matrix td{padding:4px 10px;text-align:center}
      .mt-ph{display:inline-block;min-width:16px}
    </style></head><body dir="rtl">` +
    bodyHtml +
    `</body></html>`;
  return new Response(doc, {
    headers: {
      "content-type": "application/msword; charset=utf-8",
      "content-disposition": `attachment; filename*=UTF-8''${encodeURIComponent(filename)}`,
    },
  });
}

function wordHeader(meta, extra = "") {
  let html = `<div class="hdr">`;
  if (meta.school) html += `<h1>${esc(meta.school)}</h1>`;
  if (meta.examName) html += `<h2>${esc(meta.examName)}</h2>`;
  if (meta.teacher) html += `<h3>آموزگار: ${esc(meta.teacher)}</h3>`;
  if (meta.examDuration) html += `<h3>مدت زمان: ${esc(meta.examDuration)} دقیقه</h3>`;
  html += `</div>`;
  return html + extra;
}

// عکس سوال با چینش (راست/وسط/چپ) و جای دلخواه (بالا یا زیر متن سوال) که معلم تعیین کرده
function questionImageWord(q) {
  if (!q.image) return "";
  const align = q.imageAlign === "center" || q.imageAlign === "left" ? q.imageAlign : "right";
  return `<div style="text-align:${align};margin:6px 0"><img src="${esc(q.image)}" style="width:${q.imageWidth || 320}px;max-width:100%"></div>`;
}

function questionBodyWord(q) {
  let inner = `<div><b>${q.rich ? q.text : esc(q.text)}</b> <span style="font-size:11px;color:#666">(وزن: ${q.weight || 1})</span></div>`;
  const qImg = questionImageWord(q);
  if (qImg) inner = q.imagePos === "above" ? qImg + inner : inner + qImg;
  if (q.type === "multiple") {
    (q.options || []).forEach((o, oi) => {
      inner += `<div class="opt">${["الف", "ب", "ج", "د"][oi] || oi + 1}) ${esc(o)}</div>`;
    });
  } else if (q.type === "truefalse") {
    inner += `<div class="opt">صحیح ☐&nbsp;&nbsp;&nbsp; غلط ☐</div>`;
  } else if (q.type === "short") {
    inner += `<div class="ans">پاسخ: ...........................................................</div>`;
  } else {
    inner += `<div class="ans">پاسخ:<br><br><br></div>`;
  }
  return inner;
}

function examWord(meta, questions) {
  let body = wordHeader(meta);
  body +=
    `<table class="meta-table">` +
    `<tr><td>نام و نام خانوادگی: ...................</td><td>نام پدر: ...................</td><td>کد ملی: ...................</td></tr>` +
    `<tr><td>نام درس: ...................</td><td>کلاس: ...................</td><td></td></tr>` +
    `</table>`;

  questions.forEach((q, i) => {
    body +=
      `<table class="q"><tr>` +
      `<td class="qnum">${i + 1}</td>` +
      `<td>${questionBodyWord(q)}</td>` +
      `</tr></table>`;
  });
  return body;
}

// پاک‌سازی HTML ذخیره‌شده‌ی یک سؤال برای Word: نوار ابزار ویرایشگر (دکمه‌ها) نباید وارد فایل شود،
// و عکسِ «وسط» با یک div وسط‌چین پیچیده می‌شود چون Word به margin:auto توجه نمی‌کند
function examSheetCleanQ(html) {
  let h = String(html || "");
  h = h.replace(/<div class="es-item-toolbar"[^>]*>[\s\S]*?<\/div>/g, "");
  h = h.replace(/<div class="es-tbl-toolbar"[^>]*>[\s\S]*?<\/div>/g, "");
  h = h.replace(/<img\b[^>]*data-al="center"[^>]*>/g, (m) => '<div style="text-align:center">' + m + "</div>");
  return h;
}

function examSheetWord(d) {
  d = d || {};
  const rows = Array.isArray(d.rows) && d.rows.length ? d.rows : [{ q: "", mark: "" }];
  const teacherLabel = d.teacherLabel || "نام دبیر";
  const markLabel = d.markLabel || "بارم";
  const fontSize = parseInt(d.fontSize, 10) || 12;
  const tblStyle = "width:100%;table-layout:fixed;mso-table-layout-alt:fixed";
  const fontWrap = (inner) => `<div style="font-family:'B Nazanin',Tahoma,Arial;font-weight:bold;font-size:${fontSize}pt">${inner}</div>`;
  const examTitleFull = esc(d.examtitle || "آزمون نوبت اول") + (d.examtitleExtra ? " - " + esc(d.examtitleExtra) : "");
  let body =
    `<table class="meta-table" width="100%" style="${tblStyle}"><tr>` +
    `<td style="width:33%">نام و نام‌خانوادگی: ...................................</td>` +
    `<td style="width:34%;text-align:center">${esc(d.org1 || "وزارت آموزش و پرورش جمهوری اسلامی ایران")}</td>` +
    `<td style="width:33%">تاریخ آزمون: ${esc(d.date || "")}</td>` +
    `</tr><tr>` +
    `<td>نام پدر: ...................................</td>` +
    `<td style="text-align:center">${esc(d.org2 || "")}</td>` +
    `<td>زمان آزمون: ${esc(d.time || "")}</td>` +
    `</tr><tr>` +
    `<td>رشته / پایه: ${esc(d.grade || "")}</td>` +
    `<td>سال تحصیلی: ${esc(d.schoolyear || "")}</td>` +
    `<td>${examTitleFull}</td>` +
    `</tr></table>` +
    `<table class="meta-table" width="100%" style="${tblStyle};margin-top:6px"><tr>` +
    `<td style="width:50%">نام درس: ${esc(d.course || "")}</td>` +
    `<td style="width:50%">${esc(teacherLabel)}: ${esc(d.teacher || "")}</td>` +
    `</tr></table>` +
    `<table class="q" width="100%" style="${tblStyle};margin-top:6px">` +
    `<thead><tr><th class="qnum" style="width:8%">ردیف</th><th style="width:80%">سؤال</th><th style="width:12%">${esc(markLabel)}</th></tr></thead>` +
    `<tbody>` +
    rows.map((r, i) => {
      const spRaw = parseInt(r.space, 10);
      const sp = isNaN(spRaw) ? 90 : spRaw;
      const brCount = sp > 0 ? Math.max(1, Math.round(sp / 35)) : 0;
      return `<tr style="page-break-inside:avoid"><td class="qnum" style="vertical-align:top">${toFaDigitsSrv(i + 1)}</td>` +
        `<td style="vertical-align:top;font-size:${fontSize}pt">${examSheetCleanQ(r.q)}<div style="clear:both;line-height:0;font-size:0">&nbsp;</div>${"<br>".repeat(brCount)}</td>` +
        `<td style="text-align:center;vertical-align:top">${esc(r.mark || "")}</td></tr>`;
    }).join("") +
    `</tbody></table>`;
  return fontWrap(body);
}

function answerLabel(q, ans) {
  if (q.type === "multiple") {
    const idx = Number(ans);
    if (!isNaN(idx) && q.options && q.options[idx] != null) {
      return `${["الف", "ب", "ج", "د"][idx] || idx + 1}) ${esc(q.options[idx])}`;
    }
    return esc(ans);
  }
  if (q.type === "truefalse") {
    if (ans === "true" || ans === true) return "صحیح";
    if (ans === "false" || ans === false) return "غلط";
    return esc(ans);
  }
  return esc(ans);
}

const MARK_LABEL = { correct: "صحیح", wrong: "غلط", partial: "نیمه‌درست" };

function answerSheetWord(sub) {
  const meta = sub.meta || DEFAULT_META;
  const questions = sub.questionsSnapshot || [];
  const g = sub.grading || {};
  const st = sub.student || {};
  let body = wordHeader(meta);
  body +=
    `<table class="meta-table">` +
    `<tr><td>نام و نام خانوادگی: ${esc(st.name)}</td><td>نام پدر: ${esc(st.fatherName)}</td><td>کد ملی: ${esc(st.nationalId)}</td></tr>` +
    `<tr><td>نام درس: ${esc(st.courseName)}</td><td>تاریخ ثبت: ${esc(new Date(sub.submittedAt).toLocaleString("fa-IR"))}</td><td></td></tr>` +
    `</table>`;

  body += `<table class="q"><tr><th class="qnum">ردیف</th><th>سوال</th><th>پاسخ دانش‌آموز</th><th>نمره</th><th>بازخورد معلم</th></tr>`;
  questions.forEach((q, i) => {
    const ans = sub.answers ? sub.answers[q.id] : "";
    const mark = g.marks ? g.marks[q.id] : "";
    const fb = g.feedback ? g.feedback[q.id] : "";
    let qcell = q.rich ? q.text : esc(q.text);
    const qcImg = questionImageWord(q);
    if (qcImg) qcell = q.imagePos === "above" ? qcImg + qcell : qcell + qcImg;
    body +=
      `<tr><td class="qnum">${i + 1}</td>` +
      `<td>${qcell} <small>(${esc(QUESTION_TYPES[q.type] || q.type)})</small></td>` +
      `<td>${ans == null || ans === "" ? "<i>بدون پاسخ</i>" : answerLabel(q, ans)}</td>` +
      `<td>${esc(mark)}</td>` +
      `<td>${esc(fb || "")}</td></tr>`;
  });
  body += `</table>`;
  if (g.overall) body += `<p><b>نتیجه/بازخورد کلی:</b> ${esc(g.overall)}</p>`;
  return body;
}

