  document.getElementById('btn-att-manual-add').onclick=async function(){
    var targetLink=ATT_M_SELECTED_LINK||ATT_SELECTED_LINK;
    if(!targetLink){toast('ابتدا یک لیست را انتخاب کنید');return;}
    var rows=ATT_M_TABLE_ROWS.filter(function(r){return (r.fullname||'').trim();});
    if(!rows.length){toast('حداقل یک سطر با نام و نام خانوادگی پر کنید');return;}
    var btn=this; btn.disabled=true;
    toast('در حال ثبت '+rows.length+' ردیف...');
    // ارسال دسته‌ای (batch) به جای یک‌به‌یک — بسیار سریع‌تر
    var payload=rows.map(function(r){
      var nm=attMSplitName(r.fullname);
      return {linkId:targetLink,name:nm.name,family:nm.family,role:r.role||'',school:r.school||'',region:r.region||'',nationalCode:r.nationalCode||''};
    });
    var d=await api('/api/teacher/attendance-manual-batch',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({rows:payload})});
    if(d&&d.ok){
      var added=d.added||0, failed=d.failed||0;
      // رکوردهای جدید را به لیست محلی اضافه کن
      if(d.results){
        d.results.forEach(function(r){
          if(r.ok&&r.record){
            if(targetLink===ATT_M_SELECTED_LINK)attMLastRecords.unshift(r.record);
            if(targetLink===ATT_SELECTED_LINK)attLastRecords.unshift(r.record);
          }
        });
      }
      if(targetLink===ATT_M_SELECTED_LINK)attMRenderTable();
      if(targetLink===ATT_SELECTED_LINK)attRenderTable();
      attManualClear();
      WBC_ATTENDEES_LOADED=false;
      btn.disabled=false;
      toast(added+' ردیف ثبت شد ✅'+(failed?(' — '+failed+' ردیف ناموفق'):''));
    }else{
      btn.disabled=false;
      toast((d&&d.error)||'خطا در ثبت اطلاعات');
    }
  };
